    <script>
        // Data inisial (diset null agar respon awal HTML ringan ~1.4MB dan cepat <50ms)
        window.__INITIAL_DASHBOARD_DATA__ = null;

        // Bridge kompatibilitas google.script.run untuk lingkungan PHP/Laravel & Vercel
        if (typeof google === 'undefined' || !google.script) {
            window.google = window.google || {};
            (function () {
                const gasExecUrl = 'https://script.google.com/macros/s/AKfycbzsATpz5NB3a6LXaeilqp0cBiIBigCwp5hPzvo88kJqLtEZN8fmp_bZW8Xy-G7KEJJ5/exec';

                function executeApiCall(action, params, onSuccess, onFail) {
                    if (action === 'getDashboardData') {
                        // Ambil data secara asinkron dari Google Apps Script Web App langsung (bebas limit payload Vercel)
                        fetch(gasExecUrl + '?action=getDashboardData')
                            .then(r => {
                                if (!r.ok) throw new Error('GAS HTTP ' + r.status);
                                return r.json();
                            })
                            .then(data => {
                                if (onSuccess) onSuccess(data);
                            })
                            .catch(err => {
                                console.warn('Fetch langsung ke Google Apps Script gagal/terkendala, mencoba fallback API Laravel...', err);
                                fetch('/mata-api/dashboard-data')
                                    .then(r => {
                                        if (!r.ok) throw new Error('Laravel HTTP ' + r.status);
                                        return r.json();
                                    })
                                    .then(data => {
                                        if (onSuccess) onSuccess(data);
                                    })
                                    .catch(e => {
                                        if (onFail) onFail(e);
                                        else console.error('Gagal memuat dataset dashboard:', e);
                                    });
                            });
                        return;
                    }

                    // Panggilan umum (loginUser, getUsers, addUser, updateUser, logActivity, dll.)
                    let url = gasExecUrl + '?action=' + encodeURIComponent(action);
                    if (params) {
                        for (const key in params) {
                            if (params.hasOwnProperty(key) && params[key] !== undefined && params[key] !== null) {
                                url += '&' + encodeURIComponent(key) + '=' + encodeURIComponent(params[key]);
                            }
                        }
                    }

                    fetch(url)
                        .then(r => r.json())
                        .then(res => {
                            if (onSuccess) onSuccess(res);
                        })
                        .catch(err => {
                            if (onFail) onFail(err);
                            else console.warn('GAS call error [' + action + ']:', err);
                        });
                }

                function createRunner(successCb, failCb) {
                    const runner = {
                        withSuccessHandler: function (cb) {
                            return createRunner(cb, failCb);
                        },
                        withFailureHandler: function (cb) {
                            return createRunner(successCb, cb);
                        },
                        getDashboardData: function () {
                            executeApiCall('getDashboardData', {}, successCb, failCb);
                        },
                        loginUser: function (username, password) {
                            executeApiCall('loginUser', { username: username, password: password }, successCb, failCb);
                        },
                        logActivity: function (username, role, activity) {
                            try {
                                executeApiCall('logActivity', { username: username, role: role, activity: activity });
                            } catch (e) {}
                        },
                        getUsers: function () {
                            executeApiCall('getUsers', {}, successCb, failCb);
                        },
                        addUser: function (currentUser, username, password, role, nama) {
                            executeApiCall('addUser', { currentUser: currentUser, username: username, password: password, role: role, nama: nama }, successCb, failCb);
                        },
                        updateUser: function (currentUser, username, password, role, nama) {
                            executeApiCall('updateUser', { currentUser: currentUser, username: username, password: password, role: role, nama: nama }, successCb, failCb);
                        },
                        deleteUser: function (currentUser, username) {
                            executeApiCall('deleteUser', { currentUser: currentUser, username: username }, successCb, failCb);
                        },
                        requestAccess: function (namaLengkap, username, password, unit, role) {
                            executeApiCall('requestAccess', { namaLengkap: namaLengkap, username: username, password: password, unit: unit, role: role }, successCb, failCb);
                        },
                        getColumnVisibilitySettings: function (username) {
                            executeApiCall('getColumnVisibilitySettings', { username: username }, successCb, failCb);
                        },
                        setColumnVisibilitySettings: function (username, hideDetil, hideNotes) {
                            executeApiCall('setColumnVisibilitySettings', { username: username, hideDetil: hideDetil, hideNotes: hideNotes }, successCb, failCb);
                        },
                        getPendingRequests: function () {
                            executeApiCall('getPendingRequests', {}, successCb, failCb);
                        },
                        approveRequest: function (currentUser, id) {
                            executeApiCall('approveRequest', { currentUser: currentUser, id: id }, successCb, failCb);
                        },
                        rejectRequest: function (currentUser, id) {
                            executeApiCall('rejectRequest', { currentUser: currentUser, id: id }, successCb, failCb);
                        },
                        getActivityLogs: function () {
                            executeApiCall('getActivityLogs', {}, successCb, failCb);
                        },
                        exportActivityLogs: function () {
                            executeApiCall('exportActivityLogs', {}, successCb, failCb);
                        }
                    };

                    if (typeof Proxy !== 'undefined') {
                        return new Proxy(runner, {
                            get: function (target, prop) {
                                if (prop in target) return target[prop];
                                return function (...args) {
                                    executeApiCall(prop, { args: JSON.stringify(args) }, successCb, failCb);
                                };
                            }
                        });
                    }

                    return runner;
                }

                window.google.script = {
                    run: createRunner(null, null)
                };
            })();
        }
    </script>
</head>

<body>

    <!-- Watermark username tipis & berulang di seluruh layar, tidak mengganggu klik.
       Diposisikan sebagai anak langsung <body> (bukan di dalam elemen ber-transform)
       supaya position:fixed selalu mengacu ke layar sebenarnya. -->
    <div id="watermarkOverlay"></div>

    <style>
  /* ===================== LOGIN SCREEN (MODERN SPLIT DESIGN - MATA) ===================== */
  #login-container {
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: radial-gradient(circle at 15% 20%, rgba(163, 0, 48, 0.05) 0%, transparent 45%),
                radial-gradient(circle at 85% 80%, rgba(16, 185, 129, 0.05) 0%, transparent 45%),
                #F2F4F7;
    z-index: 10000;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    font-family: 'Poppins', sans-serif;
    padding: 24px;
    opacity: 1;
    overflow-y: auto;
    transition: opacity 0.4s ease, transform 0.4s ease;
  }
  #login-container.fade-out {
    opacity: 0;
    transform: scale(0.97);
    pointer-events: none;
  }

  /* Background animasi partikel koneksi/data-flow monitoring */
  #networkCanvas {
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    z-index: 0;
    pointer-events: none;
  }
  @media (prefers-reduced-motion: reduce) {
    #networkCanvas { display: none; }
    .login-illustration-img { animation: none !important; }
  }

  /* ===================== KARTU UTAMA DUA KOLOM LEBIH BESAR ===================== */
  .login-card {
    position: relative;
    z-index: 1;
    background: #FFFFFF;
    color: #1C2541;
    border-radius: 28px;
    padding: 44px 48px;
    width: 100%;
    max-width: 960px;
    box-shadow: 0 24px 60px -12px rgba(28, 37, 65, 0.10), 0 8px 24px -6px rgba(28, 37, 65, 0.05);
    border: 1px solid rgba(226, 232, 240, 0.9);
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 48px;
    align-items: center;
    transition: box-shadow 0.3s ease;
  }

  /* ===================== KOLOM KIRI (ILUSTRASI & VALUE BAD TICKET) ===================== */
  .login-left-col {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    border-right: 1px solid #F1F3F5;
    padding-right: 44px;
    height: 100%;
  }

  .login-illustration-wrapper {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0 0 16px;
    min-height: 210px;
  }

  .login-illustration-glow {
    position: absolute;
    width: 250px;
    height: 190px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(16, 185, 129, 0.14) 0%, rgba(163, 0, 48, 0.09) 55%, transparent 75%);
    filter: blur(28px);
    pointer-events: none;
    z-index: 0;
    animation: glowPulse 4.5s ease-in-out infinite;
  }
  @keyframes glowPulse {
    0%, 100% { opacity: 0.65; transform: scale(1); }
    50% { opacity: 0.95; transform: scale(1.08); }
  }

  /* Animasi floating gambar 3D ilustrasi (lebih besar & tanpa background kotak) */
  .login-illustration-img {
    position: relative;
    z-index: 1;
    max-width: 295px;
    width: 100%;
    height: auto;
    display: block;
    filter: drop-shadow(0 16px 26px rgba(28, 37, 65, 0.12));
    animation: floatIllustration 4.2s ease-in-out infinite;
    transition: transform 0.35s cubic-bezier(0.2, 0.8, 0.2, 1), filter 0.35s ease;
    cursor: pointer;
  }
  .login-illustration-img:hover {
    transform: translateY(-11px) scale(1.035);
    filter: drop-shadow(0 22px 32px rgba(163, 0, 48, 0.20));
  }
  @keyframes floatIllustration {
    0%, 100% {
      transform: translateY(0px) rotate(0deg);
    }
    50% {
      transform: translateY(-10px) rotate(0.4deg);
    }
  }

  /* Banner BAD TICKET */
  .bad-ticket-banner {
    background: #FFFFFF;
    border: 1px solid #EEF2F6;
    border-radius: 16px;
    padding: 12px 18px;
    display: flex;
    align-items: center;
    gap: 14px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.02);
    transition: transform 0.2s, box-shadow 0.2s;
  }
  .bad-ticket-banner:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.05);
  }
  .bad-ticket-icon-badge {
    width: 40px;
    height: 40px;
    border-radius: 12px;
    background: #FFF1F2;
    border: 1px solid #FFE4E6;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }
  .bad-ticket-icon-badge i {
    color: #E11D48;
    font-size: 17px;
  }
  .bad-ticket-text {
    text-align: left;
    line-height: 1.25;
  }
  .bad-ticket-label {
    font-size: 0.72rem;
    font-weight: 700;
    color: #8898AA;
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }
  .bad-ticket-value {
    font-size: 1.05rem;
    margin-top: 2px;
  }
  .bad-ticket-value .zero-text {
    font-weight: 800;
    color: #1E293B;
  }
  .bad-ticket-value .bad-ticket-green {
    font-weight: 700;
    color: #059669;
  }

  /* 3 Mini Cards (Identify, Correct, Prevent) */
  .feature-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin-top: 14px;
  }
  .feature-card {
    background: #FFFFFF;
    border: 1px solid #EEF2F6;
    border-radius: 14px;
    padding: 13px 8px;
    text-align: center;
    transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.015);
  }
  .feature-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.06);
    border-color: #E2E8F0;
  }
  .feature-icon-badge {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    margin: 0 auto 7px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .feature-icon-badge.badge-pink {
    background: #FFF1F2;
    color: #E11D48;
  }
  .feature-icon-badge.badge-green {
    background: #ECFDF5;
    color: #10B981;
  }
  .feature-icon-badge i {
    font-size: 15px;
  }
  .feature-title {
    font-weight: 700;
    font-size: 0.85rem;
    color: #1E293B;
    line-height: 1.2;
  }
  .feature-desc {
    font-size: 0.70rem;
    color: #8898AA;
    margin-top: 3px;
    line-height: 1.2;
  }

  /* Divider dan Kutipan Motivasi di Kolom Kiri */
  .login-left-divider {
    border-top: 1px solid #F1F3F5;
    margin-top: 22px;
    margin-bottom: 14px;
  }
  .login-quote-box {
    text-align: center;
    padding: 0 6px;
  }
  .login-quote-text {
    font-size: 0.82rem;
    font-style: italic;
    color: #64748B;
    font-weight: 500;
    line-height: 1.6;
    margin: 0;
    opacity: 1;
    transition: opacity 0.5s ease;
  }
  .login-quote-text.fading {
    opacity: 0;
  }
  .login-quote-text::before { content: '\201C'; }
  .login-quote-text::after { content: '\201D'; }

  /* ===================== KOLOM KANAN (FORM LOGIN & BRAND HEADER) ===================== */
  .login-right-col {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    padding-left: 10px;
    width: 100%;
  }

  .login-form-inner {
    width: 100%;
    max-width: 370px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
  }

  .login-brand-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 12px;
    filter: drop-shadow(0 4px 14px rgba(163, 0, 48, 0.22));
    transition: transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
  }
  .login-brand-icon:hover {
    transform: scale(1.08) rotate(3deg);
  }

  .login-title {
    font-weight: 800;
    font-size: 2rem;
    letter-spacing: -0.015em;
    color: #A30030;
    margin-bottom: 4px;
    line-height: 1.2;
  }

  .login-expansion {
    font-size: 0.86rem;
    color: #64748B;
    font-weight: 500;
    margin-bottom: 26px;
    letter-spacing: 0.01em;
  }

  .login-field-group {
    text-align: left;
    margin-bottom: 16px;
  }
  .login-field-label {
    display: block;
    font-size: 0.80rem;
    font-weight: 700;
    color: #334155;
    margin-bottom: 7px;
  }
  .login-forgot-link {
    font-size: 0.78rem;
    font-weight: 700;
    color: #A30030;
    text-decoration: none;
    transition: color 0.2s, text-decoration 0.2s;
  }
  .login-forgot-link:hover {
    color: #7E0025;
    text-decoration: underline;
  }

  .login-input-wrap {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #F8FAFC;
    border: 1.5px solid #E2E8F0;
    border-radius: 14px;
    padding: 13px 16px;
    transition: border-color 0.2s, box-shadow 0.2s, background-color 0.2s;
  }
  .login-input-wrap:focus-within {
    background: #FFFFFF;
    border-color: #A30030;
    box-shadow: 0 0 0 3.5px rgba(163, 0, 48, 0.12);
  }
  .login-input-wrap i {
    color: #94A3B8;
    font-size: 1.05rem;
    width: 18px;
    text-align: center;
  }
  .login-input-wrap input {
    border: none;
    outline: none;
    background: transparent;
    width: 100%;
    font-family: 'Poppins', sans-serif;
    font-size: 0.95rem;
    color: #1E293B;
    font-weight: 500;
  }
  .login-input-wrap input::placeholder {
