  }

  .toggle-password-btn {
    background: none;
    border: none;
    padding: 0;
    color: #94A3B8;
    font-size: 1.05rem;
    cursor: pointer;
    line-height: 1;
    transition: color 0.2s;
  }
  .toggle-password-btn:hover {
    color: #A30030;
  }

  .login-btn {
    background: #A30030;
    color: #FFFFFF;
    font-weight: 700;
    font-size: 1.02rem;
    border: none;
    border-radius: 14px;
    width: 100%;
    padding: 14px;
    margin-top: 6px;
    font-family: 'Poppins', sans-serif;
    transition: all 0.25s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    cursor: pointer;
  }
  .login-btn:hover:not(:disabled) {
    background: #800026;
    box-shadow: 0 10px 24px rgba(163, 0, 48, 0.28);
    transform: translateY(-1px);
  }
  .login-btn:active:not(:disabled) {
    transform: translateY(0);
  }
  .login-btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
  }

  .login-footer-link {
    margin-top: 20px;
    font-size: 0.85rem;
    color: #64748B;
    font-weight: 500;
  }
  .login-footer-link a {
