  /* ===================== LOADER PERSENTASE ===================== */
  #loader {
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: #F2F4F7;
    z-index: 9999;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
