    transform: translateY(0) scale(1);
  }
  .loader-eye {
    margin-bottom: 18px;
  }
  .loader-eye svg { width: 42px; height: 28px; }
  .progress-radial {
    position: relative;
    width: 180px;
    height: 180px;
    border-radius: 50%;
    background: conic-gradient(#A30030 0%, #E9EBEF 0%);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background 0.05s linear;
  }
  .progress-radial-inner {
    width: 152px;
    height: 152px;
    background: #FFFFFF;
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    box-shadow: inset 0 2px 8px rgba(0,0,0,0.05);
  }
  .loader-label {
    color: #A30030;
    font-weight: 800;
    font-size: 0.95rem;
    letter-spacing: 0.03em;
    margin-bottom: 4px;
  }
  .progress-text {
    font-size: 1.9rem;
    font-weight: 800;
    color: #1C2541;
  }
  .loader-caption {
    color: #6B7280;
    font-size: 0.82rem;
    font-weight: 500;
    margin-top: 20px;
    text-align: center;
  }
</style>

<!-- 1. HALAMAN LOGIN UTAMA (MODERN TWO-COLUMN CARD) -->
<div id="login-container">
  <canvas id="networkCanvas"></canvas>

  <div class="login-card">

