    <!-- ================= KOLOM KANAN ================= -->
    <div class="login-right-col">
      <div class="login-form-inner">
        <!-- Brand Header MATA -->
        <div class="login-brand-header text-center">
          <div class="login-brand-icon" title="Dashboard MATA">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" width="56" height="56" fill="none">
              <defs>
                <linearGradient id="mataLoginGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stop-color="#FF3366"/>
                  <stop offset="100%" stop-color="#800020"/>
                </linearGradient>
                <linearGradient id="irisLoginGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stop-color="#F59E0B"/>
                  <stop offset="100%" stop-color="#D97706"/>
                </linearGradient>
                <filter id="mataLoginGlow" x="-20%" y="-20%" width="140%" height="140%">
                  <feDropShadow dx="0" dy="3" stdDeviation="4" flood-color="#E11D48" flood-opacity="0.35"/>
                </filter>
              </defs>
              <rect x="2" y="2" width="44" height="44" rx="14" fill="url(#mataLoginGrad)" filter="url(#mataLoginGlow)" stroke="rgba(255,255,255,0.25)" stroke-width="1.5"/>
              <path d="M8 24C13 16 35 16 40 24C35 32 13 32 8 24Z" fill="none" stroke="#FFFFFF" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>
              <circle cx="24" cy="24" r="7.5" fill="url(#irisLoginGrad)" stroke="#FFFFFF" stroke-width="1.6"/>
              <circle cx="24" cy="24" r="3.2" fill="#FFFFFF"/>
              <circle cx="25.2" cy="22.8" r="1.1" fill="#800020"/>
              <line x1="24" y1="12.5" x2="24" y2="15" stroke="#FBBF24" stroke-width="2" stroke-linecap="round"/>
              <line x1="24" y1="33" x2="24" y2="35.5" stroke="#FBBF24" stroke-width="2" stroke-linecap="round"/>
              <line x1="12.5" y1="24" x2="15" y2="24" stroke="#FBBF24" stroke-width="2" stroke-linecap="round"/>
              <line x1="33" y1="24" x2="35.5" y2="24" stroke="#FBBF24" stroke-width="2" stroke-linecap="round"/>
            </svg>
          </div>
          <h2 class="login-title">Dashboard MATA</h2>
          <p class="login-expansion">(Monitoring Akurasi Tiket &amp; Action)</p>
        </div>

        <!-- Alert Notifikasi Error -->
        <div id="loginAlert" class="alert alert-danger d-none p-2 small" role="alert" style="border-radius:12px; font-family:'Poppins',sans-serif;">
          Username atau Password salah!
        </div>

        <!-- Input Form -->
        <div class="login-field-group">
          <label class="login-field-label">Username</label>
          <div class="login-input-wrap">
            <i class="fa-regular fa-user"></i>
            <input type="text" id="loginUser" placeholder="Masukkan username" autocomplete="username">
          </div>
        </div>

        <div class="login-field-group">
          <div class="d-flex justify-content-between align-items-center mb-1">
            <label class="login-field-label mb-0">Password</label>
            <a href="#" onclick="handleForgotPassword(); return false;" class="login-forgot-link">Lupa Password?</a>
          </div>
          <div class="login-input-wrap">
            <i class="fa-solid fa-lock"></i>
            <input type="password" id="loginPass" placeholder="Masukkan password" autocomplete="current-password" onkeydown="if(event.key==='Enter') handleLogin()">
            <button type="button" class="toggle-password-btn" id="togglePasswordBtn" onclick="togglePasswordVisibility()" aria-label="Tampilkan/sembunyikan password">
              <i class="fa-regular fa-eye" id="togglePasswordIcon"></i>
            </button>
          </div>
        </div>

        <!-- Tombol Login -->
        <button class="login-btn" id="btnLogin" onclick="handleLogin()">
          <span>Login</span> <span style="font-size:1.15rem; line-height:1;">&rarr;</span>
        </button>

        <!-- Link Request Akses -->
        <div class="login-footer-link">
          Belum punya akses?
          <a href="#" onclick="openRequestAccessModal(); return false;">Request Akses</a>
        </div>
      </div>
    </div>

  </div>
</div>

<!-- MODAL LUPA PASSWORD -->
<div id="forgot-modal-backdrop" onclick="if(event.target===this) closeForgotPasswordModal()">
  <div class="forgot-card">
    <div style="width:52px; height:52px; border-radius:14px; background:#FFF1F2; color:#A30030; display:flex; align-items:center; justify-content:center; margin:0 auto 16px; font-size:22px;">
      <i class="fa-solid fa-key"></i>
    </div>
    <h4 style="font-weight:800; font-size:1.25rem; color:#1E293B; margin-bottom:8px;">Bantuan Password</h4>
    <p style="font-size:0.86rem; color:#64748B; line-height:1.55; margin-bottom:22px;">
      Untuk keamanan sistem MATA, reset atau pemulihan password dilakukan melalui <strong>Superadmin</strong>. Anda juga dapat mengajukan ulang melalui fitur <strong>Request Akses</strong>.
    </p>
    <div style="display:flex; gap:12px;">
      <button type="button" class="btn btn-outline-secondary w-50" style="border-radius:12px; font-weight:600; font-size:0.88rem;" onclick="closeForgotPasswordModal()">Tutup</button>
      <button type="button" class="btn w-50" style="background:#A30030; color:#fff; border-radius:12px; font-weight:600; font-size:0.88rem;" onclick="closeForgotPasswordModal(); openRequestAccessModal();">Request Akses</button>
    </div>
  </div>
</div>

<!-- 1.4 LAYAR REQUEST AKSES (CSDM, NAMA & PASSWORD) -->
<div id="request-access-container">
  <div class="source-card" style="text-align:left;">
    <div class="text-center">
      <div style="width:52px; height:52px; border-radius:14px; background:#FFF1F2; color:#A30030; display:inline-flex; align-items:center; justify-content:center; margin-bottom:14px; font-size:24px;">
        <i class="fa-solid fa-user-plus"></i>
      </div>
      <h3 class="source-select-title">Request Akses</h3>
      <p class="source-select-subtitle">Masukkan CSDM dan Password untuk mengajukan akses. Permintaan akan diverifikasi oleh Superadmin.</p>
    </div>

    <div id="requestAccessAlert" class="alert alert-danger d-none p-2 small" role="alert" style="border-radius:12px; font-family:'Poppins',sans-serif;"></div>
    <div id="requestAccessSuccess" class="alert alert-success d-none p-2 small" role="alert" style="border-radius:12px; font-family:'Poppins',sans-serif;"></div>

    <div id="requestAccessForm">
      <div class="login-field-group">
        <label class="login-field-label">CSDM</label>
        <div class="login-input-wrap">
          <i class="fa-solid fa-id-badge"></i>
          <input type="text" id="reqCsdm" inputmode="numeric" pattern="[0-9]*" maxlength="20" placeholder="Masukkan CSDM (angka)" oninput="this.value = this.value.replace(/[^0-9]/g, '')">
        </div>
      </div>
      <div class="login-field-group">
        <label class="login-field-label">Nama</label>
        <div class="login-input-wrap">
          <i class="fa-regular fa-user"></i>
          <input type="text" id="reqNama" placeholder="Masukkan nama lengkap">
        </div>
      </div>
      <div class="login-field-group">
        <label class="login-field-label">Password</label>
        <div class="login-input-wrap">
          <i class="fa-solid fa-lock"></i>
          <input type="password" id="reqPassword" placeholder="Buat password" onkeydown="if(event.key==='Enter') submitRequestAccess()">
          <button type="button" class="toggle-password-btn" onclick="toggleReqPasswordVisibility()" aria-label="Tampilkan/sembunyikan password">
            <i class="fa-regular fa-eye" id="reqPasswordToggleIcon"></i>
          </button>
        </div>
      </div>
      <button class="login-btn" id="btnRequestAccess" onclick="submitRequestAccess()">Kirim Permintaan</button>
    </div>

    <div class="text-center mt-3">
      <a href="#" onclick="backToLoginFromRequest(); return false;" style="color:#64748B; font-size:0.85rem; font-weight:600; text-decoration:none;">
        <i class="fa-solid fa-arrow-left me-1"></i> Kembali ke Login
      </a>
    </div>
  </div>
</div>

<!-- 2. SCREEN LOADING DENGAN PERSENTASE (SETELAH LOGIN BERHASIL) -->
<div id="loader" style="display: none;">
  <div class="loader-card">
    <div class="loader-eye">
      <svg viewBox="0 0 40 24" xmlns="http://www.w3.org/2000/svg">
        <path d="M2 12 C 9 -1, 31 -1, 38 12 C 31 25, 9 25, 2 12 Z" fill="none" stroke="#A30030" stroke-width="2.2" stroke-linejoin="round"/>
        <circle cx="20" cy="12" r="6" fill="#A30030"/>
        <circle cx="22" cy="9.5" r="2" fill="#FFFFFF"/>
      </svg>
    </div>
    <div class="progress-radial" id="radialBg">
      <div class="progress-radial-inner">
        <div class="loader-label">I'm Perfect</div>
        <div class="progress-text" id="loadPercent">0%</div>
      </div>
    </div>
    <div class="loader-caption">Mohon tunggu, sistem sedang menyiapkan dashboard...</div>
  </div>
</div>

<script>
  // Data akun yang sedang login, dipakai di seluruh halaman (termasuk Index.html)
  let currentUsername = '';
  let currentUserRole = '';

  // ===================== QUOTE MOTIVASI, BERGANTI OTOMATIS ===================== //
  const ADAPTIVE_QUOTES = [
    'Bukan yang terkuat yang bertahan, melainkan yang paling adaptif terhadap perubahan.',
    'Data yang akurat hari ini adalah keputusan yang tepat untuk esok hari.',
    'Perubahan adalah satu-satunya hal yang pasti. Yang membedakan adalah seberapa cepat kita beradaptasi.',
    'Setiap tiket yang kita pantau adalah satu langkah menuju layanan yang lebih baik.',
    'Konsistensi kecil setiap hari menghasilkan perubahan besar dalam jangka panjang.',
    'Ketelitian hari ini mencegah kesalahan berulang di kemudian hari.',
    'Adaptif bukan berarti berubah arah, tapi tetap fokus sambil menyesuaikan cara.',
    'Progres terbaik lahir dari kebiasaan memeriksa, bukan sekadar berharap.'
  ];
  let quoteIndex = 0;

  function rotateQuote() {
    const quoteEl = document.getElementById('loginQuote');
    if (!quoteEl) return;
    quoteEl.classList.add('fading');
    setTimeout(function () {
      quoteIndex = (quoteIndex + 1) % ADAPTIVE_QUOTES.length;
      quoteEl.innerText = ADAPTIVE_QUOTES[quoteIndex];
      quoteEl.classList.remove('fading');
    }, 500);
  }
  document.getElementById('loginQuote') && (document.getElementById('loginQuote').innerText = ADAPTIVE_QUOTES[0]);
  setInterval(rotateQuote, 7000);

  // ===================== BACKGROUND ABSTRAK: NETWORK / DATA FLOW ===================== //
  function initNetworkBackground() {
    const canvas = document.getElementById('networkCanvas');
    if (!canvas || !canvas.getContext) return;
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    const ctx = canvas.getContext('2d');
    let width, height, particles;
    const PARTICLE_COUNT = 40;
    const MAX_DIST = 135;

    function resize() {
      width = canvas.width = canvas.offsetWidth;
      height = canvas.height = canvas.offsetHeight;
    }
    window.addEventListener('resize', resize);
    resize();

    particles = Array.from({ length: PARTICLE_COUNT }, function () {
      return {
        x: Math.random() * width,
        y: Math.random() * height,
        vx: (Math.random() - 0.5) * 0.22,
        vy: (Math.random() - 0.5) * 0.22
      };
    });

    function isLoginVisible() {
      const el = document.getElementById('login-container');
      return el && el.style.display !== 'none' && !el.classList.contains('fade-out');
    }

    function tick() {
      requestAnimationFrame(tick);
      if (!isLoginVisible()) return;

      ctx.clearRect(0, 0, width, height);

      particles.forEach(function (p) {
        p.x += p.vx;
        p.y += p.vy;
        if (p.x <= 0 || p.x >= width) p.vx *= -1;
        if (p.y <= 0 || p.y >= height) p.vy *= -1;
      });

      for (let i = 0; i < particles.length; i++) {
        for (let j = i + 1; j < particles.length; j++) {
          const dx = particles[i].x - particles[j].x;
          const dy = particles[i].y - particles[j].y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < MAX_DIST) {
            const alpha = (1 - dist / MAX_DIST) * 0.14;
            ctx.strokeStyle = 'rgba(163, 0, 48, ' + alpha + ')';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(particles[i].x, particles[i].y);
            ctx.lineTo(particles[j].x, particles[j].y);
            ctx.stroke();
          }
        }
      }
      particles.forEach(function (p) {
        ctx.fillStyle = 'rgba(28, 37, 65, 0.35)';
        ctx.beginPath();
        ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
        ctx.fill();
      });
    }
    requestAnimationFrame(tick);
  }
  initNetworkBackground();

  // Toggle Password
  function togglePasswordVisibility() {
    const input = document.getElementById('loginPass');
    const icon = document.getElementById('togglePasswordIcon');
    const isHidden = input.type === 'password';
    input.type = isHidden ? 'text' : 'password';
    icon.classList.toggle('fa-eye', !isHidden);
    icon.classList.toggle('fa-eye-slash', isHidden);
  }

  // Modal Lupa Password
  function handleForgotPassword() {
    const modal = document.getElementById('forgot-modal-backdrop');
    if (modal) {
      modal.style.display = 'flex';
      void modal.offsetWidth;
      modal.classList.add('show');
    }
  }
  function closeForgotPasswordModal() {
    const modal = document.getElementById('forgot-modal-backdrop');
    if (modal) {
      modal.classList.remove('show');
      setTimeout(function() {
        modal.style.display = 'none';
      }, 300);
    }
  }

  // Handle Login Server
  function handleLogin() {
    const u = document.getElementById('loginUser').value.trim();
    const p = document.getElementById('loginPass').value.trim();
    const alertBox = document.getElementById('loginAlert');
    const btn = document.getElementById('btnLogin');

    if (u === "" || p === "") {
      alertBox.innerText = "Username dan Password wajib diisi!";
      alertBox.classList.remove('d-none');
      return;
    }

    alertBox.classList.add('d-none');
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin me-2"></i>Memeriksa...';

    // Cek apakah di Google Apps Script environment
    if (typeof google !== 'undefined' && google.script && google.script.run) {
      google.script.run
        .withSuccessHandler(function (result) {
          if (result && result.success) {
            currentUsername = result.username || u;
            currentUserRole = result.role || 'user';
            if (google.script.run.logActivity && String(currentUsername).trim().toLowerCase() !== 'superadmin') {
              google.script.run.logActivity(currentUsername, currentUserRole, 'Login');
            }
            transitionToDashboard();
          } else {
            alertBox.innerText = (result && result.pending)
              ? "Akun Anda masih menunggu persetujuan Superadmin."
              : "Username atau Password salah!";
            alertBox.classList.remove('d-none');
            btn.disabled = false;
            btn.innerHTML = '<span>Login</span> <span style="font-size:1.15rem; line-height:1;">&rarr;</span>';
          }
        })
        .withFailureHandler(function (error) {
          alertBox.innerText = "Terjadi kesalahan sistem, coba lagi.";
          alertBox.classList.remove('d-none');
          btn.disabled = false;
          btn.innerHTML = '<span>Login</span> <span style="font-size:1.15rem; line-height:1;">&rarr;</span>';
          console.error(error);
        })
        .validateLogin(u, p);
    } else {
      // Fallback preview lokal
      setTimeout(function() {
        currentUsername = u;
        currentUserRole = 'superadmin';
        transitionToDashboard();
      }, 700);
    }
  }

  function transitionToDashboard() {
    const loginEl = document.getElementById('login-container');
    loginEl.classList.add('fade-out');

    setTimeout(function () {
      loginEl.style.display = 'none';

      const loaderEl = document.getElementById('loader');
      loaderEl.style.display = 'flex';
      void loaderEl.offsetWidth;
      loaderEl.classList.add('show');

      runFakeLoader(function () {
        const dash = document.getElementById('dashboard-wrapper');
        if (dash) {
          dash.style.display = 'block';
          void dash.offsetWidth;
          dash.classList.add('visible');
        }
        if (typeof applyUserRoleUI === 'function') applyUserRoleUI();
        if (typeof applyWatermark === 'function') applyWatermark(currentUsername);
        if (typeof loadDataFromBackend === 'function') loadDataFromBackend();
        if (typeof startIdleTimer === 'function') startIdleTimer();
      });
    }, 380);
  }

  // Request Access
  function openRequestAccessModal() {
    const loginEl = document.getElementById('login-container');
    const reqEl = document.getElementById('request-access-container');

    document.getElementById('reqCsdm').value = '';
    document.getElementById('reqNama').value = '';
    document.getElementById('reqPassword').value = '';
    document.getElementById('requestAccessAlert').classList.add('d-none');
    document.getElementById('requestAccessSuccess').classList.add('d-none');
    document.getElementById('requestAccessForm').style.display = 'block';
    const btnReq = document.getElementById('btnRequestAccess');
    btnReq.disabled = false;
    btnReq.innerHTML = 'Kirim Permintaan';

    loginEl.classList.add('fade-out');
    setTimeout(function () {
      loginEl.style.display = 'none';
      reqEl.style.display = 'flex';
      void reqEl.offsetWidth;
      reqEl.classList.add('show');
    }, 380);
  }

  function backToLoginFromRequest() {
    const reqEl = document.getElementById('request-access-container');
    const loginEl = document.getElementById('login-container');

    reqEl.classList.remove('show');
    setTimeout(function () {
      reqEl.style.display = 'none';
      loginEl.style.display = 'flex';
      loginEl.classList.remove('fade-out');
      void loginEl.offsetWidth;
    }, 380);
  }

  function toggleReqPasswordVisibility() {
    const input = document.getElementById('reqPassword');
    const icon = document.getElementById('reqPasswordToggleIcon');
    const isHidden = input.type === 'password';
    input.type = isHidden ? 'text' : 'password';
    icon.classList.toggle('fa-eye', !isHidden);
    icon.classList.toggle('fa-eye-slash', isHidden);
  }

  function submitRequestAccess() {
    const csdm = document.getElementById('reqCsdm').value.trim();
    const nama = document.getElementById('reqNama').value.trim();
    const pass = document.getElementById('reqPassword').value.trim();
    const alertBox = document.getElementById('requestAccessAlert');
    alertBox.classList.add('d-none');

    if (!csdm || !nama || !pass) {
      alertBox.innerText = 'CSDM, Nama, dan Password wajib diisi.';
      alertBox.classList.remove('d-none');
      return;
    }
    if (!/^[0-9]+$/.test(csdm)) {
      alertBox.innerText = 'CSDM harus berupa angka saja.';
      alertBox.classList.remove('d-none');
      return;
    }

    const btn = document.getElementById('btnRequestAccess');
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin me-2"></i>Mengirim...';

    if (typeof google !== 'undefined' && google.script && google.script.run) {
      google.script.run
        .withSuccessHandler(function (res) {
          if (res && res.success) {
            document.getElementById('requestAccessForm').style.display = 'none';
            const successBox = document.getElementById('requestAccessSuccess');
            successBox.innerText = 'Permintaan akses berhasil dikirim. Silakan tunggu persetujuan dari Superadmin.';
            successBox.classList.remove('d-none');
          } else {
            btn.disabled = false;
            btn.innerHTML = 'Kirim Permintaan';
            alertBox.innerText = (res && res.error) ? res.error : 'Gagal mengirim permintaan.';
            alertBox.classList.remove('d-none');
          }
        })
        .withFailureHandler(function (err) {
          btn.disabled = false;
          btn.innerHTML = 'Kirim Permintaan';
          alertBox.innerText = 'Terjadi kesalahan sistem, coba lagi.';
          alertBox.classList.remove('d-none');
          console.error(err);
        })
        .requestAccess(csdm, nama, pass);
    } else {
      setTimeout(function() {
        document.getElementById('requestAccessForm').style.display = 'none';
        const successBox = document.getElementById('requestAccessSuccess');
        successBox.innerText = 'Permintaan akses berhasil dikirim (mode preview).';
        successBox.classList.remove('d-none');
      }, 700);
    }
  }

  // Loading radial progress
  function runFakeLoader(callback) {
    let percent = 0;
    const interval = setInterval(function () {
      percent += 5;
      const pctEl = document.getElementById('loadPercent');
      if (pctEl) pctEl.innerText = percent + "%";
      const radBg = document.getElementById('radialBg');
      if (radBg) {
        radBg.style.background = 'conic-gradient(#A30030 ' + percent + '%, #E9EBEF ' + percent + '%)';
      }
      if (percent >= 100) {
        clearInterval(interval);
        const loaderEl = document.getElementById('loader');
        if (loaderEl) loaderEl.classList.remove('show');
        setTimeout(function () {
          if (loaderEl) loaderEl.style.display = 'none';
          if (callback) callback();
        }, 380);
      }
    }, 20);
  }
</script>

    <!-- 3. DASHBOARD UTAMA -->
    <div id="dashboard-wrapper">
                <div class="top-header-bar">
            <div class="d-flex align-items-center gap-3">
                <button class="btn-sidebar-toggle" id="btnToggleSidebarMinimize" onclick="toggleSidebarMinimize()"
                    title="Perkecil / Perbesar Sidebar">
                    <i class="fa-solid fa-bars-staggered"></i>
                </button>
                <div class="mata-header-logo" title="Dashboard MATA (Monitoring Akurasi Tiket & Action)">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" width="38" height="38" fill="none">
                  <defs>
                    <linearGradient id="mataGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                      <stop offset="0%" stop-color="#FF3366"/>
                      <stop offset="100%" stop-color="#800020"/>
                    </linearGradient>
                    <linearGradient id="irisGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                      <stop offset="0%" stop-color="#F59E0B"/>
                      <stop offset="100%" stop-color="#D97706"/>
                    </linearGradient>
                    <filter id="mataGlow" x="-20%" y="-20%" width="140%" height="140%">
                      <feDropShadow dx="0" dy="2" stdDeviation="3" flood-color="#E11D48" flood-opacity="0.45"/>
                    </filter>
                  </defs>
                  <rect x="2" y="2" width="44" height="44" rx="13" fill="url(#mataGrad)" filter="url(#mataGlow)" stroke="rgba(255,255,255,0.25)" stroke-width="1.5"/>
                  <path d="M8 24C13 16 35 16 40 24C35 32 13 32 8 24Z" fill="none" stroke="#FFFFFF" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>
                  <circle cx="24" cy="24" r="7.5" fill="url(#irisGrad)" stroke="#FFFFFF" stroke-width="1.6"/>
                  <circle cx="24" cy="24" r="3.2" fill="#FFFFFF"/>
                  <circle cx="25.2" cy="22.8" r="1.1" fill="#800020"/>
                  <line x1="24" y1="12.5" x2="24" y2="15" stroke="#FBBF24" stroke-width="2" stroke-linecap="round"/>
                  <line x1="24" y1="33" x2="24" y2="35.5" stroke="#FBBF24" stroke-width="2" stroke-linecap="round"/>
                  <line x1="12.5" y1="24" x2="15" y2="24" stroke="#FBBF24" stroke-width="2" stroke-linecap="round"/>
                  <line x1="33" y1="24" x2="35.5" y2="24" stroke="#FBBF24" stroke-width="2" stroke-linecap="round"/>
                </svg>
                </div>
                <div>
                    <div class="d-flex align-items-center gap-2 flex-wrap">
                        <h1 class="top-header-title">Dashboard MATA</h1>
                        <span class="top-header-tagline">(Monitoring Akurasi Tiket &amp; Action)</span>
                    </div>
                    <div class="top-header-sub" id="topHeaderDateTime">-</div>
                </div>
            </div>
            <div class="top-header-right">
                <!-- DOMAIN / SERVICE TOGGLE SWITCHER (FIXED / MOBILE) -->
                <div class="domain-switch-container d-none d-md-flex align-items-center me-2">
                    <div class="domain-switch-pill" role="tablist" title="Pilih Produk: Fixed atau Mobile">
                        <button type="button" class="domain-btn active btn-domain-fixed" id="topBtnDomainFixed" onclick="switchDomain('fixed')">
                            <i class="fa-solid fa-wifi"></i> <span>Fixed</span>
                        </button>
                        <button type="button" class="domain-btn btn-domain-mobile" id="topBtnDomainMobile" onclick="switchDomain('mobile')">
                            <i class="fa-solid fa-mobile-screen-button"></i> <span>Mobile</span>
                        </button>
                    </div>
                </div>

                <span class="top-header-page-indicator" id="topHeaderPageIndicator">
                    <i class="fa-solid fa-chart-pie me-1"></i> Dashboard
                </span>
                <div class="top-header-user-badge" id="topHeaderUserBadge" style="display:none;">
                    <div class="top-header-user-avatar">
                        <i class="fa-solid fa-user-shield"></i>
                    </div>
                    <div class="top-header-user-meta">
