    <!-- html2canvas TIDAK di-load di sini lagi (lazy-load hanya saat tombol "Unduh PNG" pertama kali diklik) -->
    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
    <script>
        // Helper sensor masking 5 digit terakhir pada Kolom N (Notes by Solver / Catatan Solver)
        // Kategori: nomor 10-12 digit (misal: 0812345678 -> 08123*****, 02122412345 -> 021224*****, 
        // 143423112345 -> 1434231*****, 081326812345 -> 0813268*****) & dengan prefiks KM (KM34241112345 -> KM342411*****)
        function maskNotesKolomN(text) {
            if (!text) return text === 0 ? '0' : (text || '');
            const str = String(text);
            // 1. KM diikuti 10, 11, atau 12 digit (KM + 5-7 digit depan + 5 digit bintang)
            let res = str.replace(/\b(KM[\s:-]?)(\d{5,7})(\d{5})\b/gi, function(match, p1, p2) {
                return p1 + p2 + '*****';
            });
            // 2. Angka murni 10, 11, atau 12 digit (5-7 digit depan + 5 digit bintang)
            res = res.replace(/\b(\d{5,7})(\d{5})\b/g, function(match, p1) {
                return p1 + '*****';
            });
            return res;
        }

        let allRecords = [];
        let currentDomain = 'fixed'; // 'fixed' | 'mobile'
        let activeAppPage = 'dashboard';
        let allDatasets = {
            fixed: { records: [], filters: { tanggal: [], bulan: [], tahun: [], unit: [], sourceBy: [] } },
            mobile: { records: [], filters: { tanggal: [], bulan: [], tahun: [], unit: [], sourceBy: [] } }
        };
        let activeCharts = {};
        let currentFilteredRecords = [];
        let agentModalBootstrap;
        let breakdownModalBootstrap;
        let currentBreakdownFiltered = [];
        let userFormBootstrap;
        let userFormMode = 'add'; // 'add' | 'edit'
        let userFormEditingUsername = '';
        let currentBreakdownAgentName = '';
        let hasSearched = false;
        let bulanTerurutGlobal = [];

        const urutanBulanIndo = {
            "JANUARI": 1, "FEBRUARI": 2, "MARET": 3, "APRIL": 4, "MEI": 5, "JUNI": 6,
            "JULI": 7, "AGUSTUS": 8, "SEPTEMBER": 9, "OKTOBER": 10, "NOVEMBER": 11, "DESEMBER": 12
        };
        const singkatanBulanIndo = {
            "JANUARI": "Jan", "FEBRUARI": "Feb", "MARET": "Mar", "APRIL": "Apr", "MEI": "Mei", "JUNI": "Jun",
            "JULI": "Jul", "AGUSTUS": "Agu", "SEPTEMBER": "Sep", "OKTOBER": "Okt", "NOVEMBER": "Nov", "DESEMBER": "Des"
        };

        // Helper mengecek apakah tiket berstatus "SANGGAHAN DITERIMA" pada Kolom O (Final Status / row[14])
        function isSanggahanDiterima(row) {
            if (!row || row.length <= 14 || row[14] === undefined || row[14] === null) return false;
            const st = String(row[14]).trim().toUpperCase();
            return st === 'SANGGAHAN DITERIMA' || st.includes('SANGGAHAN DITERIMA') || st === 'SANGGAHAN DISETUJUI';
        }
        function sortBulanIndo(arr) {
            return [...arr].sort((a, b) => {
                let keyA = String(a).toUpperCase().trim();
                let keyB = String(b).toUpperCase().trim();
                return (urutanBulanIndo[keyA] || 99) - (urutanBulanIndo[keyB] || 99);
            });
        }

        // Registrasi plugin chartjs-plugin-datalabels & standardisasi tampilan grafik modern
        if (typeof ChartDataLabels !== 'undefined') {
            Chart.register(ChartDataLabels);
            Chart.defaults.set('plugins.datalabels', { display: false });
        }
        Chart.defaults.font.family = 'Poppins';
        Chart.defaults.color = '#64748B';
        if (Chart.defaults.plugins && Chart.defaults.plugins.tooltip) {
            Chart.defaults.plugins.tooltip.backgroundColor = '#0F172A';
            Chart.defaults.plugins.tooltip.titleColor = '#F8FAFC';
            Chart.defaults.plugins.tooltip.bodyColor = '#F1F5F9';
            Chart.defaults.plugins.tooltip.titleFont = { family: 'Poppins', size: 12, weight: '600' };
            Chart.defaults.plugins.tooltip.bodyFont = { family: 'Poppins', size: 11, weight: '400' };
            Chart.defaults.plugins.tooltip.padding = { top: 8, right: 12, bottom: 8, left: 12 };
            Chart.defaults.plugins.tooltip.cornerRadius = 8;
            Chart.defaults.plugins.tooltip.boxPadding = 4;
            Chart.defaults.plugins.tooltip.usePointStyle = true;
        }
        if (Chart.defaults.plugins && Chart.defaults.plugins.legend && Chart.defaults.plugins.legend.labels) {
            Chart.defaults.plugins.legend.labels.usePointStyle = true;
            Chart.defaults.plugins.legend.labels.pointStyle = 'circle';
            Chart.defaults.plugins.legend.labels.boxWidth = 8;
            Chart.defaults.plugins.legend.labels.boxHeight = 8;
            Chart.defaults.plugins.legend.labels.padding = 16;
            Chart.defaults.plugins.legend.labels.color = '#475569';
            Chart.defaults.plugins.legend.labels.font = { family: 'Poppins', size: 11, weight: '600' };
        }

        const barDataLabelOptions = {
            display: (ctx) => {
                const val = ctx.dataset && ctx.dataset.data ? ctx.dataset.data[ctx.dataIndex] : null;
                return val !== 0 && val !== null && val !== undefined && val !== '';
            },
            anchor: 'end',
            align: 'top',
            offset: 2,
            color: '#64748B',
            font: { family: 'Poppins', weight: '600', size: 9.5 },
            formatter: (value) => (value === 0 ? '' : value)
        };

        // Berpindah antara halaman "Dashboard", "Breakdown Agent", "Bandingkan Periode", "Kelola Akun"
        function showPage(page) {
            activeAppPage = page;
            document.getElementById('page-dashboard').style.display = (page === 'dashboard') ? 'block' : 'none';
            document.getElementById('page-breakdown-agent').style.display = (page === 'breakdown') ? 'block' : 'none';
            const pageBreakdownKipEl = document.getElementById('page-breakdown-kip');
            if (pageBreakdownKipEl) pageBreakdownKipEl.style.display = (page === 'breakdownKip') ? 'block' : 'none';
            document.getElementById('page-compare-range').style.display = (page === 'compare') ? 'block' : 'none';
            document.getElementById('page-user-management').style.display = (page === 'usermgmt') ? 'block' : 'none';
            document.getElementById('page-activity-log').style.display = (page === 'activitylog') ? 'block' : 'none';

            const pageUserGuideEl = document.getElementById('page-user-guide');
            if (pageUserGuideEl) pageUserGuideEl.style.display = (page === 'userguide') ? 'block' : 'none';

            // Update indikator halaman aktif di top header bar (desktop)
            const pageMeta = {
                dashboard: { icon: 'fa-chart-pie', label: 'Dashboard' },
                breakdown: { icon: 'fa-users-viewfinder', label: 'Team Insights' },
                breakdownKip: { icon: 'fa-list-check', label: 'KIP Insights' },
                compare: { icon: 'fa-calendar-week', label: 'Period Comparison' },
                usermgmt: { icon: 'fa-users-gear', label: 'Kelola Akun' },
                activitylog: { icon: 'fa-clock-rotate-left', label: 'Log Aktivitas' },
                userguide: { icon: 'fa-book-open', label: 'User Guide' }
            };
            const indicatorEl = document.getElementById('topHeaderPageIndicator');
            if (indicatorEl && pageMeta[page]) {
                const isDomainPage = ['dashboard', 'breakdown', 'breakdownKip', 'compare'].includes(page);
                const domainTag = isDomainPage 
                    ? `<span class="badge-domain-chip ${currentDomain} me-1.5"><i class="fa-solid ${currentDomain === 'fixed' ? 'fa-wifi' : 'fa-mobile-screen-button'} me-1"></i>${currentDomain === 'fixed' ? 'Fixed' : 'Mobile'}</span>` 
                    : '';
                indicatorEl.innerHTML = `${domainTag}<i class="fa-solid ${pageMeta[page].icon} me-1"></i> ${pageMeta[page].label}`;
            }

            document.getElementById('navDashboard').classList.toggle('active', page === 'dashboard');
            document.getElementById('navBreakdown').classList.toggle('active', page === 'breakdown');
            const navBreakdownKip = document.getElementById('navBreakdownKip');
            if (navBreakdownKip) navBreakdownKip.classList.toggle('active', page === 'breakdownKip');
            document.getElementById('navCompareRange').classList.toggle('active', page === 'compare');
            const navUserMgmt = document.getElementById('navUserMgmt');
            if (navUserMgmt) navUserMgmt.classList.toggle('active', page === 'usermgmt');
            const navActivityLog = document.getElementById('navActivityLog');
            if (navActivityLog) navActivityLog.classList.toggle('active', page === 'activitylog');
            const navUserGuide = document.getElementById('navUserGuide');
            if (navUserGuide) navUserGuide.classList.toggle('active', page === 'userguide');

            if (page === 'breakdown') {
                populateBreakdownFilterDropdowns();
                const emptyState = document.getElementById('breakdownEmptyState');
                const resultContainer = document.getElementById('breakdownResultContainer');
                if (!hasSearchedBreakdown) {
                    if (emptyState) emptyState.style.display = 'block';
                    if (resultContainer) resultContainer.style.display = 'none';
                } else {
                    if (emptyState) emptyState.style.display = 'none';
                    if (resultContainer) resultContainer.style.display = 'block';
                }
            }
            if (page === 'breakdownKip') {
                if (!isBreakdownKipInitialized) {
                    populateBreakdownKipFilters();
                    isBreakdownKipInitialized = true;
                }
                const emptyState = document.getElementById('kipEmptyState');
                const resultContainer = document.getElementById('kipResultContainer');
                if (!hasSearchedKip) {
                    if (emptyState) emptyState.style.display = 'block';
                    if (resultContainer) resultContainer.style.display = 'none';
                } else {
                    if (emptyState) emptyState.style.display = 'none';
                    if (resultContainer) resultContainer.style.display = 'block';
                }
            }
            if (page === 'usermgmt') { loadUserManagementTable(); loadPendingRequests(); }
            if (page === 'activitylog') { loadActivityLogs(); }

            // Catat aktivitas perpindahan halaman (khusus halaman yang punya menu di sidebar)
            const pageLabels = {
                dashboard: 'Membuka halaman Dashboard',
                breakdown: 'Membuka halaman Team Insights',
                breakdownKip: 'Membuka halaman KIP Insights',
                compare: 'Membuka halaman Period Comparison',
                usermgmt: 'Membuka halaman Kelola Akun',
                activitylog: 'Membuka halaman Log Aktivitas',
                userguide: 'Membuka User Guide'
            };
            if (pageLabels[page] && currentUsername && String(currentUsername).trim().toLowerCase() !== 'superadmin') {
                google.script.run.logActivity(currentUsername, currentUserRole, pageLabels[page]);
            }

            if (window.innerWidth < 992) {
                document.querySelector('.sidebar').classList.remove('show');
                document.getElementById('sidebarOverlay').classList.remove('show');
            }
        }

        // Menampilkan/menyembunyikan menu "Kelola Akun" & "Log Aktivitas" sesuai role akun yang login
        function applyUserRoleUI() {
            const navUserMgmt = document.getElementById('navUserMgmt');
            if (navUserMgmt) {
                navUserMgmt.style.display = (currentUserRole === 'superadmin') ? '' : 'none';
            }
