        // ===================== WATERMARK USERNAME (anti-screenshot) ===================== //
        // Menyimpan tanggal & jam persis saat login dilakukan untuk dicetak di watermark
        let userLoginSessionStamp = '';

        function getFormattedLoginTimestamp() {
            if (userLoginSessionStamp) return userLoginSessionStamp;
            const now = new Date();
            const pad = n => String(n).padStart(2, '0');
            const d = pad(now.getDate());
            const m = pad(now.getMonth() + 1);
            const y = now.getFullYear();
            const hh = pad(now.getHours());
            const mm = pad(now.getMinutes());
            const ss = pad(now.getSeconds());
            userLoginSessionStamp = `${d}/${m}/${y} ${hh}:${mm}:${ss} WIB`;
            return userLoginSessionStamp;
        }

        // Menggambar satu ubin watermark dengan format: "username • DD/MM/YYYY HH:mm:ss WIB"
        function drawWatermarkTile(ctx, tileSize, opacity, fontSize) {
            ctx.save();
            ctx.clearRect(0, 0, tileSize, tileSize);
            ctx.translate(tileSize / 2, tileSize / 2);
            ctx.rotate(-Math.PI / 6); // -30 derajat
            ctx.font = `600 ${fontSize}px 'Poppins', sans-serif`;
            ctx.fillStyle = `rgba(28, 37, 65, ${opacity})`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            const stamp = getFormattedLoginTimestamp();
            const userText = currentUsername || 'user';
            ctx.fillText(`${userText}  \u2022  ${stamp}`, 0, 0);
            ctx.restore();
        }

        function applyWatermark(username) {
            const overlay = document.getElementById('watermarkOverlay');
            if (!overlay || !username) return;
            if (!userLoginSessionStamp) {
                getFormattedLoginTimestamp();
            }

            const tile = 380;
            const canvas = document.createElement('canvas');
            canvas.width = tile;
            canvas.height = tile;
            drawWatermarkTile(canvas.getContext('2d'), tile, 0.08, 15);

            overlay.style.backgroundImage = `url(${canvas.toDataURL('image/png')})`;
            overlay.style.display = 'block';
        }

        // Menerakan watermark langsung ke canvas hasil download (PNG tabel/grafik).
        function stampWatermarkOnCanvas(targetCtx, width, height) {
            if (!currentUsername) return;
            const tile = 380;
            const tileCanvas = document.createElement('canvas');
            tileCanvas.width = tile;
            tileCanvas.height = tile;
            drawWatermarkTile(tileCanvas.getContext('2d'), tile, 0.13, 15);

            const pattern = targetCtx.createPattern(tileCanvas, 'repeat');
            targetCtx.save();
            targetCtx.fillStyle = pattern;
            targetCtx.fillRect(0, 0, width, height);
            targetCtx.restore();
        }

        function hideWatermark() {
            userLoginSessionStamp = '';
            const overlay = document.getElementById('watermarkOverlay');
            if (overlay) {
                overlay.style.display = 'none';
                overlay.style.backgroundImage = 'none';
            }
        }

        // Jam & tanggal realtime di top header bar (desktop)
        const HARI_INDO_DASHBOARD = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', "Jum'at", 'Sabtu'];
        const BULAN_INDO_DASHBOARD = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
        function updateTopHeaderClock() {
            const el = document.getElementById('topHeaderDateTime');
            if (!el) return;
            const now = new Date();
            const dateStr = `${HARI_INDO_DASHBOARD[now.getDay()]}, ${now.getDate()} ${BULAN_INDO_DASHBOARD[now.getMonth()]} ${now.getFullYear()}`;
            const timeStr = [now.getHours(), now.getMinutes(), now.getSeconds()].map(n => String(n).padStart(2, '0')).join(':');
            el.innerHTML = `<i class="fa-regular fa-calendar-days opacity-75"></i> <span>${dateStr}</span> <span class="opacity-50 mx-1">\u2022</span> <i class="fa-regular fa-clock opacity-75 ms-1"></i> <span>${timeStr} WIB</span>`;
        }
        updateTopHeaderClock();
        setInterval(updateTopHeaderClock, 1000);

        // Animasi "hitung naik" pada angka KPI, dari 0 ke nilai akhir -- memberi kesan hidup
        // setiap kali data difilter ulang. Durasi disesuaikan otomatis (angka besar => lebih cepat per step).
        function animateCountUp(el, targetValue) {
            const target = parseInt(targetValue, 10) || 0;
            const duration = 600;
            const startTime = performance.now();
            const startValue = 0;
            function step(now) {
                const progress = Math.min((now - startTime) / duration, 1);
                const eased = 1 - Math.pow(1 - progress, 3); // ease-out cubic
                el.innerText = Math.round(startValue + (target - startValue) * eased);
                if (progress < 1) requestAnimationFrame(step);
                else el.innerText = target;
            }
            requestAnimationFrame(step);
        }

        // Menampilkan loading persentase setiap kali tombol Cari diklik, lalu menampilkan detail section
        function handleCariClick() {
            const loader = document.getElementById('loader');
            if (loader) loader.style.display = 'flex';
            runFakeLoader(function () {
                if (loader) loader.style.display = 'none';
                const detailSec = document.getElementById('dashboardDetailSection');
                if (detailSec) detailSec.style.display = 'block';
                filterAndRender();
                setTimeout(function () {
                    if (typeof activeCharts === 'object' && activeCharts) {
                        Object.values(activeCharts).forEach(function (c) {
                            if (c && typeof c.resize === 'function') c.resize();
                        });
                    }
                }, 100);
            });
        }
        let hasSearchedBreakdown = false;

        function handleCariBreakdown() {
            const btn = document.getElementById('btnCariBreakdown');
            const originalHtml = btn ? btn.innerHTML : '<i class="fa-solid fa-magnifying-glass me-1"></i> Cari Data';
            if (btn) {
                btn.disabled = true;
                btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin me-1"></i> Memuat Data...';
            }

            setTimeout(function () {
                try {
                    hasSearchedBreakdown = true;
                    filterBreakdownAgent();
                    const emptyState = document.getElementById('breakdownEmptyState');
                    const resultContainer = document.getElementById('breakdownResultContainer');
                    if (emptyState) emptyState.style.display = 'none';
                    if (resultContainer) resultContainer.style.display = 'block';
                } catch (err) {
                    console.error('Error executing filterBreakdownAgent:', err);
                } finally {
                    if (btn) {
                        btn.disabled = false;
                        btn.innerHTML = originalHtml;
                    }
                }
            }, 35);
        }

        // Catatan: fungsi handleLogin() dan runFakeLoader() sekarang ada di Login.html
        // dan memanggil loadDataFromBackend() di bawah ini setelah login server-side berhasil.

        // Buka/tutup sidebar khusus tampilan mobile (di bawah 992px)
        function toggleSidebar() {
            document.querySelector('.sidebar').classList.toggle('show');
            document.getElementById('sidebarOverlay').classList.toggle('show');
        }

        // Perkecil / Perbesar sidebar desktop (collapse / expand mode)
        function toggleSidebarMinimize() {
            const wrap = document.getElementById('dashboard-wrapper');
            if (!wrap) return;
            wrap.classList.toggle('sidebar-minimized');
            const isMin = wrap.classList.contains('sidebar-minimized');
            try {
                localStorage.setItem('mata_sidebar_minimized', isMin ? 'true' : 'false');
            } catch (e) { }

            // Memicu Chart.js resize setelah transisi CSS sidebar selesai (300ms)
            setTimeout(function () {
