        function restoreSidebarPreference() {
            try {
                if (localStorage.getItem('mata_sidebar_minimized') === 'true') {
                    const wrap = document.getElementById('dashboard-wrapper');
                    if (wrap) wrap.classList.add('sidebar-minimized');
                }
            } catch (e) { }
        }

        // ===================== SISTEM AUTO-LOGOUT SAAT IDLE 15 MENIT ===================== //
        const IDLE_TIMEOUT_MS = 15 * 60 * 1000; // 15 menit = 900.000 ms
        let idleTimer = null;
        let idleIntervalChecker = null;
        let lastUserActivityTime = Date.now();
        let isIdleListenerAttached = false;

        function resetIdleTimer() {
            if (!currentUsername) return;
            lastUserActivityTime = Date.now();
            if (idleTimer) clearTimeout(idleTimer);
            idleTimer = setTimeout(triggerIdleLogout, IDLE_TIMEOUT_MS);
        }

        function triggerIdleLogout() {
            if (!currentUsername) return;
            console.warn('[Security] Tidak ada aktivitas selama 15 menit. Auto-logout dipicu.');
            handleLogout('idle');
        }

        function startIdleTimer() {
            stopIdleTimer();
            lastUserActivityTime = Date.now();
            idleTimer = setTimeout(triggerIdleLogout, IDLE_TIMEOUT_MS);

            // Interval cadangan untuk mendeteksi sleep mode atau tab background browser
            idleIntervalChecker = setInterval(function () {
                if (currentUsername && (Date.now() - lastUserActivityTime >= IDLE_TIMEOUT_MS)) {
                    triggerIdleLogout();
                }
            }, 15000); // periksa setiap 15 detik

            if (!isIdleListenerAttached) {
                const events = ['mousemove', 'mousedown', 'keydown', 'touchstart', 'scroll', 'click'];
                let throttleTimeout = null;

                const throttledActivity = function () {
                    if (!throttleTimeout) {
                        throttleTimeout = setTimeout(function () {
                            throttleTimeout = null;
                            resetIdleTimer();
                        }, 1000); // Throttle 1 detik agar hemat CPU
                    }
                };

                events.forEach(function (evt) {
                    window.addEventListener(evt, throttledActivity, { passive: true });
                });

                isIdleListenerAttached = true;
            }
        }

        function stopIdleTimer() {
            if (idleTimer) {
                clearTimeout(idleTimer);
                idleTimer = null;
            }
            if (idleIntervalChecker) {
                clearInterval(idleIntervalChecker);
                idleIntervalChecker = null;
            }
        }

        function handleLogout(reason) {
            stopIdleTimer();

            const isIdleLogout = (reason === 'idle');
            const logMsg = isIdleLogout ? 'Logout Otomatis (Idle 15 Menit)' : 'Logout';

            if (currentUsername && String(currentUsername).trim().toLowerCase() !== 'superadmin') {
                google.script.run.logActivity(currentUsername, currentUserRole, logMsg);
            }
            hideWatermark();

            // Tutup modal apapun yang sedang terbuka
            try {
                const openModals = document.querySelectorAll('.modal.show');
                openModals.forEach(m => {
                    const inst = bootstrap.Modal.getInstance(m);
                    if (inst) inst.hide();
                });
            } catch (e) { }

            const dash = document.getElementById('dashboard-wrapper');
            const loginEl = document.getElementById('login-container');

            // Fade-out halaman Dashboard secara halus
            dash.classList.remove('visible');

            setTimeout(function () {
                dash.style.display = 'none';

                document.getElementById('loginUser').value = '';
                document.getElementById('loginPass').value = '';

                const loginAlert = document.getElementById('loginAlert');
                if (isIdleLogout) {
                    loginAlert.innerText = 'Sesi Anda telah berakhir secara otomatis karena tidak ada aktivitas selama 15 menit. Silakan login kembali.';
                    loginAlert.className = 'alert alert-warning mb-3 py-2 text-center small fw-semibold';
                    loginAlert.classList.remove('d-none');
                } else {
                    loginAlert.className = 'alert alert-danger mb-3 py-2 text-center small fw-semibold d-none';
                }

                // Reset tombol login ke kondisi semula
                const btnLogin = document.getElementById('btnLogin');
                btnLogin.disabled = false;
                btnLogin.innerHTML = '<span>Login</span> <span style="font-size:1.15rem; line-height:1;">&rarr;</span>';

                // Fade-in halaman Login kembali
                loginEl.style.display = 'flex';
                loginEl.classList.remove('fade-out');
                void loginEl.offsetWidth;
            }, 400);

            // Reset state aplikasi
            allRecords = [];
            allDatasets = {
                fixed: { records: [], filters: { tanggal: [], bulan: [], tahun: [], unit: [], sourceBy: [] } },
                mobile: { records: [], filters: { tanggal: [], bulan: [], tahun: [], unit: [], sourceBy: [] } }
            };
            currentFilteredRecords = [];
            hasSearched = false;
            Object.keys(activeCharts).forEach(key => destroyChart(key));
            activeCharts = {};

            // Reset akun & UI khusus superadmin, serta kembalikan ke halaman Dashboard untuk sesi berikutnya
            currentUsername = '';
            currentUserRole = '';
            const navUserMgmt = document.getElementById('navUserMgmt');
            if (navUserMgmt) navUserMgmt.style.display = 'none';
            const navActivityLog = document.getElementById('navActivityLog');
            if (navActivityLog) navActivityLog.style.display = 'none';
            const pendingBadge = document.getElementById('pendingBadge');
            if (pendingBadge) pendingBadge.style.display = 'none';
            const userBadge = document.getElementById('topHeaderUserBadge');
            if (userBadge) userBadge.style.display = 'none';
            showPage('dashboard');
        }

        // Mengunduh grafik Chart.js sebagai PNG.
        // FIX: canvas Chart.js dibuat dengan background transparan. Saat diekspor langsung
        // via toBase64Image, area transparan itu sering tampil HITAM PEKAT ketika file PNG
        // dibuka di aplikasi/viewer yang tidak merender transparansi (WhatsApp, sebagian
        // image viewer, dsb). Solusinya: gambar ulang ke canvas sementara dengan latar putih
        // solid dahulu, baru diekspor.
        function downloadChartPng(chartKey, filename) {
            const chart = activeCharts[chartKey];
            if (!chart) {
                alert('Grafik belum tersedia. Silakan klik tombol Cari terlebih dahulu.');
                return;
            }

            const sourceCanvas = chart.canvas;
            const tempCanvas = document.createElement('canvas');
            tempCanvas.width = sourceCanvas.width;
            tempCanvas.height = sourceCanvas.height;
            const ctx = tempCanvas.getContext('2d');

            // Isi latar putih solid dahulu supaya tidak menjadi hitam saat dibuka
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, tempCanvas.width, tempCanvas.height);
            ctx.drawImage(sourceCanvas, 0, 0);

            // Cap watermark username supaya tetap terlihat di file PNG yang diunduh
            stampWatermarkOnCanvas(ctx, tempCanvas.width, tempCanvas.height);

            const link = document.createElement('a');
            link.href = tempCanvas.toDataURL('image/png', 1);
            link.download = filename + '.png';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }

        // Lazy-load html2canvas: library ini (~190KB) hanya dimuat saat dibutuhkan pertama kali
        // (klik tombol "Unduh PNG"), bukan di awal load halaman -- mempercepat waktu load awal
        // tanpa mengubah fungsi tombol download sama sekali.
        function ensureHtml2Canvas(callback) {
            if (typeof html2canvas !== 'undefined') { callback(); return; }
            const existing = document.getElementById('html2canvas-lazy-script');
            if (existing) { existing.addEventListener('load', callback, { once: true }); return; }
            const s = document.createElement('script');
            s.id = 'html2canvas-lazy-script';
            s.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
            s.onload = callback;
            s.onerror = function () { alert('Gagal memuat modul unduh gambar. Periksa koneksi internet Anda.'); };
            document.head.appendChild(s);
        }

        // Mengunduh tabel "Data Keseluruhan Agent" sebagai PNG via html2canvas.
        function downloadTableAsPng() {
            ensureHtml2Canvas(function () {
                const el = document.getElementById('topAgentTable').closest('.card-custom');
                html2canvas(el, {
                    backgroundColor: '#ffffff',
                    scale: 2,
                    useCORS: true,
                    allowTaint: true,
                    logging: false
                }).then(canvas => {
                    // Cap watermark username supaya tetap terlihat di file PNG yang diunduh
                    stampWatermarkOnCanvas(canvas.getContext('2d'), canvas.width, canvas.height);

                    const link = document.createElement('a');
                    link.download = 'Data_Keseluruhan_Bad_Tiket_Agent.png';
                    link.href = canvas.toDataURL('image/png');
                    link.click();
                }).catch(() => {
                    alert('Gagal membuat gambar tabel. Coba lagi.');
                });
            });
        }

        // Lazy-load SheetJS (xlsx.js): dipakai untuk fitur "Unduh Excel" pada tabel Data
        // Keseluruhan Agent. Hanya dimuat saat tombol Excel benar-benar diklik pertama kali.
        function ensureXLSXLibrary(callback) {
            if (typeof XLSX !== 'undefined') { callback(); return; }
            const existing = document.getElementById('xlsx-lazy-script');
            if (existing) { existing.addEventListener('load', callback, { once: true }); return; }
            const s = document.createElement('script');
            s.id = 'xlsx-lazy-script';
            s.src = 'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';
            s.onload = callback;
            s.onerror = function () { alert('Gagal memuat modul Excel. Periksa koneksi internet Anda.'); };
            document.head.appendChild(s);
        }

        // Mengunduh detail tiket (dari data yang sedang tampil di tabel Data Keseluruhan Agent,
        // mengikuti filter/pencarian Nama Agent & Kategori L yang aktif) sebagai file .xlsx,
        // dengan urutan kolom yang sama seperti modal "Detail Temuan Bad Ticket".
        function downloadDetailExcel() {
            if (!currentFilteredRecords || currentFilteredRecords.length === 0) {
                alert('Tidak ada data untuk diunduh. Silakan sesuaikan filter/pencarian terlebih dahulu.');
                return;
            }

            ensureXLSXLibrary(function () {
                const headers = [
                    'Tanggal Input Solver (D)', 'SIAD Agent (F)', 'Nama Agent (G)', 'Nama TL (H)',
                    'Nama SPV (I)', 'Unit Name (J)', 'No Tiket (E)', 'KIP (K)',
                    'Kategori Bad Ticket (L)', 'Detil Bad Ticket (M)', 'Notes by Solver (N)',
                    'Final Status (O)', 'Source by (P)'
                ];

                const rows = currentFilteredRecords.map(row => [
                    row[3] || '', row[5] || '', row[6] || '', row[7] || '', row[8] || '',
                    row[9] || '', row[4] || '', row[10] || '', row[11] || '', row[12] || '',
                    maskNotesKolomN(row[13]) || '', row[14] || '', row[15] || ''
                ]);

                const worksheet = XLSX.utils.aoa_to_sheet([headers, ...rows]);
                // Lebar kolom disesuaikan supaya enak dibaca saat file dibuka di Excel
                worksheet['!cols'] = [
                    { wch: 18 }, { wch: 14 }, { wch: 22 }, { wch: 18 }, { wch: 18 },
                    { wch: 16 }, { wch: 14 }, { wch: 28 }, { wch: 26 }, { wch: 34 },
                    { wch: 34 }, { wch: 16 }, { wch: 14 }
                ];

                const workbook = XLSX.utils.book_new();
                XLSX.utils.book_append_sheet(workbook, worksheet, 'Detail Bad Ticket');

                const tz = new Date();
                const stamp = `${tz.getFullYear()}${String(tz.getMonth() + 1).padStart(2, '0')}${String(tz.getDate()).padStart(2, '0')}_${String(tz.getHours()).padStart(2, '0')}${String(tz.getMinutes()).padStart(2, '0')}`;
                XLSX.writeFile(workbook, `Detail_Bad_Ticket_${stamp}.xlsx`);
            });
        }

        function updateDomainSwitcherUI(domain) {
            const pairs = [
                ['topBtnDomainFixed', 'topBtnDomainMobile'],
                ['sideBtnDomainFixed', 'sideBtnDomainMobile'],
                ['mobBtnDomainFixed', 'mobBtnDomainMobile']
            ];
            pairs.forEach(([fixedId, mobileId]) => {
                const btnF = document.getElementById(fixedId);
                const btnM = document.getElementById(mobileId);
                if (btnF) {
                    btnF.classList.toggle('active', domain === 'fixed');
                }
                if (btnM) {
                    btnM.classList.toggle('active', domain === 'mobile');
                }
            });
        }

        function updateDomainBadges(domain) {
            const isFixed = (domain === 'fixed');
            const icon = isFixed ? 'fa-wifi' : 'fa-mobile-screen-button';
            const label = isFixed ? 'FIXED' : 'MOBILE';
            const cls = isFixed ? 'fixed' : 'mobile';

            const badgeIds = ['dashDomainBadge', 'teamDomainBadge', 'kipDomainBadge', 'compareDomainBadge'];
            badgeIds.forEach(id => {
                const b = document.getElementById(id);
                if (b) {
                    b.className = `badge-domain-indicator ${cls}`;
                    b.innerHTML = `<i class="fa-solid ${icon} me-1"></i> ${label}`;
                }
            });

            // Update top header page indicator jika berada di salah satu 4 halaman domain
            if (['dashboard', 'breakdown', 'breakdownKip', 'compare'].includes(activeAppPage)) {
                showPage(activeAppPage);
            }
        }

        function refreshActivePageForDomain(domain) {
            if (activeAppPage === 'dashboard') {
                resetFilters();
            } else if (activeAppPage === 'breakdown') {
                resetBreakdownFilters();
            } else if (activeAppPage === 'breakdownKip') {
                resetBreakdownKipFilters();
            } else if (activeAppPage === 'compare') {
                resetCompareRange();
            }
        }

        function switchDomain(domain, isInit) {
            if (domain !== 'fixed' && domain !== 'mobile') domain = 'fixed';
            if (!isInit && currentDomain === domain) return;

            currentDomain = domain;
            try {
                localStorage.setItem('mata_domain_pref', domain);
            } catch (e) {}

            const activeData = (allDatasets && allDatasets[domain]) ? allDatasets[domain] : { records: [], filters: {} };
            allRecords = (activeData.records || []).slice();

            // Isi ulang seluruh dropdown filter sesuai dataset domain aktif
            populateFilters(activeData.filters || {});
            populateSubFilterKolomL();
            populateSpvTlVsFilters();
            populateBreakdownTrendMonths();
            populateCompareRangeFilters();
            populateBreakdownKipFilters();

            // Sinkronkan UI Switcher dan Badge di setiap halaman
            updateDomainSwitcherUI(domain);
            updateDomainBadges(domain);

            if (isInit) {
                // Data dashboard overview otomatis digenerate saat login (hanya Card & Trend Monthly)
                initDashboardOverview();
            } else {
                refreshActivePageForDomain(domain);
                // Catat log aktivitas jika bukan superadmin
                if (currentUsername && String(currentUsername).trim().toLowerCase() !== 'superadmin' && typeof google !== 'undefined' && google.script && google.script.run) {
                    google.script.run.logActivity(currentUsername, currentUserRole, 'Beralih ke Layanan ' + (domain === 'fixed' ? 'Fixed Broadband' : 'Mobile'));
                }
            }
        }

        function loadDataFromBackend() {
            google.script.run.withSuccessHandler(function (response) {
                if (response && response.error) {
                    alert('Gagal memuat data: ' + response.error);
                }

                const processRecords = (records) => {
                    return (records || []).map(row => {
                        if (row && row[13]) {
                            row[13] = maskNotesKolomN(row[13]);
                        }
                        return row;
                    });
                };

                // Parsing Fixed Dataset (Sheet "Data")
                if (response && response.fixed) {
                    allDatasets.fixed = {
                        records: processRecords(response.fixed.rawRecords),
                        filters: response.fixed.filters || { tanggal: [], bulan: [], tahun: [], unit: [], sourceBy: [] }
                    };
                } else {
                    allDatasets.fixed = {
                        records: processRecords(response ? response.rawRecords : []),
                        filters: (response && response.filters) ? response.filters : { tanggal: [], bulan: [], tahun: [], unit: [], sourceBy: [] }
                    };
                }

                // Parsing Mobile Dataset (Sheet "Data2")
                if (response && response.mobile) {
                    allDatasets.mobile = {
                        records: processRecords(response.mobile.rawRecords),
                        filters: response.mobile.filters || { tanggal: [], bulan: [], tahun: [], unit: [], sourceBy: [] }
                    };
                } else {
                    allDatasets.mobile = {
                        records: [],
                        filters: { tanggal: [], bulan: [], tahun: [], unit: [], sourceBy: [] }
                    };
                }

                // Ambil preferensi domain tersimpan (default 'fixed')
                let initialDomain = 'fixed';
                try {
                    const saved = localStorage.getItem('mata_domain_pref');
                    if (saved === 'mobile') initialDomain = 'mobile';
                } catch(e) {}

                // Inisialisasi domain aktif
                switchDomain(initialDomain, true);
            }).getDashboardData();
        }

        window.onload = function () {
            agentModalBootstrap = new bootstrap.Modal(document.getElementById('agentDetailModal'));
            breakdownModalBootstrap = new bootstrap.Modal(document.getElementById('breakdownDetailModal'));
            userFormBootstrap = new bootstrap.Modal(document.getElementById('userFormModal'));
            restoreSidebarPreference();
        };

        function populateFilters(filters) {
            const pop = (id, arr) => {
                const select = document.getElementById(id);
                select.innerHTML = select.options[0].outerHTML;
                arr.forEach(val => {
                    if (val && val.toString().trim() !== "") {
                        select.options[select.options.length] = new Option(val, val);
                    }
                });
            };
            const bulanTerurut = sortBulanIndo(filters.bulan || []);
            bulanTerurutGlobal = bulanTerurut;

            pop('filTanggal', filters.tanggal);
            pop('filBulan', bulanTerurut);
            pop('filTahun', filters.tahun);
            pop('filUnit', filters.unit);
            pop('filSourceBy', filters.sourceBy || []);

            // Isi juga dropdown filter di halaman Breakdown Agent (sumber data sama)
            pop('filBdTanggal', filters.tanggal);
            pop('filBdBulan', bulanTerurut);
            pop('filBdTahun', filters.tahun);
            pop('filBdUnit', filters.unit);
            pop('filBdSourceBy', filters.sourceBy || []);
            populateBreakdownFilterDropdowns();

            // Isi juga dropdown filter di halaman Breakdown KIP
            pop('filKipTanggal', filters.tanggal);
            pop('filKipBulan', bulanTerurut);
            pop('filKipTahun', filters.tahun);
            pop('filKipUnit', filters.unit);
            pop('filKipSourceBy', filters.sourceBy || []);

            // Isi Filter Dropdown Section Baru (Vs) - terurut Januari s/d Desember
            const selBefore = document.getElementById('vsBulanBefore');
            const selAfter = document.getElementById('vsBulanAfter');
            selBefore.innerHTML = "";
            selAfter.innerHTML = "";

            bulanTerurut.forEach((val) => {
                if (val && val.toString().trim() !== "") {
                    selBefore.options[selBefore.options.length] = new Option(val, val);
                    selAfter.options[selAfter.options.length] = new Option(val, val);
                }
            });

            // Default set: Before indeks awal, After indeks kedua (jika ada)
            if (selBefore.options.length > 0) selBefore.selectedIndex = 0;
            if (selAfter.options.length > 1) {
                selAfter.selectedIndex = 1;
            } else if (selAfter.options.length > 0) {
                selAfter.selectedIndex = 0;
            }
        }

        // Mengisi semua dropdown yang bersumber dari Kolom L (index 11):
        // filter panel utama (filKategoriL), grafik Trend Daily (filGraphKolomL),
        // grafik VS (vsFilterKolomL), filter kecil di tabel agent (filAgentKategoriL),
        // dan filter di Team Insights (filBdKategoriL).
        // Membersihkan opsi lama terlebih dahulu sehingga tidak pernah terjadi duplikasi opsi saat beralih produk/domain.
        function populateSubFilterKolomL() {
            let listL = [...new Set(allRecords.map(row => row[11]).filter(x => x && String(x).trim() !== ""))].sort();
            
            const fillSelect = (id, defaultLabel) => {
                const sel = document.getElementById(id);
                if (!sel) return;
                const prevVal = sel.value;
                sel.innerHTML = '<option value="">' + defaultLabel + '</option>';
                listL.forEach(val => {
                    sel.options[sel.options.length] = new Option(val, val);
                });
                if (prevVal && listL.includes(prevVal)) {
                    sel.value = prevVal;
                }
            };

            fillSelect('filGraphKolomL', 'Semua Kategori (Kolom L)');
            fillSelect('vsFilterKolomL', 'Semua Kategori (Kolom L)');
            fillSelect('filKategoriL', 'Semua Kategori');
            fillSelect('filAgentKategoriL', 'Semua Kategori (L)');
            fillSelect('filBdKategoriL', 'Semua Kategori');
        }

        // Inisialisasi tampilan awal Dashboard: Hanya Card KPI dan Trend Bad Tiket Monthly
        function initDashboardOverview() {
            hasSearched = false;
            const detailSec = document.getElementById('dashboardDetailSection');
            if (detailSec) detailSec.style.display = 'none';

            const selStatusSgh = document.getElementById('filStatusSanggahan');
            const fStatusSgh = selStatusSgh ? selStatusSgh.value : 'net';

            let baseData = allRecords;
            if (fStatusSgh === 'net') {
                baseData = allRecords.filter(r => !isSanggahanDiterima(r));
            } else if (fStatusSgh === 'only_sanggahan') {
                baseData = allRecords.filter(r => isSanggahanDiterima(r));
            }

            calculateKPI(baseData, allRecords);
            renderMonthlyChart(baseData);
        }

