        function filterAndRender() {
            hasSearched = true;
            const fTgl = document.getElementById('filTanggal').value.trim();
            const fBln = document.getElementById('filBulan').value.trim();
            const fThn = document.getElementById('filTahun').value.trim();
            const fUnit = document.getElementById('filUnit').value.trim();
            const fKatL = document.getElementById('filKategoriL').value.trim();
            const fSourceBy = document.getElementById('filSourceBy').value.trim();
            const selStatusSgh = document.getElementById('filStatusSanggahan');
            const fStatusSgh = selStatusSgh ? selStatusSgh.value : 'net';
            const sSIAD = document.getElementById('searchSIAD').value.toLowerCase().trim();
            const sAgentName = document.getElementById('searchAgentName').value.toLowerCase().trim();
            const fAgentKatL = document.getElementById('filAgentKategoriL').value.trim();

            // Saring seluruh parameter dasar (sebelum status sanggahan)
            // Mendukung filter tanggal kumulatif (MTD): jika tanggal dipilih (misal: 27),
            // maka data yang tertampil adalah akumulasi tanggal 1 s/d tanggal tersebut.
            let maxDay = 31;
            if (fTgl !== "") {
                const parsed = parseInt(fTgl, 10);
                if (!isNaN(parsed) && parsed >= 1 && parsed <= 31) maxDay = parsed;
            }

            let baseFiltered = allRecords.filter(row => {
                let rDate = parseInt(row[0], 10);
                let matchTgl = fTgl === "" || (!isNaN(rDate) && rDate >= 1 && rDate <= maxDay);
                let matchBln = fBln === "" || String(row[1]).trim() === fBln;
                let matchThn = fThn === "" || String(row[2]).trim() === fThn;
                let matchUnit = fUnit === "" || String(row[9]).trim() === fUnit;
                let matchKatL = fKatL === "" || String(row[11]).trim().toUpperCase() === fKatL.toUpperCase();
                let matchSourceBy = fSourceBy === "" || String(row[15]).trim() === fSourceBy;
                let matchSIAD = sSIAD === "" || (row[5] != null && String(row[5]).toLowerCase().includes(sSIAD));
                return matchTgl && matchBln && matchThn && matchUnit && matchKatL && matchSourceBy && matchSIAD;
            });

            // Terapkan saringan Status Sanggahan (Kolom O)
            let filtered = baseFiltered.filter(row => {
                if (fStatusSgh === 'net' && isSanggahanDiterima(row)) return false;
                if (fStatusSgh === 'only_sanggahan' && !isSanggahanDiterima(row)) return false;
                return true;
            });

            // Filter tambahan (kecil) khusus untuk tabel "Data Keseluruhan Agent"
            let filteredForAgentTable = filtered.filter(row => {
                let matchKatL = fAgentKatL === "" || String(row[11]).trim().toUpperCase() === fAgentKatL.toUpperCase();
                let matchAgentName = sAgentName === "" || (row[6] != null && String(row[6]).toLowerCase().includes(sAgentName));
                return matchKatL && matchAgentName;
            });

            currentFilteredRecords = filteredForAgentTable;

            calculateKPI(filtered, baseFiltered);
            renderCharts(filtered, baseFiltered);
            renderAllAgents(filteredForAgentTable);
            renderVsChart();
            renderSpvVsChart();
            renderTlVsChart();
        }

        // Helper pemetaan tema, warna, dan icon untuk kategori Bad Tiket (Kolom L)
        function getCategoryTheme(catName) {
            const upper = String(catName || '').toUpperCase();
            if (upper.includes('CASE ID') || upper.includes('PANDUAN SOLUSI')) {
                return { icon: 'fa-file-circle-xmark', theme: 'kpi-theme-case-id' };
            }
            if (upper.includes('MANDATORY')) {
                return { icon: 'fa-triangle-exclamation', theme: 'kpi-theme-mandatory' };
            }
            if (upper.includes('KIP/SYMPTOMP') || upper.includes('SYMPTOMP')) {
                return { icon: 'fa-circle-exclamation', theme: 'kpi-theme-kip-symptomp' };
            }
            if (upper.includes('KIP TIDAK SESUAI') || upper.includes('KIP')) {
                return { icon: 'fa-id-card', theme: 'kpi-theme-kip' };
            }
            if (upper.includes('TIDAK PERLU DIESKALASI') || upper.includes('NO ESCALATE')) {
                return { icon: 'fa-ban', theme: 'kpi-theme-no-escalate' };
            }
            if (upper.includes('DUMMY')) {
                return { icon: 'fa-phone', theme: 'kpi-theme-dummy' };
            }
            if (upper.includes('DOUBLE')) {
                return { icon: 'fa-clone', theme: 'kpi-theme-double' };
            }
            if (upper.includes('ESKALASI') && upper.includes('SALAH')) {
                return { icon: 'fa-route', theme: 'kpi-theme-salah-eskalasi' };
            }
            if (upper.includes('SALAH TUJUAN')) {
                return { icon: 'fa-location-crosshairs', theme: 'kpi-theme-salah-tujuan' };
            }
            if (upper.includes('ISL')) {
                return { icon: 'fa-network-wired', theme: 'kpi-theme-isl' };
            }
            if (upper.includes('OSL')) {
                return { icon: 'fa-satellite-dish', theme: 'kpi-theme-osl' };
            }
            return { icon: 'fa-tag', theme: 'kpi-theme-generic' };
        }

        // Filter cepat dashboard langsung dari klik kartu KPI Kategori
        function filterDashboardByKategori(catName) {
            const sel = document.getElementById('filKategoriL');
            if (sel) {
                sel.value = catName;
                handleCariClick();
            }
        }

        // KPI menghitung TOTAL tiket per Kategori (Kolom L), disesuaikan secara dinamis
        // antara Fixed (Sheet "Data") dan Mobile (Sheet "Data2").
        function calculateKPI(data, rawBaseData) {
            // 1. Animasi Total Bad Tiket
            const elTotal = document.getElementById('kpiTotalBadTiket');
            if (elTotal) {
                animateCountUp(elTotal, data.length);
            }

            // 2. Sub-pills pada Card Total Bad Tiket (All vs Sgh vs Net)
            const base = (rawBaseData && rawBaseData.length > 0) ? rawBaseData : (allRecords || []);
            let totAll = 0, totSgh = 0, totNet = 0;
            base.forEach(r => {
                totAll++;
                if (isSanggahanDiterima(r)) totSgh++;
                else totNet++;
            });

            const pillsEl = document.getElementById('kpiTotalBadTiketPills');
            if (pillsEl) {
                pillsEl.innerHTML = `
                    <span class="badge" style="background:#F1F5F9; color:#475569; font-weight:600; padding:2px 6px; font-size:0.68rem;" title="Total Tiket Sebelum Sanggahan">
                        All: <strong>${totAll.toLocaleString('id-ID')}</strong>
                    </span>
                    <span class="badge" style="background:rgba(217,119,6,0.12); color:#B45309; font-weight:600; padding:2px 6px; font-size:0.68rem;" title="Sanggahan Diterima (Pengurang Kolom O)">
                        <i class="fa-solid fa-gavel me-1"></i>Sgh: <strong>-${totSgh.toLocaleString('id-ID')}</strong>
                    </span>
                    <span class="badge" style="background:rgba(16,185,129,0.12); color:#047857; font-weight:600; padding:2px 6px; font-size:0.68rem;" title="Bad Tiket Bersih Setelah Sanggahan Diterima">
                        <i class="fa-solid fa-check-double me-1"></i>Net: <strong>${totNet.toLocaleString('id-ID')}</strong>
                    </span>
                `;
            }

            // 3. Render Card Kategori Dinamis
            const container = document.getElementById('dashboardCategoryCardsContainer');
            if (!container) return;

            let categoriesToDisplay = [];
            if (currentDomain === 'fixed') {
                categoriesToDisplay = [
                    { id: 'kpiMandatory', label: 'Mandatory Ticket', keys: ['MANDATORY TICKET'] },
                    { id: 'kpiKip', label: 'KIP Tidak Sesuai', keys: ['KIP TIDAK SESUAI'] },
                    { id: 'kpiNoEscalate', label: 'Case Tidak Perlu Dieskalasi', keys: ['CASE TIDAK PERLU DIESKALASI'] },
                    { id: 'kpiDummy', label: 'Penggunaan Nomer Dummy', keys: ['PENGGUNAAN NOMER DUMMY', 'NOMER DUMMY'] },
                    { id: 'kpiDouble', label: 'Double Ticket', keys: ['DOUBLE TICKET'] },
                    { id: 'kpiSalahTujuan', label: 'Salah Tujuan', keys: ['SALAH TUJUAN'] }
                ];
            } else {
                // Mobile: Ekstrak seluruh kategori unik pada Kolom L sheet Data2
                const distinctL = [...new Set(allRecords.map(r => r[11]).filter(x => x && String(x).trim() !== ""))].sort();
                categoriesToDisplay = distinctL.map((cName, idx) => ({
                    id: 'kpiMobile_' + idx,
                    label: cName,
                    keys: [cName.toUpperCase()]
                }));
            }

            const counts = {};
            categoriesToDisplay.forEach(c => { counts[c.id] = 0; });

            data.forEach(row => {
                let valL = String(row[11] || '').toUpperCase().trim();
                for (let i = 0; i < categoriesToDisplay.length; i++) {
                    const c = categoriesToDisplay[i];
                    if (c.keys.some(k => valL === k || valL.includes(k))) {
                        counts[c.id]++;
                        break;
                    }
                }
            });

            container.innerHTML = categoriesToDisplay.map((c) => {
                const theme = getCategoryTheme(c.label);
                return `
                    <div class="kpi-card ${theme.theme}" style="cursor:pointer;" onclick="filterDashboardByKategori('${escapeHtml(c.label)}')" title="Klik untuk memfilter: ${escapeHtml(c.label)}">
                        <div class="kpi-icon"><i class="fa-solid ${theme.icon}"></i></div>
                        <div class="kpi-label" title="${escapeHtml(c.label)}">${escapeHtml(c.label)}</div>
                        <div class="kpi-value" id="${c.id}">0</div>
                    </div>
                `;
            }).join('');

            categoriesToDisplay.forEach(c => {
                const el = document.getElementById(c.id);
                if (el) animateCountUp(el, counts[c.id]);
            });
        }

        function destroyChart(chartKey) {
            if (activeCharts[chartKey]) { activeCharts[chartKey].destroy(); }
        }

        function createDailyCategoryChart(canvasId, chartKey, data, categories, timelineSlots, isAllMonths, fBln, color) {
            destroyChart(chartKey);

            let filteredRows = data.filter(row => {
                let valL = String(row[11]).toUpperCase().trim();
                return categories.some(cat => valL.includes(cat));
            });

            let dailyCounts = {};
            timelineSlots.forEach(s => dailyCounts[s.key] = 0);
            filteredRows.forEach(row => {
                let rTgl = parseInt(row[0], 10);
                let rBln = String(row[1] || '').trim().toUpperCase();
                let key = isAllMonths ? (rBln + '_' + rTgl) : (fBln.toUpperCase() + '_' + rTgl);
                if (dailyCounts[key] !== undefined) dailyCounts[key]++;
            });

            activeCharts[chartKey] = new Chart(document.getElementById(canvasId), {
                type: 'line',
                data: {
                    labels: timelineSlots.map(s => s.label),
                    datasets: [{
                        label: 'Jumlah Temuan',
                        data: timelineSlots.map(s => dailyCounts[s.key]),
                        borderColor: color,
                        backgroundColor: (typeof color === 'string' && color.startsWith('#')) ? color + '15' : 'rgba(163,0,48,0.08)',
                        fill: true,
                        borderWidth: 2.2,
                        tension: 0.38,
                        pointRadius: 2.2,
                        pointHoverRadius: 5,
                        pointBackgroundColor: color,
                        pointBorderColor: '#ffffff',
                        pointBorderWidth: 1.5
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: { display: false },
                        datalabels: { display: false },
                        tooltip: {
                            callbacks: {
                                title: function (ctx) {
                                    const idx = ctx[0].dataIndex;
                                    const s = timelineSlots[idx];
                                    return isAllMonths ? `Tgl ${s.label}` : `Tgl ${s.tgl} ${fBln}`;
                                }
                            }
                        }
                    },
                    scales: {
                        y: {
                            ticks: { color: '#94A3B8', font: { family: 'Poppins', size: 9 }, stepSize: 1 },
                            grid: { color: 'rgba(241, 245, 249, 0.85)', drawBorder: false },
                            border: { display: false },
                            beginAtZero: true
                        },
                        x: {
                            ticks: {
                                color: '#94A3B8',
                                font: { family: 'Poppins', size: isAllMonths ? 8.5 : 9 },
                                maxRotation: isAllMonths ? 45 : 0
                            },
                            grid: { display: false },
                            border: { display: false }
                        }
                    }
                }
            });
        }

        function renderMonthlyChart(data) {
            destroyChart('monthly');
            const monthKeys = ["JANUARI", "FEBRUARI", "MARET", "APRIL", "MEI", "JUNI", "JULI", "AGUSTUS", "SEPTEMBER", "OKTOBER", "NOVEMBER", "DESEMBER"];
            const monthLabels = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
            const palette = ['#A30030', '#2563EB', '#0D9488', '#8B5CF6', '#F59E0B', '#EC4899', '#06B6D4', '#64748B'];

            let units = [...new Set(data.map(row => String(row[9]).trim().toUpperCase()).filter(u => u !== ""))].sort();

            let countMap = {};
            units.forEach(u => { countMap[u] = {}; monthKeys.forEach(m => countMap[u][m] = 0); });
            data.forEach(row => {
                let bln = String(row[1]).trim().toUpperCase();
                let unit = String(row[9]).trim().toUpperCase();
                if (countMap[unit] && countMap[unit][bln] !== undefined) countMap[unit][bln]++;
            });

            let datasets = units.map((u, idx) => ({
                label: u,
                data: monthKeys.map(m => countMap[u][m]),
                backgroundColor: palette[idx % palette.length],
                borderRadius: { topLeft: 5, topRight: 5 },
                borderSkipped: false,
                maxBarThickness: 28
            }));

            activeCharts['monthly'] = new Chart(document.getElementById('chartMonthly'), {
                type: 'bar',
                data: { labels: monthLabels, datasets: datasets },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            display: true,
                            labels: {
                                color: '#475569',
                                font: { family: 'Poppins', size: 11, weight: '600' },
                                usePointStyle: true,
                                pointStyle: 'circle',
                                boxWidth: 8,
                                boxHeight: 8,
                                padding: 16
                            }
                        },
                        datalabels: {
                            ...barDataLabelOptions,
                            color: '#64748B',
                            font: { family: 'Poppins', weight: '600', size: 8.5 }
                        }
                    },
                    scales: {
                        y: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 }, stepSize: 1 },
                            grid: { color: 'rgba(226, 232, 240, 0.7)', drawBorder: false },
                            border: { display: false },
                            beginAtZero: true,
                            title: { display: true, text: 'Jumlah Tiket', color: '#64748B', font: { family: 'Poppins', size: 11, weight: '600' } }
                        },
                        x: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 11, weight: '500' } },
                            grid: { display: false },
                            border: { display: false }
                        }
                    }
                }
            });
        }

        function renderCharts(data, rawBaseData) {
            Chart.defaults.font.family = 'Poppins';
            renderMonthlyChart(data);

            const fTgl = (document.getElementById('filTanggal')?.value || '').trim();
            const fBln = document.getElementById('filBulan').value.trim();
            const fStatusSgh = (document.getElementById('filStatusSanggahan')?.value || 'net').trim();

            // Bangun slot waktu (timelineSlots):
            // Jika "Semua Bulan" (fBln === ""), tampilkan pergerakan harian per bulan (1 Sep, 2 Sep ... 1 Okt, 2 Okt)
            // Jika bulan tertentu dipilih, tampilkan tanggal 1 s/d 31 bulan tersebut.
            let timelineSlots = [];
            const isAllMonths = (fBln === "");

            if (isAllMonths) {
                let mapSlots = {};
                const sourceForTimeline = (rawBaseData && rawBaseData.length > 0) ? rawBaseData : data;
                sourceForTimeline.forEach(row => {
                    let rTgl = String(row[0] || '').trim();
                    let rBln = String(row[1] || '').trim().toUpperCase();
                    if (!rTgl || !rBln) return;
                    let numTgl = parseInt(rTgl, 10);
                    if (isNaN(numTgl)) return;

                    let key = rBln + '_' + numTgl;
                    if (!mapSlots[key]) {
                        mapSlots[key] = {
                            key: key,
                            bln: rBln,
                            tgl: numTgl,
                            monthOrder: urutanBulanIndo[rBln] || 99,
                            label: `${numTgl} ${singkatanBulanIndo[rBln] || rBln}`
                        };
                    }
                });

                timelineSlots = Object.values(mapSlots).sort((a, b) => {
                    if (a.monthOrder !== b.monthOrder) return a.monthOrder - b.monthOrder;
                    return a.tgl - b.tgl;
                });

                if (timelineSlots.length === 0) {
                    timelineSlots = Array.from({ length: 31 }, (_, i) => ({
                        key: 'TGL_' + (i + 1),
                        bln: '',
                        tgl: i + 1,
                        monthOrder: 0,
                        label: String(i + 1)
                    }));
                }
            } else {
                let dates = [];
                if (fTgl !== "") {
                    const parsed = parseInt(fTgl, 10);
                    const maxD = (!isNaN(parsed) && parsed >= 1 && parsed <= 31) ? parsed : 31;
                    dates = Array.from({ length: maxD }, (_, i) => i + 1);
                } else {
                    dates = [...new Set(data.map(row => parseInt(row[0], 10)).filter(d => !isNaN(d)))].sort((a, b) => a - b);
                    if (dates.length === 0) {
                        dates = Array.from({ length: 31 }, (_, i) => i + 1);
                    }
                }
                timelineSlots = dates.map(d => ({
                    key: fBln.toUpperCase() + '_' + d,
                    bln: fBln.toUpperCase(),
                    tgl: d,
                    monthOrder: urutanBulanIndo[fBln.toUpperCase()] || 0,
                    label: String(d)
                }));
            }

            // 1. GRAFIK STANDARD BULANAN UTAMA (Trend Bad Tiket Daily - Stacked Bad Tiket Net + Sanggahan Diterima)
            destroyChart('unitCategory');
            const subFilterL = document.getElementById('filGraphKolomL').value.trim().toUpperCase();
            let baseForDaily = (rawBaseData && rawBaseData.length > 0) ? rawBaseData : data;
            if (subFilterL !== "") {
                baseForDaily = baseForDaily.filter(row => String(row[11]).trim().toUpperCase() === subFilterL);
            }

            let countsNet = {};
            let countsSgh = {};
            let countsAll = {};
            timelineSlots.forEach(s => {
                countsNet[s.key] = 0;
                countsSgh[s.key] = 0;
                countsAll[s.key] = 0;
            });

            baseForDaily.forEach(row => {
                let rTgl = parseInt(row[0], 10);
                let rBln = String(row[1] || '').trim().toUpperCase();
                let key = isAllMonths ? (rBln + '_' + rTgl) : (fBln.toUpperCase() + '_' + rTgl);

                if (countsAll[key] !== undefined) {
                    countsAll[key]++;
                    if (isSanggahanDiterima(row)) {
                        countsSgh[key]++;
                    } else {
                        countsNet[key]++;
                    }
                }
            });

            let dailyDatasets = [];
            let isStacked = true;

            if (fStatusSgh === 'only_sanggahan') {
                isStacked = false;
                dailyDatasets = [{
                    label: 'Sanggahan Diterima (Kolom O)',
                    data: timelineSlots.map(s => countsSgh[s.key]),
                    backgroundColor: '#10B981',
                    borderRadius: { topLeft: 6, topRight: 6 },
                    borderSkipped: false,
                    maxBarThickness: 24
                }];
            } else {
                dailyDatasets = [
                    {
                        label: 'Bad Tiket Bersih (Net)',
                        data: timelineSlots.map(s => countsNet[s.key]),
                        backgroundColor: '#A30030',
                        borderRadius: { topLeft: 4, topRight: 4 },
                        borderSkipped: false,
                        maxBarThickness: 24,
                        stack: 'dailyStack'
                    },
                    {
                        label: 'Sanggahan Diterima (Kolom O)',
                        data: timelineSlots.map(s => countsSgh[s.key]),
                        backgroundColor: '#10B981',
                        borderRadius: { topLeft: 4, topRight: 4 },
                        borderSkipped: false,
                        maxBarThickness: 24,
                        stack: 'dailyStack'
                    }
                ];
            }

            activeCharts['unitCategory'] = new Chart(document.getElementById('chartUnitCategory'), {
                type: 'bar',
                data: {
                    labels: timelineSlots.map(s => s.label),
                    datasets: dailyDatasets
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            display: true,
                            position: 'top',
                            labels: {
                                color: '#475569',
                                font: { family: 'Poppins', size: 10, weight: '600' },
                                usePointStyle: true,
                                pointStyle: 'circle',
                                boxWidth: 7,
                                padding: 12
                            }
                        },
                        tooltip: {
                            callbacks: {
                                title: function (ctx) {
                                    const idx = ctx[0].dataIndex;
                                    const s = timelineSlots[idx];
                                    return isAllMonths ? `Tanggal ${s.label}` : `Tanggal ${s.tgl} ${fBln}`;
                                },
                                footer: function (ctx) {
                                    const idx = ctx[0].dataIndex;
                                    const key = timelineSlots[idx].key;
                                    const total = countsAll[key];
                                    const net = countsNet[key];
                                    const sgh = countsSgh[key];
                                    const pct = total > 0 ? ((sgh / total) * 100).toFixed(1) : 0;
                                    return `────────────────────\nTotal All Bad Tiket: ${total} tiket\nNet Bad Tiket: ${net} tiket\nSanggahan Diterima: ${sgh} tiket (${pct}%)`;
                                }
                            }
                        },
                        datalabels: {
                            ...barDataLabelOptions,
                            color: '#64748B',
                            font: { family: 'Poppins', weight: '600', size: 8.5 },
                            formatter: function (value) {
                                return value > 0 ? value : '';
                            }
                        }
                    },
                    scales: {
                        y: {
                            stacked: isStacked,
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 }, stepSize: 1 },
                            grid: { color: 'rgba(226, 232, 240, 0.7)', drawBorder: false },
                            border: { display: false },
                            beginAtZero: true
                        },
                        x: {
                            stacked: isStacked,
                            ticks: {
                                color: '#64748B',
                                font: { family: 'Poppins', size: isAllMonths ? 8.5 : 10 },
                                maxRotation: isAllMonths ? 45 : 0
                            },
                            grid: { display: false },
                            border: { display: false }
                        }
                    }
                }
            });

            // RENDER 6 GRAFIK LINE KATEGORI (Daily per bulan tersinkronisasi)
            // Menyesuaikan Breakdown Kategori secara otomatis:
            // - Fixed Broadband: 6 kategori bawaan Fixed
            // - Mobile: 6 kategori tertinggi dari Sheet Data2
            const catSlots = [
                { canvasId: 'chartMandatory', chartKey: 'catMandatory', titleId: 'titleChartCat1', btnId: 'btnDownloadCat1', boxId: 'boxChartCat1' },
                { canvasId: 'chartKip', chartKey: 'catKip', titleId: 'titleChartCat2', btnId: 'btnDownloadCat2', boxId: 'boxChartCat2' },
                { canvasId: 'chartNoEscalate', chartKey: 'catNoEscalate', titleId: 'titleChartCat3', btnId: 'btnDownloadCat3', boxId: 'boxChartCat3' },
                { canvasId: 'chartDummy', chartKey: 'catDummy', titleId: 'titleChartCat4', btnId: 'btnDownloadCat4', boxId: 'boxChartCat4' },
                { canvasId: 'chartDouble', chartKey: 'catDouble', titleId: 'titleChartCat5', btnId: 'btnDownloadCat5', boxId: 'boxChartCat5' },
                { canvasId: 'chartSalahTujuan', chartKey: 'catSalahTujuan', titleId: 'titleChartCat6', btnId: 'btnDownloadCat6', boxId: 'boxChartCat6' }
            ];

            let activeTargetCats = [];
            if (currentDomain === 'fixed') {
                activeTargetCats = [
                    { label: 'Mandatory Ticket', keys: ['MANDATORY TICKET'], color: '#A30030' },
                    { label: 'KIP Tidak Sesuai', keys: ['KIP TIDAK SESUAI'], color: '#10B981' },
                    { label: 'Case Tidak Perlu Dieskalasi', keys: ['CASE TIDAK PERLU DIESKALASI'], color: '#2563EB' },
                    { label: 'Penggunaan Nomer Dummy', keys: ['PENGGUNAAN NOMER DUMMY', 'NOMER DUMMY'], color: '#D97706' },
                    { label: 'Double Ticket', keys: ['DOUBLE TICKET'], color: '#7C3AED' },
                    { label: 'Salah Tujuan', keys: ['SALAH TUJUAN'], color: '#0891B2' }
                ];
            } else {
                // Mobile: Urutkan kategori teratas berdasarkan frekuensi di dataset Mobile
                const mobFreq = {};
                allRecords.forEach(r => {
                    const kt = String(r[11] || '').trim();
                    if (kt) mobFreq[kt] = (mobFreq[kt] || 0) + 1;
                });
                const colorPalette = ['#A30030', '#2563EB', '#7C3AED', '#10B981', '#D97706', '#0891B2', '#DC2626', '#0D9488'];
                const sortedMob = Object.keys(mobFreq).sort((a, b) => mobFreq[b] - mobFreq[a]);
                activeTargetCats = sortedMob.slice(0, 6).map((cName, idx) => ({
                    label: cName,
                    keys: [cName.toUpperCase()],
                    color: colorPalette[idx % colorPalette.length]
                }));
            }

            catSlots.forEach((slot, idx) => {
                const boxEl = document.getElementById(slot.boxId);
                const titleEl = document.getElementById(slot.titleId);
                const btnEl = document.getElementById(slot.btnId);

                if (idx < activeTargetCats.length) {
                    if (boxEl) boxEl.style.display = 'block';
                    const target = activeTargetCats[idx];
                    if (titleEl) {
                        titleEl.innerHTML = `<i class="fa-solid fa-chart-line text-glow-red me-2"></i>Trend Bad Tiket Kategori ${escapeHtml(target.label)}`;
                        titleEl.title = target.label;
                    }
                    if (btnEl) {
                        const safeSlug = target.label.replace(/[^a-zA-Z0-9]/g, '_');
                        btnEl.setAttribute('onclick', `downloadChartPng('${slot.chartKey}', 'Trend_${safeSlug}')`);
                    }
                    createDailyCategoryChart(slot.canvasId, slot.chartKey, data, target.keys, timelineSlots, isAllMonths, fBln, target.color);
                } else {
                    destroyChart(slot.chartKey);
                    if (boxEl) boxEl.style.display = 'none';
                }
            });

            // Trend per SPV
            destroyChart('spv');
            let countSPV = {};
            data.forEach(row => { if (row[8]) countSPV[row[8]] = (countSPV[row[8]] || 0) + 1; });
            let sortedSPV = Object.entries(countSPV).sort((a, b) => b[1] - a[1]).slice(0, 10);
            activeCharts['spv'] = new Chart(document.getElementById('chartSPV'), {
                type: 'bar',
                data: {
                    labels: sortedSPV.map(x => x[0]),
                    datasets: [{
                        label: 'Temuan',
                        data: sortedSPV.map(x => x[1]),
                        backgroundColor: '#A30030',
                        borderRadius: { topLeft: 6, topRight: 6 },
                        borderSkipped: false,
                        maxBarThickness: 28
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: { legend: { display: false }, datalabels: barDataLabelOptions },
                    scales: {
                        y: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 } },
                            grid: { color: 'rgba(226, 232, 240, 0.7)', drawBorder: false },
                            border: { display: false },
                            beginAtZero: true
                        },
                        x: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 } },
                            grid: { display: false },
                            border: { display: false }
                        }
                    }
                }
            });

            // Trend per TL
            destroyChart('tl');
            let countTL = {};
            data.forEach(row => { if (row[7]) countTL[row[7]] = (countTL[row[7]] || 0) + 1; });
            let sortedTL = Object.entries(countTL).sort((a, b) => b[1] - a[1]).slice(0, 10);
            activeCharts['tl'] = new Chart(document.getElementById('chartTL'), {
                type: 'bar',
                data: {
                    labels: sortedTL.map(x => x[0]),
                    datasets: [{
                        label: 'Temuan',
                        data: sortedTL.map(x => x[1]),
                        backgroundColor: '#2563EB',
                        borderRadius: { topLeft: 6, topRight: 6 },
                        borderSkipped: false,
                        maxBarThickness: 28
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: { legend: { display: false }, datalabels: barDataLabelOptions },
                    scales: {
                        y: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 } },
                            grid: { color: 'rgba(226, 232, 240, 0.7)', drawBorder: false },
                            border: { display: false },
                            beginAtZero: true
                        },
                        x: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 } },
                            grid: { display: false },
                            border: { display: false }
                        }
                    }
                }
            });
        }

        // LOGIKA RENDER GRAFIK SEKSI (Vs) BERDAMPINGAN
        function renderVsChart() {
            destroyChart('comparisonVs');

            const vsBefore = document.getElementById('vsBulanBefore').value.trim();
            const vsAfter = document.getElementById('vsBulanAfter').value.trim();
            const vsFilterL = document.getElementById('vsFilterKolomL').value.trim().toUpperCase();
            const activeUnit = document.getElementById('filUnit').value.trim().toUpperCase();
            const selStatusSgh = document.getElementById('filStatusSanggahan');
            const fStatusSgh = selStatusSgh ? selStatusSgh.value : 'net';

            // Ambil filter tanggal aktif dari Dashboard (MTD: 1 s/d tanggal dipilih)
            const fTgl = (document.getElementById('filTanggal')?.value || '').trim();
            let maxDay = 31;
            if (fTgl !== "") {
                const parsed = parseInt(fTgl, 10);
                if (!isNaN(parsed) && parsed >= 1 && parsed <= 31) maxDay = parsed;
            }

            let dates1to31 = Array.from({ length: maxDay }, (_, i) => String(i + 1));

            let countsBefore = {};
            let countsAfter = {};
            dates1to31.forEach(d => { countsBefore[d] = 0; countsAfter[d] = 0; });

            allRecords.forEach(row => {
                let rowBln = String(row[1]).trim();
                let rowUnit = String(row[9]).trim().toUpperCase();
                let rowL = String(row[11]).trim().toUpperCase();
                let rowTgl = String(row[0]).trim();

                let rDate = parseInt(rowTgl, 10);
                if (!isNaN(rDate) && rDate > maxDay) return;
                if (fStatusSgh === 'net' && isSanggahanDiterima(row)) return;
                if (fStatusSgh === 'only_sanggahan' && !isSanggahanDiterima(row)) return;

                let matchUnit = (activeUnit === "" || rowUnit === activeUnit);
                let matchL = (vsFilterL === "" || rowL === vsFilterL);

                if (matchUnit && matchL) {
                    if (rowBln === vsBefore && countsBefore[rowTgl] !== undefined) {
                        countsBefore[rowTgl]++;
                    }
                    if (rowBln === vsAfter && countsAfter[rowTgl] !== undefined) {
                        countsAfter[rowTgl]++;
                    }
                }
            });

            activeCharts['comparisonVs'] = new Chart(document.getElementById('chartComparisonVs'), {
                type: 'bar',
                data: {
                    labels: dates1to31,
                    datasets: [
                        {
                            label: vsBefore ? `Bulan: ${vsBefore}` : 'Bulan Sebelum',
                            data: dates1to31.map(d => countsBefore[d]),
                            backgroundColor: '#A30030',
                            borderRadius: { topLeft: 5, topRight: 5 },
                            borderSkipped: false,
                            maxBarThickness: 18,
                            barPercentage: 0.85,
                            categoryPercentage: 0.85
                        },
                        {
                            label: vsAfter ? `Bulan: ${vsAfter}` : 'Bulan Sesudah',
                            data: dates1to31.map(d => countsAfter[d]),
                            backgroundColor: '#2563EB',
                            borderRadius: { topLeft: 5, topRight: 5 },
                            borderSkipped: false,
                            maxBarThickness: 18,
                            barPercentage: 0.85,
                            categoryPercentage: 0.85
                        }
                    ]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            display: true,
                            labels: {
                                color: '#475569',
                                font: { family: 'Poppins', size: 11, weight: '600' },
                                usePointStyle: true,
                                pointStyle: 'circle',
                                boxWidth: 8,
                                boxHeight: 8,
                                padding: 16
                            }
                        },
                        datalabels: barDataLabelOptions
                    },
                    scales: {
                        y: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 }, stepSize: 1 },
                            grid: { color: 'rgba(226, 232, 240, 0.7)', drawBorder: false },
                            border: { display: false },
                            beginAtZero: true,
                            title: { display: true, text: 'Jumlah Tiket', color: '#64748B', font: { family: 'Poppins', size: 11, weight: '600' } }
                        },
                        x: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 } },
                            grid: { display: false },
                            border: { display: false }
                        }
                    }
                }
            });
        }

        function populateSpvTlVsFilters() {
            const fillMonthPair = (idBefore, idAfter) => {
                const selBefore = document.getElementById(idBefore);
                const selAfter = document.getElementById(idAfter);
                selBefore.innerHTML = "";
                selAfter.innerHTML = "";
                bulanTerurutGlobal.forEach((val) => {
                    if (val && val.toString().trim() !== "") {
                        selBefore.options[selBefore.options.length] = new Option(val, val);
                        selAfter.options[selAfter.options.length] = new Option(val, val);
                    }
                });
                if (selBefore.options.length > 0) selBefore.selectedIndex = 0;
                if (selAfter.options.length > 1) selAfter.selectedIndex = 1;
                else if (selAfter.options.length > 0) selAfter.selectedIndex = 0;
            };
            fillMonthPair('vsSpvBulanBefore', 'vsSpvBulanAfter');
            fillMonthPair('vsTlBulanBefore', 'vsTlBulanAfter');

            const listSPV = [...new Set(allRecords.map(row => row[8]).filter(x => x && x.toString().trim() !== ""))]
                .sort((a, b) => String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: 'base' }));
            const listTL = [...new Set(allRecords.map(row => row[7]).filter(x => x && x.toString().trim() !== ""))]
                .sort((a, b) => String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: 'base' }));

            const selSpvNama = document.getElementById('vsSpvNama');
            listSPV.forEach(val => { selSpvNama.options[selSpvNama.options.length] = new Option(val, val); });

            const selTlNama = document.getElementById('vsTlNama');
            listTL.forEach(val => { selTlNama.options[selTlNama.options.length] = new Option(val, val); });

            const listL = [...new Set(allRecords.map(row => row[11]).filter(x => x && x.toString().trim() !== ""))].sort();
            const selSpvL = document.getElementById('vsSpvKolomL');
            const selTlL = document.getElementById('vsTlKolomL');
            listL.forEach(val => {
                selSpvL.options[selSpvL.options.length] = new Option(val, val);
                selTlL.options[selTlL.options.length] = new Option(val, val);
            });
        }

