        function renderTlVsChart() {
            destroyChart('tlVs');

            const vsBefore = document.getElementById('vsTlBulanBefore').value.trim();
            const vsAfter = document.getElementById('vsTlBulanAfter').value.trim();
            const namaTl = document.getElementById('vsTlNama').value.trim().toUpperCase();
            const filterL = document.getElementById('vsTlKolomL').value.trim().toUpperCase();
            const selStatusSgh = document.getElementById('filStatusSanggahan');
            const fStatusSgh = selStatusSgh ? selStatusSgh.value : 'net';

            // Ambil filter tanggal aktif dari Dashboard (MTD: 1 s/d tanggal dipilih)
            const fTgl = (document.getElementById('filTanggal')?.value || '').trim();
            let maxDay = 31;
            if (fTgl !== "") {
                const parsed = parseInt(fTgl, 10);
                if (!isNaN(parsed) && parsed >= 1 && parsed <= 31) maxDay = parsed;
            }

            let dates1to31 = Array.from({ length: maxDay }, (_, i) => String(i + 1));
            let countsBefore = {}, countsAfter = {};
            dates1to31.forEach(d => { countsBefore[d] = 0; countsAfter[d] = 0; });

            allRecords.forEach(row => {
                let rowBln = String(row[1]).trim();
                let rowTl = String(row[7]).trim().toUpperCase();
                let rowL = String(row[11]).trim().toUpperCase();
                let rowTgl = String(row[0]).trim();

                let rDate = parseInt(rowTgl, 10);
                if (!isNaN(rDate) && rDate > maxDay) return;
                if (fStatusSgh === 'net' && isSanggahanDiterima(row)) return;
                if (fStatusSgh === 'only_sanggahan' && !isSanggahanDiterima(row)) return;

                let matchTl = (namaTl === "" || rowTl === namaTl);
                let matchL = (filterL === "" || rowL === filterL);
                if (matchTl && matchL) {
                    if (rowBln === vsBefore && countsBefore[rowTgl] !== undefined) countsBefore[rowTgl]++;
                    if (rowBln === vsAfter && countsAfter[rowTgl] !== undefined) countsAfter[rowTgl]++;
                }
            });

            activeCharts['tlVs'] = new Chart(document.getElementById('chartTlVs'), {
                type: 'bar',
                data: {
                    labels: dates1to31,
                    datasets: [
                        {
                            label: vsBefore ? `Bulan: ${vsBefore}` : 'Bulan Sebelum',
                            data: dates1to31.map(d => countsBefore[d]),
                            backgroundColor: '#A30030',
                            borderRadius: { topLeft: 5, topRight: 5 },
                            borderSkipped: false,
                            maxBarThickness: 18,
                            barPercentage: 0.85,
                            categoryPercentage: 0.85
                        },
                        {
                            label: vsAfter ? `Bulan: ${vsAfter}` : 'Bulan Sesudah',
                            data: dates1to31.map(d => countsAfter[d]),
                            backgroundColor: '#2563EB',
                            borderRadius: { topLeft: 5, topRight: 5 },
                            borderSkipped: false,
                            maxBarThickness: 18,
                            barPercentage: 0.85,
                            categoryPercentage: 0.85
                        }
                    ]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            display: true,
                            labels: {
                                color: '#475569',
                                font: { family: 'Poppins', size: 11, weight: '600' },
                                usePointStyle: true,
                                pointStyle: 'circle',
                                boxWidth: 8,
                                boxHeight: 8,
                                padding: 16
                            }
                        },
                        datalabels: barDataLabelOptions
                    },
                    scales: {
                        y: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 }, stepSize: 1 },
                            grid: { color: 'rgba(226, 232, 240, 0.7)', drawBorder: false },
                            border: { display: false },
                            beginAtZero: true,
                            title: { display: true, text: 'Jumlah Tiket', color: '#64748B', font: { family: 'Poppins', size: 11, weight: '600' } }
                        },
                        x: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 } },
                            grid: { display: false },
                            border: { display: false }
                        }
                    }
                }
            });
        }

        function renderAllAgents(data) {
            let agentMap = {};
            data.forEach(row => {
                let agent = row[6];
                let unit = row[9];
                if (agent) {
                    if (!agentMap[agent]) agentMap[agent] = { count: 0, unit: unit };
                    agentMap[agent].count++;
                }
            });

            let sortedAgents = Object.entries(agentMap).sort((a, b) => b[1].count - a[1].count);

            let tbody = document.getElementById('topAgentTable');
            tbody.innerHTML = "";

            if (sortedAgents.length === 0) {
                tbody.innerHTML = `<tr><td colspan="4" class="text-center py-3 text-dark">Tidak ada data ditemukan</td></tr>`;
                return;
            }

            // OPTIMASI: sebelumnya tiap baris di-append satu-satu (appendChild di dalam loop),
            // yang berarti reflow browser terpicu berkali-kali untuk ratusan agent.
            // Sekarang HTML dirakit sebagai string dulu, baru di-set sekali lewat innerHTML --
            // hasil tampilan & data sama persis, cuma prosesnya lebih cepat.
            let rowsHtml = sortedAgents.map((item, index) => `
          <tr>
            <td><span class="badge badge-solid-gray px-2 py-2">${index + 1}</span></td>
            <td><span class="agent-name-style">${item[0]}</span></td>
            <td><span class="unit-name-style">${item[1].unit || '-'}</span></td>
            <td class="text-end fw-bold">
              <span class="clickable-ticket" onclick="showAgentPopupDetail('${escapeJsAttr(item[0])}')">${item[1].count} Tiket</span>
            </td>
          </tr>
        `).join('');
            tbody.innerHTML = rowsHtml;
        }

        function showAgentPopupDetail(agentName) {
            document.getElementById('modalAgentTitle').innerText = "Detail Temuan Bad Ticket: " + agentName;

            let matchedDetails = currentFilteredRecords.filter(row => String(row[6]).trim() === agentName);
            document.getElementById('modalTotalCount').innerText = "Total: " + matchedDetails.length + " tiket";
            let tbody = document.getElementById('modalTableBody');
            tbody.innerHTML = "";

            matchedDetails.forEach(row => {
                let tr = document.createElement('tr');
                tr.innerHTML = `
          <td>${row[3] || '-'}</td>
          <td>${row[5] || '-'}</td>
          <td><strong>${row[6] || '-'}</strong></td>
          <td>${row[7] || '-'}</td>
          <td>${row[8] || '-'}</td>
          <td>${row[9] || '-'}</td>
          <td>${row[4] || '-'}</td>
          <td><span class="badge bg-dark">${row[10] || '-'}</span></td>
          <td><span class="text-danger fw-bold">${row[11] || '-'}</span></td>
          <td class="col-detil-m"><small>${row[12] || '-'}</small></td>
          <td class="col-notes-n"><small>${maskNotesKolomN(row[13]) || '-'}</small></td>
          <td>${isSanggahanDiterima(row) ? '<span class="badge bg-success" style="font-size:0.7rem;"><i class="fa-solid fa-circle-check me-1"></i>SANGGAHAN DITERIMA</span>' : (row[14] || '-')}</td>
          <td>${row[15] || '-'}</td>
        `;
                tbody.appendChild(tr);
            });

            // Terapkan dulu pakai nilai cache yang ada sekarang (supaya tidak ada "flash" kolom
            // salah sesaat), LALU segera ambil ulang nilai TERBARU langsung dari server --
            // ini menghilangkan race condition kalau loadColumnVisibilitySettings() saat login
            // belum sempat selesai ketika modal ini dibuka (mis. langsung diklik habis login).
            applyAgentDetailColumnVisibility();
            google.script.run
                .withSuccessHandler(function (res) {
                    if (res && res.success) {
                        globalHideDetilForUser = !!res.hideDetilForUser;
                        globalHideNotesForUser = !!res.hideNotesForUser;
                    }
                    applyAgentDetailColumnVisibility();
                })
                .withFailureHandler(function () {
                    // Gagal fetch -> tetap pakai nilai cache yang sudah diterapkan di atas
                })
                .getColumnVisibilitySettings(currentUsername);

            agentModalBootstrap.show();
        }

        // Menerapkan class hide-col-detil/hide-col-notes ke tabel modal, dan menyiapkan
        // toolbar toggle (khusus superadmin) sesuai nilai globalHideDetilForUser/globalHideNotesForUser
        // yang sedang berlaku saat ini.
        function applyAgentDetailColumnVisibility() {
            const table = document.getElementById('agentDetailTable');
            if (!table) return;
            const isSuperadmin = (currentUserRole === 'superadmin');
            table.classList.toggle('hide-col-detil', !isSuperadmin && globalHideDetilForUser);
            table.classList.toggle('hide-col-notes', !isSuperadmin && globalHideNotesForUser);

            const toggleBar = document.getElementById('modalColumnToggle');
            if (toggleBar) {
                toggleBar.style.display = isSuperadmin ? 'flex' : 'none';
                if (isSuperadmin) {
                    document.getElementById('toggleHideDetil').checked = globalHideDetilForUser;
                    document.getElementById('toggleHideNotes').checked = globalHideNotesForUser;
                    document.getElementById('columnToggleSaveStatus').innerText = '';
                }
            }
        }

        // Pengaturan visibilitas kolom GLOBAL (permanen, tersimpan di server via Script Properties).
        // Dimuat sekali setelah login (lihat loadColumnVisibilitySettings), lalu dipakai setiap
        // kali modal detail agent dibuka -- BUKAN preferensi pribadi/sesi, tapi kebijakan sistem
        // yang berlaku untuk SEMUA akun role "user" sampai diubah lagi oleh superadmin.
        let globalHideDetilForUser = false;
        let globalHideNotesForUser = false;

        function loadColumnVisibilitySettings() {
            google.script.run.withSuccessHandler(function (res) {
                if (res && res.success) {
                    globalHideDetilForUser = !!res.hideDetilForUser;
                    globalHideNotesForUser = !!res.hideNotesForUser;
                }
            }).getColumnVisibilitySettings(currentUsername);
        }

        // Dipanggil saat superadmin mencentang/membuka centang salah satu checkbox --
        // langsung disimpan permanen ke server, berlaku untuk semua akun role "user"
        function toggleModalColumn() {
            const hideDetil = document.getElementById('toggleHideDetil').checked;
            const hideNotes = document.getElementById('toggleHideNotes').checked;
            const statusEl = document.getElementById('columnToggleSaveStatus');
            statusEl.style.color = '#6B7280';
            statusEl.innerText = 'Menyimpan...';

            google.script.run
                .withSuccessHandler(function (res) {
                    if (res && res.success) {
                        globalHideDetilForUser = hideDetil;
                        globalHideNotesForUser = hideNotes;
                        statusEl.style.color = '#10B981';
                        statusEl.innerText = 'âœ“ Tersimpan';
                        setTimeout(() => { statusEl.innerText = ''; }, 2500);
                    } else {
                        // Gagal simpan -> kembalikan checkbox ke posisi semula
                        document.getElementById('toggleHideDetil').checked = globalHideDetilForUser;
                        document.getElementById('toggleHideNotes').checked = globalHideNotesForUser;
                        statusEl.style.color = '#A30030';
                        statusEl.innerText = (res && res.error) ? res.error : 'Gagal menyimpan';
                    }
                })
                .withFailureHandler(function (err) {
                    document.getElementById('toggleHideDetil').checked = globalHideDetilForUser;
                    document.getElementById('toggleHideNotes').checked = globalHideNotesForUser;
                    statusEl.style.color = '#A30030';
                    statusEl.innerText = 'Gagal menyimpan';
                    console.error(err);
                })
                .setColumnVisibilitySettings(currentUsername, hideDetil, hideNotes);
        }

        function escapeHtml(str) {
            if (!str) return '';
            return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
        }

        // Escape khusus untuk nilai yang disisipkan sebagai ARGUMEN JAVASCRIPT di dalam
        // atribut onclick="...('nilai')". BEDA dengan escapeHtml(): tanda kutip satu (')
        // di sini di-escape jadi \' (backslash-quote, level JS), BUKAN &#039; (entity HTML).
        //
        // Kenapa penting: browser men-decode entity HTML pada atribut SEBELUM kode JS di
        // dalamnya dieksekusi. Jadi &#039; akan berubah balik jadi ' persis sebelum JS
        // membacanya -- yang artinya nama seperti "AHMAD SAFI'I" akan merusak sintaks JS
        // (string ditutup lebih awal) dan tombol onclick jadi tidak berfungsi sama sekali.
        function escapeJsAttr(str) {
            if (str === null || str === undefined) return '';
            return String(str)
                .replace(/\\/g, '\\\\')
                .replace(/&/g, '&amp;')
                .replace(/"/g, '&quot;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/'/g, "\\'");
        }

        // ===================== KELOLA AKUN (KHUSUS SUPERADMIN) ===================== //

        // Memuat daftar permintaan akses yang masih pending, ditampilkan sebagai card
        // di halaman Kelola Akun + badge notifikasi di sidebar
        function loadPendingRequests() {
            google.script.run.withSuccessHandler(function (res) {
                const card = document.getElementById('pendingRequestsCard');
                const tbody = document.getElementById('pendingRequestsTable');
                const badge = document.getElementById('pendingBadge');

                if (!res || !res.success || res.requests.length === 0) {
                    if (card) card.style.display = 'none';
                    if (badge) badge.style.display = 'none';
                    return;
                }

                if (card) card.style.display = 'block';
                if (badge) {
                    badge.innerText = res.requests.length;
                    badge.style.display = '';
                }

                tbody.innerHTML = res.requests.map((r, idx) => `
          <tr>
            <td><span class="badge badge-solid-gray px-2 py-2">${idx + 1}</span></td>
            <td><span class="agent-name-style">${escapeHtml(r.username)}</span></td>
            <td><span class="unit-name-style">${escapeHtml(r.nama) || '-'}</span></td>
            <td class="text-center">
              <button class="btn-download-chart me-1" style="background:#DCFCE7; border-color:#86EFAC; color:#10B981;" onclick="approveAccessRequest('${escapeJsAttr(r.username)}')">
                <i class="fa-solid fa-check me-1"></i>Approve
              </button>
              <button class="btn-download-chart" style="background:#FEE2E2; border-color:#FCA5A5; color:#A30030;" onclick="rejectAccessRequest('${escapeJsAttr(r.username)}')">
                <i class="fa-solid fa-xmark me-1"></i>Tolak
              </button>
            </td>
          </tr>
        `).join('');
            }).getPendingRequests(currentUsername);
        }

        function approveAccessRequest(username) {
            if (!confirm('Setujui permintaan akses dari "' + username + '"?')) return;
            google.script.run.withSuccessHandler(function (res) {
                if (res && res.success) {
                    loadPendingRequests();
                    loadUserManagementTable();
                } else {
                    alert((res && res.error) ? res.error : 'Gagal menyetujui permintaan.');
                }
            }).withFailureHandler(function (err) {
                alert('Terjadi kesalahan sistem, coba lagi.');
                console.error(err);
            }).approveUser(currentUsername, username);
        }

        // Menyetujui SEMUA permintaan akses yang masih pending sekaligus, dalam satu klik
        function approveAllAccessRequests() {
            if (!confirm('Setujui SEMUA permintaan akses yang menunggu? Tindakan ini tidak bisa dibatalkan.')) return;
            google.script.run.withSuccessHandler(function (res) {
                if (res && res.success) {
                    loadPendingRequests();
                    loadUserManagementTable();
                } else {
                    alert((res && res.error) ? res.error : 'Gagal menyetujui semua permintaan.');
                }
            }).withFailureHandler(function (err) {
                alert('Terjadi kesalahan sistem, coba lagi.');
                console.error(err);
            }).approveAllPendingUsers(currentUsername);
        }

        function rejectAccessRequest(username) {
            if (!confirm('Tolak permintaan akses dari "' + username + '"? Permintaan akan dihapus.')) return;
            google.script.run.withSuccessHandler(function (res) {
                if (res && res.success) {
                    loadPendingRequests();
                } else {
                    alert((res && res.error) ? res.error : 'Gagal menolak permintaan.');
                }
            }).withFailureHandler(function (err) {
                alert('Terjadi kesalahan sistem, coba lagi.');
                console.error(err);
            }).rejectUser(currentUsername, username);
        }

        // Menampilkan/menyembunyikan password di tabel Kelola Akun saat ikon mata diklik
        function toggleUserPasswordVisibility(btn) {
            const span = btn.previousElementSibling;
            const icon = btn.querySelector('i');
            const isMasked = span.innerText.includes('\u2022') || span.innerText.includes('â€¢') || span.innerText.includes('•');
            if (isMasked) {
                span.innerText = span.getAttribute('data-pass');
                icon.classList.remove('fa-eye');
                icon.classList.add('fa-eye-slash');
            } else {
                span.innerText = '\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022';
                icon.classList.remove('fa-eye-slash');
                icon.classList.add('fa-eye');
            }
        }

        // Helper Toast Notifikasi Admin
        function showAdminToast(msg, type = 'success') {
            let toast = document.getElementById('adminToastNotification');
            if (!toast) {
                toast = document.createElement('div');
                toast.id = 'adminToastNotification';
                toast.className = 'admin-toast-notification';
                document.body.appendChild(toast);
            }
            const icon = type === 'success'
                ? '<i class="fa-solid fa-circle-check text-success"></i>'
                : '<i class="fa-solid fa-circle-exclamation text-warning"></i>';
            toast.innerHTML = `${icon} <span>${escapeHtml(msg)}</span>`;
            toast.classList.add('show');
            clearTimeout(window.adminToastTimeout);
            window.adminToastTimeout = setTimeout(() => {
                toast.classList.remove('show');
            }, 3200);
        }

        // Helper format waktu & tanggal log aktivitas
        function formatLogTimestamp(ts) {
            if (!ts) return '-';
            if (typeof ts === 'string' && ts.includes('/') && ts.includes('WIB')) return ts;
            const d = new Date(ts);
            if (isNaN(d.getTime())) return ts;
            const pad = n => String(n).padStart(2, '0');
            const dStr = `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()}`;
            const tStr = `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())} WIB`;
            return `${dStr}  \u2022  ${tStr}`;
        }

        // Penampung data log aktivitas untuk filtering cepat tanpa reload backend
        let allActivityLogs = [];
        let currentFilteredActivityLogs = [];

        // Memuat riwayat aktivitas (login, logout, buka halaman) untuk ditampilkan superadmin
        function loadActivityLogs() {
            const tbody = document.getElementById('activityLogTable');
            tbody.innerHTML = `<tr><td colspan="5" class="text-center py-4 text-muted"><i class="fa-solid fa-circle-notch fa-spin me-2 text-glow-red"></i>Memuat riwayat log aktivitas...</td></tr>`;

            const refreshBtn = document.getElementById('btnRefreshActivityLog');
            const iconRefresh = document.getElementById('iconRefreshLog');
            if (refreshBtn) refreshBtn.disabled = true;
            if (iconRefresh) iconRefresh.classList.add('fa-spin');

            google.script.run.withSuccessHandler(function (res) {
                if (refreshBtn) refreshBtn.disabled = false;
                if (iconRefresh) iconRefresh.classList.remove('fa-spin');

                if (!res || !res.success) {
                    allActivityLogs = [];
                    tbody.innerHTML = `<tr><td colspan="5" class="text-center py-4 text-muted">${escapeHtml((res && res.error) || 'Gagal memuat log aktivitas.')}</td></tr>`;
                    return;
                }
                allActivityLogs = (res.logs || []).filter(log => String(log.username || '').trim().toLowerCase() !== 'superadmin');
                filterActivityLogsTable();
            }).withFailureHandler(function (err) {
                if (refreshBtn) refreshBtn.disabled = false;
                if (iconRefresh) iconRefresh.classList.remove('fa-spin');
                tbody.innerHTML = `<tr><td colspan="5" class="text-center py-4 text-danger">Gagal menghubungi server untuk memuat log.</td></tr>`;
                console.error(err);
            }).getActivityLogs(currentUsername);
        }

        // Filter log aktivitas secara live (berdasarkan kata kunci & dropdown tipe aktivitas)
        function filterActivityLogsTable() {
            const searchEl = document.getElementById('searchActivityLog');
            const typeEl = document.getElementById('filterActivityTypeSelect');
            const term = searchEl ? searchEl.value.toLowerCase().trim() : '';
            const filterType = typeEl ? typeEl.value : 'all';

            const filtered = allActivityLogs.filter(log => {
                const u = String(log.username || '').toLowerCase();
                const n = String(log.nama || '').toLowerCase();
                const a = String(log.activity || '').toLowerCase();
                const t = String(log.timestamp || '').toLowerCase();
                const matchSearch = term === '' || u.includes(term) || n.includes(term) || a.includes(term) || t.includes(term);

                if (!matchSearch) return false;
                if (filterType === 'all') return true;
                if (filterType === 'login') return a === 'login';
                if (filterType === 'logout') return a === 'logout';
                if (filterType === 'page') return a.startsWith('membuka halaman');
                return true;
            });

            currentFilteredActivityLogs = filtered;
            renderActivityLogsRows(filtered);

            const countBadge = document.getElementById('activityLogCountBadge');
            if (countBadge) countBadge.innerText = `${filtered.length} Aktivitas`;
            const countText = document.getElementById('activityFilteredCountText');
            if (countText) countText.innerText = `Menampilkan ${filtered.length} dari ${allActivityLogs.length} entri`;
        }

        function renderActivityLogsRows(list) {
            const tbody = document.getElementById('activityLogTable');
            if (!tbody) return;
            if (list.length === 0) {
                tbody.innerHTML = `<tr><td colspan="5" class="text-center py-4 text-muted"><i class="fa-regular fa-folder-open me-2"></i>Tidak ada aktivitas yang sesuai filter.</td></tr>`;
                return;
            }

            tbody.innerHTML = list.map((log, idx) => {
                const act = String(log.activity || '').trim();
                const actLower = act.toLowerCase();
                let chipHtml = '';

                if (actLower === 'login') {
                    chipHtml = `<span class="badge-log-chip chip-login"><i class="fa-solid fa-arrow-right-to-bracket"></i> Login</span>`;
                } else if (actLower === 'logout') {
                    chipHtml = `<span class="badge-log-chip chip-logout"><i class="fa-solid fa-arrow-right-from-bracket"></i> Logout</span>`;
                } else if (actLower.startsWith('membuka halaman')) {
                    const pageTitle = act.replace(/^membuka halaman\s*/i, '');
                    chipHtml = `<span class="badge-log-chip chip-page"><i class="fa-regular fa-folder-open"></i> Buka ${escapeHtml(pageTitle)}</span>`;
                } else {
                    chipHtml = `<span class="badge-log-chip chip-other"><i class="fa-solid fa-circle-dot"></i> ${escapeHtml(act)}</span>`;
                }

                const roleBadge = log.role === 'superadmin'
                    ? `<span class="badge-role-superadmin"><i class="fa-solid fa-shield-halved"></i> Superadmin</span>`
                    : `<span class="badge-role-view"><i class="fa-regular fa-user"></i> View</span>`;

                return `
          <tr>
            <td class="text-center"><span class="badge badge-solid-gray px-2 py-1.5">${idx + 1}</span></td>
            <td>
              <div class="fw-bold text-navy">${escapeHtml(log.username)}</div>
              <div class="text-muted small" style="font-size:0.75rem;">${escapeHtml(log.nama) || '-'}</div>
            </td>
            <td>${roleBadge}</td>
            <td>${chipHtml}</td>
            <td><span class="timestamp-badge"><i class="fa-regular fa-clock text-muted"></i> ${formatLogTimestamp(log.timestamp)}</span></td>
          </tr>
        `;
            }).join('');
        }

        function downloadActivityLogsExcel() {
            const listToExport = (currentFilteredActivityLogs && currentFilteredActivityLogs.length > 0)
                ? currentFilteredActivityLogs
                : allActivityLogs;

            if (!listToExport || listToExport.length === 0) {
                alert('Tidak ada data log aktivitas untuk diunduh.');
                return;
            }

            ensureXLSXLibrary(function () {
                const headers = [
                    'No',
                    'Username',
                    'Nama Pengguna',
                    'Role',
                    'Aktivitas',
                    'Waktu & Tanggal'
                ];

                const rows = listToExport.map((log, idx) => [
                    idx + 1,
                    log.username || '',
                    log.nama || '',
                    (String(log.role || '').toLowerCase() === 'superadmin') ? 'Superadmin' : 'View',
                    log.activity || '',
                    log.timestamp || ''
                ]);

                const worksheet = XLSX.utils.aoa_to_sheet([headers, ...rows]);
                worksheet['!cols'] = [
                    { wch: 6 },
                    { wch: 18 },
                    { wch: 25 },
                    { wch: 16 },
                    { wch: 35 },
                    { wch: 26 }
                ];

                const workbook = XLSX.utils.book_new();
                XLSX.utils.book_append_sheet(workbook, worksheet, 'Log Aktivitas');

                const tz = new Date();
                const stamp = `${tz.getFullYear()}${String(tz.getMonth() + 1).padStart(2, '0')}${String(tz.getDate()).padStart(2, '0')}_${String(tz.getHours()).padStart(2, '0')}${String(tz.getMinutes()).padStart(2, '0')}`;
                XLSX.writeFile(workbook, `Log_Aktivitas_${stamp}.xlsx`);
            });
        }

        let allUsersManagementList = [];

        function loadUserManagementTable() {
            const tbody = document.getElementById('userManagementTable');
            tbody.innerHTML = `<tr><td colspan="6" class="text-center py-4 text-muted"><i class="fa-solid fa-circle-notch fa-spin me-2 text-glow-red"></i>Memuat data akun pengguna...</td></tr>`;

            google.script.run.withSuccessHandler(function (res) {
                if (!res || !res.success) {
                    allUsersManagementList = [];
                    tbody.innerHTML = `<tr><td colspan="6" class="text-center py-4 text-muted">${escapeHtml((res && res.error) || 'Gagal memuat data akun.')}</td></tr>`;
                    return;
                }
                allUsersManagementList = res.users || [];
                filterUserManagementTable();
            }).getAllUsers(currentUsername);
        }

        // Menyaring tabel Kelola Akun berdasarkan kata kunci & role
        function filterUserManagementTable() {
            const searchEl = document.getElementById('searchUserManagement');
            const roleFilterEl = document.getElementById('filterUserRoleSelect');
            const term = searchEl ? searchEl.value.toLowerCase().trim() : '';
            const roleFilter = roleFilterEl ? roleFilterEl.value : 'all';

            const filtered = allUsersManagementList.filter(u => {
                const uName = String(u.username || '').toLowerCase();
                const nama = String(u.nama || '').toLowerCase();
                const matchSearch = term === '' || uName.includes(term) || nama.includes(term);
                if (!matchSearch) return false;
                if (roleFilter === 'all') return true;
                if (roleFilter === 'superadmin') return u.role === 'superadmin';
                if (roleFilter === 'user') return u.role !== 'superadmin';
                return true;
            });

            renderUserManagementRows(filtered);

            const userBadge = document.getElementById('userCountBadge');
            if (userBadge) userBadge.innerText = `Total: ${allUsersManagementList.length} Pengguna`;
            const filteredText = document.getElementById('userFilteredCountText');
            if (filteredText) filteredText.innerText = `Menampilkan ${filtered.length} dari ${allUsersManagementList.length} pengguna`;
        }

        // Mengubah role akun secara cepat langsung dari baris tabel Daftar Akun
        function changeUserRoleInline(username, newRole, nama) {
            const userObj = allUsersManagementList.find(u => u.username === username);
            const currentRole = userObj ? userObj.role : 'user';

            if (currentRole === newRole) return;

            // Cegah mengubah superadmin terakhir
            if (currentRole === 'superadmin' && newRole !== 'superadmin') {
                const totalSuperadmin = allUsersManagementList.filter(u => u.role === 'superadmin').length;
                if (totalSuperadmin <= 1) {
                    alert('Tidak bisa mengubah role Superadmin terakhir yang tersisa.');
                    filterUserManagementTable();
                    return;
                }
            }

            const roleLabel = (newRole === 'superadmin') ? 'Superadmin' : 'View (User)';
            const msg = `Ubah role akun "${username}" menjadi "${roleLabel}"?`;

            if (!confirm(msg)) {
                filterUserManagementTable();
                return;
            }

            google.script.run.withSuccessHandler(function (res) {
                if (res && res.success) {
                    showAdminToast(`Role akun "${username}" berhasil diubah menjadi ${roleLabel}!`);
                    loadUserManagementTable();
                } else {
                    alert((res && res.error) || 'Gagal mengubah role pengguna.');
                    filterUserManagementTable();
                }
            }).withFailureHandler(function (err) {
                alert('Terjadi kesalahan sistem saat mengubah role.');
                console.error(err);
                filterUserManagementTable();
            }).updateUser(currentUsername, username, '', newRole, nama || '');
        }

        function renderUserManagementRows(list) {
            const tbody = document.getElementById('userManagementTable');
            if (!tbody) return;
            if (list.length === 0) {
                tbody.innerHTML = `<tr><td colspan="6" class="text-center py-4 text-muted"><i class="fa-regular fa-user me-2"></i>Tidak ada akun yang sesuai kriteria.</td></tr>`;
                return;
            }

            tbody.innerHTML = list.map((u, idx) => {
                const isSuperadmin = (u.role === 'superadmin');
                const roleSelectClass = isSuperadmin ? 'role-superadmin-select' : 'role-user-select';

                return `
          <tr>
            <td class="text-center"><span class="badge badge-solid-gray px-2 py-1.5">${idx + 1}</span></td>
            <td>
              <span class="agent-name-style">${escapeHtml(u.username)}</span>
            </td>
            <td>
              <span class="unit-name-style">${escapeHtml(u.nama) || '-'}</span>
            </td>
            <td>
              <span class="d-flex align-items-center gap-2">
                ${u.isHashed 
                  ? `<span class="badge bg-light text-success border px-2 py-1" title="Password di-hash dengan SHA-256 + Salt"><i class="fa-solid fa-shield-halved me-1"></i>Terenkripsi SHA-256</span>`
                  : `<span class="user-pass-mask" data-pass="${escapeHtml(u.password)}" style="font-family:monospace; letter-spacing:2px;">\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022</span>
                     <button type="button" class="toggle-password-btn" style="color:#9CA3AF; font-size:0.85rem;" onclick="toggleUserPasswordVisibility(this)" title="Lihat/sembunyikan password">
                       <i class="fa-solid fa-eye"></i>
                     </button>
                     <span class="badge bg-light text-warning border px-1.5 py-0.5" style="font-size:0.68rem;" title="Password masih plain text, akan terenkripsi otomatis saat user login">Legacy</span>`
                }
              </span>
            </td>
            <td>
              <div class="d-inline-flex align-items-center gap-2">
                <select class="form-select form-select-sm role-badge-select ${roleSelectClass}"
                        onchange="changeUserRoleInline('${escapeJsAttr(u.username)}', this.value, '${escapeJsAttr(u.nama)}')"
                        title="Klik untuk mengubah role akun">
                  <option value="user" ${!isSuperadmin ? 'selected' : ''}>View (User)</option>
                  <option value="superadmin" ${isSuperadmin ? 'selected' : ''}>Superadmin</option>
                </select>
              </div>
            </td>
            <td class="text-center">
              <button class="btn-download-chart me-1" onclick="openUserModal('edit', '${escapeJsAttr(u.username)}', '${escapeJsAttr(u.role)}', '${escapeJsAttr(u.nama)}')" title="Edit Akun">
                <i class="fa-solid fa-pen"></i>
              </button>
              <button class="btn-download-chart" style="background:#FEE2E2; border-color:#FCA5A5; color:#A30030;" onclick="deleteUserAccount('${escapeJsAttr(u.username)}')" title="Hapus Akun">
                <i class="fa-solid fa-trash"></i>
              </button>
            </td>
          </tr>
        `;
            }).join('');
        }

        function openUserModal(mode, username, role, nama) {
            userFormMode = mode;
            userFormEditingUsername = username || '';

            document.getElementById('userFormAlert').classList.add('d-none');
            document.getElementById('userFormUsername').value = username || '';
            document.getElementById('userFormUsername').disabled = (mode === 'edit');
            document.getElementById('userFormNama').value = nama || '';
            document.getElementById('userFormPassword').value = '';
            document.getElementById('userFormPasswordLabel').innerText =
                (mode === 'edit') ? 'Password Baru (kosongkan jika tidak diubah)' : 'Password';
            document.getElementById('userFormRole').value = role || 'user';
            document.getElementById('userFormModalTitle').innerHTML = (mode === 'edit')
                ? '<i class="fa-solid fa-user-pen me-2"></i>Edit Akun'
                : '<i class="fa-solid fa-user-plus me-2"></i>Tambah Akun';

            const saveBtn = document.getElementById('userFormSaveBtn');
            saveBtn.disabled = false;
            saveBtn.innerText = 'Simpan';

            userFormBootstrap.show();
        }

        function saveUserForm() {
            const uName = document.getElementById('userFormUsername').value.trim();
            const uNama = document.getElementById('userFormNama').value.trim();
            const uPass = document.getElementById('userFormPassword').value.trim();
            const uRole = document.getElementById('userFormRole').value;
            const alertBox = document.getElementById('userFormAlert');
            alertBox.classList.add('d-none');

            if (!uName) {
                alertBox.innerText = 'Username wajib diisi.';
                alertBox.classList.remove('d-none');
                return;
            }
            if (userFormMode === 'add' && !uPass) {
                alertBox.innerText = 'Password wajib diisi untuk akun baru.';
                alertBox.classList.remove('d-none');
                return;
            }

            const saveBtn = document.getElementById('userFormSaveBtn');
            saveBtn.disabled = true;
            saveBtn.innerText = 'Menyimpan...';

            const handleResult = function (res) {
                saveBtn.disabled = false;
                saveBtn.innerText = 'Simpan';
                if (res && res.success) {
                    userFormBootstrap.hide();
                    showAdminToast(userFormMode === 'add' ? 'Akun baru berhasil ditambahkan!' : 'Perubahan akun berhasil disimpan!');
                    loadUserManagementTable();
                } else {
                    alertBox.innerText = (res && res.error) ? res.error : 'Gagal menyimpan akun.';
                    alertBox.classList.remove('d-none');
                }
            };
            const handleFailure = function (err) {
                saveBtn.disabled = false;
                saveBtn.innerText = 'Simpan';
                alertBox.innerText = 'Terjadi kesalahan sistem, coba lagi.';
                alertBox.classList.remove('d-none');
                console.error(err);
            };

            if (userFormMode === 'add') {
                google.script.run.withSuccessHandler(handleResult).withFailureHandler(handleFailure)
                    .addUser(currentUsername, uName, uPass, uRole, uNama);
            } else {
                google.script.run.withSuccessHandler(handleResult).withFailureHandler(handleFailure)
                    .updateUser(currentUsername, userFormEditingUsername, uPass, uRole, uNama);
            }
        }

        function deleteUserAccount(username) {
            if (!confirm('Yakin ingin menghapus akun "' + username + '"? Tindakan ini tidak bisa dibatalkan.')) return;

            google.script.run.withSuccessHandler(function (res) {
                if (res && res.success) {
                    showAdminToast(`Akun "${username}" berhasil dihapus.`);
                    loadUserManagementTable();
                } else {
                    alert((res && res.error) ? res.error : 'Gagal menghapus akun.');
                }
            }).withFailureHandler(function (err) {
                alert('Terjadi kesalahan sistem, coba lagi.');
                console.error(err);
            }).deleteUser(currentUsername, username);
        }

        // State variabel Team Insights 2.0
        let currentBdRawTemuanList = [];

        // Scroll halus ke bagian User Guide (aman untuk Google Apps Script iframe)
        
        // Cetak atau simpan User Guide ke PDF dengan nama file & format cetak optimal
        
        // Cetak atau simpan Period Comparison ke PDF dengan format optimal
        function printPeriodComparison() {
            // Pastikan data perbandingan sudah terhitung; jika belum, hitung terlebih dahulu
            if (!cmpLastFilteredData && typeof filterCompareRange === 'function') {
                filterCompareRange();
            }

            const originalTitle = document.title;
            try {
                const blnA = document.getElementById('cmpBulanA') ? (document.getElementById('cmpBulanA').value || 'BulanA') : 'BulanA';
                const blnB = document.getElementById('cmpBulanB') ? (document.getElementById('cmpBulanB').value || 'BulanB') : 'BulanB';
                const tglA = document.getElementById('cmpTglAwal') ? (document.getElementById('cmpTglAwal').value || '1') : '1';
                const tglB = document.getElementById('cmpTglAkhir') ? (document.getElementById('cmpTglAkhir').value || '31') : '31';
                const prod = (currentDomain === 'fixed') ? 'Fixed' : 'Mobile';

                // Atur judul dokumen agar saat Save as PDF nama filenya langsung deskriptif & rapi
                document.title = `Period_Comparison_${prod}_${blnA}_vs_${blnB}_Tgl_${tglA}-${tglB}_MATA`;

                // Perbarui teks banner cetak jika elemennya ada
                const metaEl = document.getElementById('printCmpPeriodMeta');
                if (metaEl) {
                    metaEl.textContent = `${blnA} vs ${blnB} (Tgl ${tglA}-${tglB})`;
                }
                const domainTextEl = document.getElementById('printCmpDomainText');
                if (domainTextEl) {
                    domainTextEl.textContent = (currentDomain === 'fixed') ? 'Fixed Broadband' : 'Mobile Broadband';
                }

                // Tandai body dengan class printing-compare
                document.body.classList.add('printing-compare');
                showPage('compare');

                // Beri jeda 150ms agar browser merender seluruh elemen grafik & tabel secara optimal
                setTimeout(() => {
                    window.print();
                    // Kembalikan judul halaman dan hapus class pencetakan
                    setTimeout(() => {
                        document.title = originalTitle;
                        document.body.classList.remove('printing-compare');
                    }, 1500);
                }, 150);
            } catch (err) {
                console.warn('Fallback printPeriodComparison error:', err);
                window.print();
                document.title = originalTitle;
                document.body.classList.remove('printing-compare');
            }
        }

        function printUserGuide() {
            const originalTitle = document.title;
            try {
                // Atur judul dokumen agar nama file otomatis 'User_Guide_MATA_v2.0.pdf' saat Save as PDF
                document.title = "User_Guide_MATA_v2.0";
                
                // Pastikan halaman aktif adalah userguide
                showPage('userguide');
                
                // Beri jeda sejenak agar browser merender seluruh elemen sebelum dialog print terbuka
                setTimeout(() => {
                    window.print();
                    // Kembalikan judul halaman setelah dialog cetak ditutup
                    setTimeout(() => {
                        document.title = originalTitle;
                    }, 1500);
                }, 120);
            } catch (err) {
                console.warn('Fallback print error:', err);
                window.print();
                document.title = originalTitle;
            }
        }

