        // Auto-sinkronisasi Bulan B pada tabel tren harian saat filter Bulan dipilih
        function onBdBulanChange() {
            const bVal = document.getElementById('filBdBulan') ? document.getElementById('filBdBulan').value.trim() : '';
            if (bVal) {
                const selB = document.getElementById('bdTrendBulanB');
                const selA = document.getElementById('bdTrendBulanA');
                if (selB && [...selB.options].some(o => o.value === bVal)) {
                    selB.value = bVal;
                    // Pilihkan bulan sebelumnya untuk Bulan A
                    if (typeof bulanTerurutGlobal !== 'undefined' && Array.isArray(bulanTerurutGlobal)) {
                        const idx = bulanTerurutGlobal.indexOf(bVal);
                        if (idx > 0 && selA) {
                            selA.value = bulanTerurutGlobal[idx - 1];
                        }
                    }
                }
            }
        }

        function populateBreakdownFilterDropdowns() {
            if (!allRecords || allRecords.length === 0) return;

            // 1. SPV (Kolom I, index 8)
            const selSpv = document.getElementById('filBdSpv');
            if (selSpv) {
                const currentSpv = selSpv.value;
                selSpv.innerHTML = '<option value="">Semua SPV</option>';
                const listSpv = [...new Set(allRecords.map(r => r[8]).filter(x => x && String(x).trim() !== ""))].sort();
                listSpv.forEach(v => selSpv.options[selSpv.options.length] = new Option(v, v));
                if (listSpv.includes(currentSpv)) selSpv.value = currentSpv;
            }

            // 2. TL (Kolom H, index 7)
            populateBreakdownTlOptions();

            // 3. KIP (Kolom K, index 10)
            const selKip = document.getElementById('filBdKip');
            if (selKip) {
                const currentKip = selKip.value;
                selKip.innerHTML = '<option value="">Semua KIP</option>';
                const listKip = [...new Set(allRecords.map(r => r[10]).filter(x => x && String(x).trim() !== ""))].sort();
                listKip.forEach(v => selKip.options[selKip.options.length] = new Option(v, v));
                if (listKip.includes(currentKip)) selKip.value = currentKip;
            }

            // 4. Kategori Bad Tiket (Kolom L, index 11)
            const selKatL = document.getElementById('filBdKategoriL');
            if (selKatL) {
                const currentKat = selKatL.value;
                selKatL.innerHTML = '<option value="">Semua Kategori</option>';
                const listL = [...new Set(allRecords.map(row => row[11]).filter(x => x && String(x).trim() !== ""))].sort();
                listL.forEach(v => selKatL.options[selKatL.options.length] = new Option(v, v));
                if (listL.includes(currentKat)) selKatL.value = currentKat;
            }
        }

        function populateBreakdownTlOptions(selectedSpv) {
            const selTl = document.getElementById('filBdTl');
            if (!selTl) return;
            const currentTl = selTl.value;
            selTl.innerHTML = '<option value="">Semua TL</option>';

            let source = allRecords;
            const spvVal = selectedSpv !== undefined ? selectedSpv : (document.getElementById('filBdSpv') ? document.getElementById('filBdSpv').value.trim() : '');
            if (spvVal) {
                source = allRecords.filter(r => String(r[8]).trim() === spvVal);
            }
            const listTl = [...new Set(source.map(r => r[7]).filter(x => x && String(x).trim() !== ""))].sort();
            listTl.forEach(v => selTl.options[selTl.options.length] = new Option(v, v));
            if (listTl.includes(currentTl)) selTl.value = currentTl;
        }

