        function onBdTlChange() {
            // SPV sengaja dibiarkan independen (tidak otomatis terkunci) karena seorang TL
            // dapat mengalami perubahan/rotasi SPV antar waktu atau lintas unit.
            // Dengan tetap pada "Semua SPV", seluruh tiket TL akan tampil lengkap tanpa terpotong.
        }

        function getActiveBreakdownFilters() {
            const getVal = id => { const el = document.getElementById(id); return el ? el.value.trim() : ''; };
            return {
                fTgl: getVal('filBdTanggal'),
                fBln: getVal('filBdBulan'),
                fThn: getVal('filBdTahun'),
                fUnit: getVal('filBdUnit'),
                fSourceBy: getVal('filBdSourceBy'),
                fSpv: getVal('filBdSpv'),
                fTl: getVal('filBdTl'),
                fKatL: getVal('filBdKategoriL'),
                fKip: getVal('filBdKip'),
                fStatusSgh: getVal('filBdStatusSanggahan') || 'net',
                fAgentSearch: getVal('filBdAgentSearch').toLowerCase()
            };
        }

        function filterBreakdownAgent() {
            const filters = getActiveBreakdownFilters();
            let maxDay = 31;
            if (filters.fTgl !== "") {
                const parsed = parseInt(filters.fTgl, 10);
                if (!isNaN(parsed) && parsed >= 1 && parsed <= 31) maxDay = parsed;
            }

            let filtered = allRecords.filter(row => {
                let agentName = row[6] != null ? String(row[6]).trim() : '';
                // Hanya proses baris dengan Nama Agent yang valid (bukan baris kosong/blank di spreadsheet)
                if (!agentName || agentName === '-' || agentName.toLowerCase() === 'undefined') return false;

                let rDate = parseInt(row[0], 10);
                let matchTgl = filters.fTgl === "" || (!isNaN(rDate) && rDate >= 1 && rDate <= maxDay);
                let matchBln = filters.fBln === "" || String(row[1]).trim() === filters.fBln;
                let matchThn = filters.fThn === "" || String(row[2]).trim() === filters.fThn;
                let matchUnit = filters.fUnit === "" || String(row[9]).trim() === filters.fUnit;
                let matchKatL = filters.fKatL === "" || String(row[11]).trim().toUpperCase() === filters.fKatL.trim().toUpperCase();
                let matchSourceBy = filters.fSourceBy === "" || String(row[15]).trim() === filters.fSourceBy;
                let matchSpv = filters.fSpv === "" || String(row[8]).trim() === filters.fSpv;
                let matchTl = filters.fTl === "" || String(row[7]).trim() === filters.fTl;
                let matchKip = filters.fKip === "" || String(row[10]).trim() === filters.fKip;
                let matchAgent = filters.fAgentSearch === "" || agentName.toLowerCase().includes(filters.fAgentSearch);
                if (filters.fStatusSgh === 'net' && isSanggahanDiterima(row)) return false;
                if (filters.fStatusSgh === 'only_sanggahan' && !isSanggahanDiterima(row)) return false;
                return matchTgl && matchBln && matchThn && matchUnit && matchKatL && matchSourceBy && matchSpv && matchTl && matchKip && matchAgent;
            });

            currentBreakdownFiltered = filtered;

            renderBreakdownExecutiveSummary(filtered, filters);
            renderBreakdownTopBottom(filtered);
            renderBreakdownTemuanMatrix(filtered);
            renderBreakdownTable(filtered);
        }

        // 1. EXECUTIVE SUMMARY & REKOMENDASI TINDAKAN (DILENGKAPI TOP 3 KETIDAKSESUAIAN)
        function renderBreakdownExecutiveSummary(filtered, filters) {
            const totalBad = filtered.length;

            // Roster Populasi: seluruh agent unik terdaftar dalam lingkup SPV, TL, Unit, Tahun aktif
            let rosterSource = allRecords.filter(r => {
                let mUnit = filters.fUnit === "" || String(r[9]).trim() === filters.fUnit;
                let mThn = filters.fThn === "" || String(r[2]).trim() === filters.fThn;
                let mSpv = filters.fSpv === "" || String(r[8]).trim() === filters.fSpv;
                let mTl = filters.fTl === "" || String(r[7]).trim() === filters.fTl;
                return mUnit && mThn && mSpv && mTl;
            });

            const rosterSet = new Set(rosterSource.map(r => String(r[6]).trim()).filter(Boolean));
            const totalPopulasi = rosterSet.size;

            // Agent yang memiliki temuan bad tiket di filter saat ini
            const badAgentMap = {};
            const kipFreq = {};
            const katFreq = {};

            filtered.forEach(r => {
                const ag = String(r[6] || '').trim();
                const kp = String(r[10] || '').trim();
                const kt = String(r[11] || '').trim();
                if (ag) badAgentMap[ag] = (badAgentMap[ag] || 0) + 1;
                if (kp) kipFreq[kp] = (kipFreq[kp] || 0) + 1;
                if (kt) katFreq[kt] = (katFreq[kt] || 0) + 1;
            });

            const countKenaBad = Object.keys(badAgentMap).length;
            const countZeroBad = Math.max(0, totalPopulasi - countKenaBad);
            const pctZeroBad = totalPopulasi > 0 ? ((countZeroBad / totalPopulasi) * 100).toFixed(1) : 0;
            const pctKenaBad = totalPopulasi > 0 ? ((countKenaBad / totalPopulasi) * 100).toFixed(1) : 0;

            // Top KIP & Top Kategori
            const sortedKip = Object.entries(kipFreq).sort((a, b) => b[1] - a[1]);
            const topKip = sortedKip.length > 0 ? sortedKip[0] : null;

            const sortedKat = Object.entries(katFreq).sort((a, b) => b[1] - a[1]);
            const top3Kat = sortedKat.slice(0, 3); // TOP 3 Ketidaksesuaian Bad Tiket

            // Top Agent terburuk
            const sortedBadAgents = Object.entries(badAgentMap).sort((a, b) => b[1] - a[1]);
            const topAgent = sortedBadAgents.length > 0 ? sortedBadAgents[0] : null;

            // Update KPI Cards DOM
            const elTotalBad = document.getElementById('bdKpiTotalBad');
            if (elTotalBad) elTotalBad.innerText = totalBad;

            // Hitung status sanggahan pada lingkup filter aktif
            let scopeAll = 0, scopeSgh = 0, scopeNet = 0;
            let maxDay = 31;
            if (filters.fTgl !== "") {
                const parsed = parseInt(filters.fTgl, 10);
                if (!isNaN(parsed) && parsed >= 1 && parsed <= 31) maxDay = parsed;
            }

            allRecords.forEach(r => {
                let agName = r[6] != null ? String(r[6]).trim() : '';
                if (!agName || agName === '-' || agName.toLowerCase() === 'undefined') return;
                let rDate = parseInt(r[0], 10);
                let matchTgl = filters.fTgl === "" || (!isNaN(rDate) && rDate >= 1 && rDate <= maxDay);
                let matchBln = filters.fBln === "" || String(r[1]).trim() === filters.fBln;
                let matchThn = filters.fThn === "" || String(r[2]).trim() === filters.fThn;
                let matchUnit = filters.fUnit === "" || String(r[9]).trim() === filters.fUnit;
                let matchKatL = filters.fKatL === "" || String(r[11] || '').trim().toUpperCase() === filters.fKatL.trim().toUpperCase();
                let matchSourceBy = filters.fSourceBy === "" || String(r[15]).trim() === filters.fSourceBy;
                let matchSpv = filters.fSpv === "" || String(r[8]).trim() === filters.fSpv;
                let matchTl = filters.fTl === "" || String(r[7]).trim() === filters.fTl;
                let matchKip = filters.fKip === "" || String(r[10]).trim() === filters.fKip;
                let matchAg = filters.fAgentSearch === "" || agName.toLowerCase().includes(filters.fAgentSearch);
                if (matchTgl && matchBln && matchThn && matchUnit && matchKatL && matchSourceBy && matchSpv && matchTl && matchKip && matchAg) {
                    scopeAll++;
                    if (isSanggahanDiterima(r)) scopeSgh++;
                    else scopeNet++;
                }
            });

            const pillsBd = document.getElementById('bdKpiSanggahanPills');
            if (pillsBd) {
                pillsBd.innerHTML = `
                    <span class="badge" style="background:#F1F5F9; color:#475569; font-weight:600; padding:3px 6px; font-size:0.65rem;" title="Total Tiket Sebelum Sanggahan">
                        All: <strong>${scopeAll}</strong>
                    </span>
                    <span class="badge" style="background:rgba(217,119,6,0.12); color:#B45309; font-weight:600; padding:3px 6px; font-size:0.65rem;" title="Sanggahan Diterima (Pengurang Kolom O)">
                        <i class="fa-solid fa-gavel me-1"></i>Sgh: <strong>-${scopeSgh}</strong>
                    </span>
                    <span class="badge" style="background:rgba(16,185,129,0.12); color:#047857; font-weight:600; padding:3px 6px; font-size:0.65rem;" title="Bad Tiket Bersih Setelah Sanggahan Diterima">
                        <i class="fa-solid fa-check-double me-1"></i>Net: <strong>${scopeNet}</strong>
                    </span>
                `;
            }

            const elKenaBad = document.getElementById('bdKpiAgentKenaBad');
            if (elKenaBad) elKenaBad.innerHTML = `${countKenaBad} <span style="font-size:0.78rem; font-weight:700; color:#D97706;">(${pctKenaBad}%)</span>`;

            const elZeroBad = document.getElementById('bdKpiAgentZeroBad');
            if (elZeroBad) elZeroBad.innerHTML = `${countZeroBad} <span style="font-size:0.78rem; font-weight:700; color:#059669;">(${pctZeroBad}% Zero)</span>`;

            const elTopKip = document.getElementById('bdKpiTopKip');
            if (elTopKip) {
                if (topKip) {
                    elTopKip.innerHTML = `${escapeHtml(topKip[0])} <span class="badge bg-purple-subtle text-purple ms-1" style="font-size:0.7rem; vertical-align:middle;">${topKip[1]}x</span>`;
                    elTopKip.title = topKip[0];
                } else {
                    elTopKip.innerText = '-';
                    elTopKip.title = '';
                }
            }

            // Scope Badge
            const elScopeBadge = document.getElementById('bdScopeBadge');
            if (elScopeBadge) {
                let scopeParts = [];
                if (filters.fSpv) scopeParts.push('SPV: ' + filters.fSpv);
                if (filters.fTl) scopeParts.push('TL: ' + filters.fTl);
                if (filters.fUnit) scopeParts.push('Unit: ' + filters.fUnit);
                if (filters.fBln) scopeParts.push('Bulan: ' + filters.fBln);
                if (filters.fTgl) scopeParts.push('Tgl: 1-' + filters.fTgl);

                elScopeBadge.innerHTML = scopeParts.length > 0
                    ? '<i class="fa-solid fa-filter me-1"></i> Lingkup: ' + escapeHtml(scopeParts.join(' • '))
                    : '<i class="fa-solid fa-users me-1"></i> Lingkup: Seluruh Tim (Semua SPV &amp; TL)';
            }

            // Actionable Narrative Box dengan TOP 3 Ketidaksesuaian Bad Tiket
            const elNarrative = document.getElementById('bdExecutiveNarrative');
            if (elNarrative) {
                if (totalBad === 0) {
                    elNarrative.innerHTML = `
                        <div class="d-flex align-items-center gap-2 text-success fw-bold mb-1">
                            <i class="fa-solid fa-circle-check fa-lg"></i>
                            <span>Performa Sempurna (Zero Defect)!</span>
                        </div>
                        <p class="mb-0 text-muted">Tidak ada temuan bad tiket pada parameter filter yang dipilih. Seluruh tim beroperasi dengan akurasi 100%.</p>
                    `;
                } else {
                    const timName = filters.fTl ? ('TL ' + filters.fTl) : (filters.fSpv ? ('SPV ' + filters.fSpv) : 'Operasional');
                    const topKipText = topKip ? `<strong>${escapeHtml(topKip[0])}</strong> (${topKip[1]} temuan)` : '-';
                    const topAgentText = topAgent ? `<strong>${escapeHtml(topAgent[0])}</strong> (${topAgent[1]} tiket)` : '-';

                    // HTML TOP 3 Ketidaksesuaian Card Grid
                    const colors = ['#E11D48', '#D97706', '#2563EB'];
                    const bgColors = ['rgba(225,29,72,0.1)', 'rgba(217,119,6,0.1)', 'rgba(37,99,235,0.1)'];
                    const rankMedals = ['🥇', '🥈', '🥉'];

                    let top3Html = top3Kat.map(([katName, vol], idx) => {
                        const pct = totalBad > 0 ? ((vol / totalBad) * 100).toFixed(1) : 0;
                        return `
                            <div class="col-md-4 col-12">
                                <div class="p-2.5 rounded-3 border h-100 shadow-sm top3-card-item" style="background:#FFFFFF;">
                                    <div class="d-flex align-items-center justify-content-between mb-1">
                                        <span class="fw-bold" style="font-size:0.8rem; color:${colors[idx]};">
                                            ${rankMedals[idx]} Top #${idx + 1}
                                        </span>
                                        <span class="badge fw-bold" style="background:${bgColors[idx]}; color:${colors[idx]}; font-size:0.75rem;">
                                            ${vol} Tiket (${pct}%)
                                        </span>
                                    </div>
                                    <div class="fw-bold text-truncate text-navy" style="font-size:0.82rem;" title="${escapeHtml(katName)}">
                                        ${escapeHtml(katName)}
                                    </div>
                                    <div class="progress mt-2" style="height: 5px; background:rgba(0,0,0,0.06); border-radius:10px;">
                                        <div class="progress-bar" style="width: ${pct}%; background: ${colors[idx]}; border-radius:10px;"></div>
                                    </div>
                                </div>
                            </div>
                        `;
                    }).join('');

                    elNarrative.innerHTML = `
                        <!-- TOP 3 Ketidaksesuaian Bad Tiket -->
                        <div class="p-3 rounded-3 mb-3 top3-ketidaksesuaian-box" style="background: rgba(255, 241, 242, 0.7); border: 1px solid rgba(225, 29, 72, 0.22);">
                            <div class="d-flex align-items-center justify-content-between mb-2 flex-wrap gap-2">
                                <strong class="text-navy d-flex align-items-center gap-2" style="font-size: 0.88rem;">
                                    <i class="fa-solid fa-triangle-exclamation text-danger"></i>
                                    TOP 3 Ketidaksesuaian Bad Tiket (Volume Terbanyak &amp; Persentase):
                                </strong>
                                <span class="badge bg-white text-danger border border-danger-subtle px-2 py-1" style="font-size:0.72rem; font-weight:700;">
                                    Total: ${totalBad} Bad Tiket
                                </span>
                            </div>
                            <div class="row g-2">
                                ${top3Html || '<div class="col-12 text-muted small">Tidak ada data kategori</div>'}
                            </div>
                        </div>

                        <!-- Diagnosa & Prioritas Tindakan -->
                        <div class="mb-2" style="font-size:0.84rem;">
                            <strong class="text-navy"><i class="fa-solid fa-chart-simple text-danger me-1"></i>Diagnosa Masalah Tim ${escapeHtml(timName)}:</strong>
                            Ditemukan <strong>${totalBad} bad tiket</strong> dari <strong>${countKenaBad} agent</strong> (${pctKenaBad}% tim terdampak).
                            Titik kerentanan utama berada pada KIP ${topKipText}.
                        </div>
                        <div class="p-2.5 rounded-2" style="background:rgba(255,255,255,0.85); border:1px dashed rgba(163,0,48,0.25);">
                            <strong class="text-danger" style="font-size:0.84rem;"><i class="fa-solid fa-list-check me-1"></i>Prioritas Take Action SPV / TL:</strong>
                            <ol class="mb-0 ps-3 mt-1" style="line-height:1.6; font-size:0.82rem;">
                                <li><strong>Briefing SOP KIP:</strong> Refresh pemahaman SOP untuk KIP ${topKipText} kepada seluruh anggota tim.</li>
                                <li><strong>Coaching Prioritas:</strong> Lakukan coaching 1-on-1 intensif kepada agent dengan temuan tertinggi (${topAgentText}) guna menelusuri kendala teknis.</li>
                            </ol>
                        </div>
                    `;
                }
            }
        }

        // 2. TOP 10 HIGHEST & TOP 10 LOWEST BAD TIKET (RESPONSIF FILTER DATA BREAKDOWN)
        function renderBreakdownTopBottom(data) {
            let agentMap = {};
            data.forEach(row => {
                let agent = row[6];
                let unit = row[9];
                let tl = row[7];
                let spv = row[8];
                let kip = row[10];
                if (!agent) return;
                if (!agentMap[agent]) {
                    agentMap[agent] = { unit: unit, tl: tl, spv: spv, total: 0, kips: {} };
                }
                agentMap[agent].total++;
                if (kip) agentMap[agent].kips[kip] = (agentMap[agent].kips[kip] || 0) + 1;
            });

            let entries = Object.entries(agentMap);
            let highest = [...entries].sort((a, b) => b[1].total - a[1].total).slice(0, 10);
            let lowest = [...entries].sort((a, b) => a[1].total - b[1].total).slice(0, 10);

            const getRankBadge = (rank) => {
                if (rank === 1) return '<span class="badge-rank rank-gold" title="Peringkat 1"><i class="fa-solid fa-crown me-1" style="font-size:0.6rem;"></i>1</span>';
                if (rank === 2) return '<span class="badge-rank rank-silver" title="Peringkat 2">2</span>';
                if (rank === 3) return '<span class="badge-rank rank-bronze" title="Peringkat 3">3</span>';
                return '<span class="badge-rank rank-normal">' + rank + '</span>';
            };

            const buildRows = (list, isHighest) => {
                if (list.length === 0) {
                    return '<tr><td colspan="7" class="text-center py-4 text-muted"><i class="fa-solid fa-inbox fa-lg mb-2 d-block" style="color:#CBD5E1;"></i>Tidak ada data untuk filter yang dipilih</td></tr>';
                }
                return list.map(([agentName, info], idx) => {
                    const sortedKips = Object.entries(info.kips).sort((a, b) => b[1] - a[1]);
                    const topKipBadge = sortedKips.length > 0
                        ? `<span class="badge bg-danger-subtle text-danger border text-truncate" style="max-width:140px; font-size:0.7rem;" title="${escapeHtml(sortedKips[0][0])}">${escapeHtml(sortedKips[0][0])} (${sortedKips[0][1]}x)</span>`
                        : '-';
                    const statusBadge = isHighest
                        ? '<span class="badge bg-danger-subtle text-danger fw-bold px-2 py-1" style="font-size:0.7rem;">Perlu Evaluasi</span>'
                        : '<span class="badge bg-success-subtle text-success fw-bold px-2 py-1" style="font-size:0.7rem;">Akurasi Terbaik</span>';

                    return `
                        <tr>
                            <td class="text-center">${getRankBadge(idx + 1)}</td>
                            <td>
                                <div class="d-flex align-items-center gap-2">
                                    <span class="avatar-initials" style="width:26px; height:26px; font-size:0.7rem;">${getInitials(agentName)}</span>
                                    <span class="agent-name-style text-truncate" style="max-width:140px;" title="${escapeHtml(agentName)}">${escapeHtml(agentName)}</span>
                                </div>
                            </td>
                            <td><span class="unit-name-style">${escapeHtml(info.unit || '-')}</span></td>
                            <td><span class="unit-name-style">${escapeHtml(info.tl || '-')}</span></td>
                            <td><span class="unit-name-style">${escapeHtml(info.spv || '-')}</span></td>
                            <td>${isHighest ? topKipBadge : statusBadge}</td>
                            <td class="text-end">
                                <span class="badge ${isHighest ? 'bg-danger-subtle text-danger' : 'bg-success-subtle text-success'} fw-bold px-2.5 py-1" style="font-size:0.82rem; border-radius:8px;">
                                    ${info.total}
                                </span>
                            </td>
                        </tr>
                    `;
                }).join('');
            };

            const elHigh = document.getElementById('breakdownTopHighestTable');
            const elLow = document.getElementById('breakdownTopLowestTable');
            if (elHigh) elHigh.innerHTML = buildRows(highest, true);
            if (elLow) elLow.innerHTML = buildRows(lowest, false);
        }

        // 3. PEMETAAN TEMUAN KIP & DETAIL BAD TIKET
        function renderBreakdownTemuanMatrix(filtered) {
            currentBdRawTemuanList = filtered;

            const badgeCount = document.getElementById('bdTemuanCountBadge');
            if (badgeCount) badgeCount.innerText = filtered.length + ' Temuan';

            // Top 5 KIP Bermasalah
            const kipFreq = {};
            const katFreq = {};

            filtered.forEach(r => {
                const kp = String(r[10] || '').trim();
                const kt = String(r[11] || '').trim();
                if (kp) kipFreq[kp] = (kipFreq[kp] || 0) + 1;
                if (kt) katFreq[kt] = (katFreq[kt] || 0) + 1;
            });

            const sortedKip = Object.entries(kipFreq).sort((a, b) => b[1] - a[1]).slice(0, 5);
            const totalBad = filtered.length;
            const containerKip = document.getElementById('bdTopKipBars');
            if (containerKip) {
                if (sortedKip.length === 0) {
                    containerKip.innerHTML = '<span class="text-muted small">Tidak ada temuan KIP</span>';
                } else {
                    containerKip.innerHTML = sortedKip.map(([kipName, cnt]) => {
                        const pct = totalBad > 0 ? Math.round((cnt / totalBad) * 100) : 0;
                        return `
                            <div>
                                <div class="d-flex justify-content-between align-items-center mb-1" style="font-size:0.75rem;">
                                    <span class="text-navy fw-semibold text-truncate" style="max-width:280px;" title="${escapeHtml(kipName)}">${escapeHtml(kipName)}</span>
                                    <span class="fw-bold text-danger">${cnt} tiket (${pct}%)</span>
                                </div>
                                <div class="progress" style="height:6px; background:#FEE2E2; border-radius:6px;">
                                    <div class="progress-bar" style="width:${pct}%; background:#A30030; border-radius:6px;"></div>
                                </div>
                            </div>
                        `;
                    }).join('');
                }
            }

            // Sebaran Kategori Chips
            const containerKat = document.getElementById('bdCategoryChips');
            if (containerKat) {
                const sortedKat = Object.entries(katFreq).sort((a, b) => b[1] - a[1]);
                if (sortedKat.length === 0) {
                    containerKat.innerHTML = '<span class="text-muted small">Tidak ada temuan kategori</span>';
                } else {
                    containerKat.innerHTML = sortedKat.map(([katName, cnt]) => {
                        return `
                            <span class="badge bg-light text-navy border px-2.5 py-1.5" style="font-size:0.72rem; border-radius:8px;">
                                <i class="fa-solid fa-tag text-danger me-1"></i>${escapeHtml(katName)}: <strong>${cnt}</strong>
                            </span>
                        `;
                    }).join('');
                }
            }

            renderBreakdownTemuanTable();
        }

        function renderBreakdownTemuanTable() {
            const tbody = document.getElementById('bdTemuanTable');
            const thead = document.getElementById('bdTemuanTableThead');
            if (!tbody) return;

            const searchInput = document.getElementById('searchTemuanMatrixInput');
            const searchVal = searchInput ? searchInput.value.toLowerCase().trim() : '';

            let list = currentBdRawTemuanList || [];
            if (searchVal) {
                list = list.filter(r => {
                    const rowText = [r[3], r[4], r[6], r[7], r[8], r[10], r[11], r[12], r[13], r[15]].join(' ').toLowerCase();
                    return rowText.includes(searchVal);
                });
            }

            // Agregasi temuan identik untuk data mode pola temuan
            const grouped = {};
            list.forEach(r => {
                const key = [r[6], r[7], r[8], r[10], r[11], r[12], r[13], r[15]].join('|||');
                if (!grouped[key]) {
                    grouped[key] = {
                        agent: r[6] || '-',
                        tl: r[7] || '-',
                        spv: r[8] || '-',
                        kip: r[10] || '-',
                        kat: r[11] || '-',
                        detil: r[12] || '-',
                        notes: maskNotesKolomN(r[13]) || '-',
                        source: r[15] || '-',
                        count: 0
                    };
                }
                grouped[key].count++;
            });

            const aggregatedRows = Object.values(grouped).sort((a, b) => b.count - a.count);
            const totalPhysicalTickets = list.length;
            const totalPatterns = aggregatedRows.length;

            // Perbarui counter tombol toggle view mode
            const btnTiketCount = document.getElementById('btnModeTiketCount');
            const btnPolaCount = document.getElementById('btnModePolaCount');
            if (btnTiketCount) btnTiketCount.innerText = totalPhysicalTickets;
            if (btnPolaCount) btnPolaCount.innerText = totalPatterns;

            const summaryTextEl = document.getElementById('bdTemuanTableSummaryText');
            const badgeCount = document.getElementById('bdTemuanCountBadge');
            const hintTextEl = document.getElementById('bdTemuanTableHintText');

            if (bdTemuanViewMode === 'pertiket') {
                // ================= MODE 1: PER LEMBAR TIKET (DEFAULT, 1 BARIS = 1 TIKET FISIK) =================
                if (thead) {
                    thead.innerHTML = `
                        <tr>
                            <th width="3%" class="text-center">No</th>
                            <th width="9%">Tanggal Input (D)</th>
                            <th width="11%">No Tiket (E)</th>
                            <th width="13%">Nama Agent (G)</th>
                            <th width="10%">TL (H)</th>
                            <th width="10%">SPV (I)</th>
                            <th width="12%">KIP (K)</th>
                            <th width="9%">Kategori (L)</th>
                            <th width="13%">Detil Bad Tiket (M)</th>
                            <th width="14%">Notes Solver (N)</th>
                            <th width="6%">Source (P)</th>
                        </tr>
                    `;
                }

                if (badgeCount) {
                    badgeCount.innerHTML = `<i class="fa-solid fa-ticket me-1"></i>${totalPhysicalTickets} Lembar Tiket`;
                }
                if (summaryTextEl) {
                    summaryTextEl.innerHTML = `Menampilkan <strong>${totalPhysicalTickets} lembar tiket fisik</strong> (1 baris = 1 tiket, sinkron dengan KPI Total Bad Tiket)`;
                }
                if (hintTextEl) {
                    hintTextEl.innerHTML = `<i class="fa-solid fa-circle-check me-1 text-success"></i>Mode: <strong>Per Lembar Tiket</strong> (Setiap baris mewakili 1 lembar tiket fisik lengkap dengan No Tiket).`;
                }

                if (list.length === 0) {
                    tbody.innerHTML = '<tr><td colspan="11" class="text-center py-4 text-muted"><i class="fa-solid fa-inbox fa-lg mb-2 d-block" style="color:#CBD5E1;"></i>Tidak ada data temuan tiket</td></tr>';
                    return;
                }

                tbody.innerHTML = list.map((r, idx) => {
                    const tglInput = r[3] || '-';
                    const noTiket = r[4] || '-';
                    const agent = r[6] || '-';
                    const tl = r[7] || '-';
                    const spv = r[8] || '-';
                    const kip = r[10] || '-';
                    const kat = r[11] || '-';
                    const detil = r[12] || '-';
                    const notes = maskNotesKolomN(r[13]) || '-';
                    const source = r[15] || '-';

                    return `
                        <tr>
                            <td class="text-center text-muted fw-semibold">${idx + 1}</td>
                            <td><span class="small text-secondary font-monospace" style="font-size:0.75rem;">${escapeHtml(tglInput)}</span></td>
                            <td>
                                <span class="badge bg-light text-navy border fw-bold font-monospace" style="font-size:0.75rem; letter-spacing:0.5px;">
                                    <i class="fa-solid fa-hashtag text-danger me-1"></i>${escapeHtml(noTiket)}
                                </span>
                            </td>
                            <td><strong class="text-navy">${escapeHtml(agent)}</strong></td>
                            <td><span class="unit-name-style">${escapeHtml(tl)}</span></td>
                            <td><span class="unit-name-style">${escapeHtml(spv)}</span></td>
                            <td><span class="badge bg-light text-navy border" style="font-size:0.72rem;">${escapeHtml(kip)}</span></td>
                            <td><span class="badge bg-danger-subtle text-danger" style="font-size:0.72rem;">${escapeHtml(kat)}</span></td>
                            <td><span class="text-truncate d-inline-block" style="max-width:200px;" title="${escapeHtml(detil)}">${escapeHtml(detil)}</span></td>
                            <td><span class="text-truncate d-inline-block text-muted" style="max-width:180px;" title="${escapeHtml(notes)}">${escapeHtml(notes)}</span></td>
                            <td><span class="badge bg-secondary-subtle text-secondary" style="font-size:0.7rem;">${escapeHtml(source)}</span></td>
                        </tr>
                    `;
                }).join('');

            } else {
                // ================= MODE 2: RINGKAS POLA TEMUAN (AGREGASI TEMUAN IDENTIK) =================
                if (thead) {
                    thead.innerHTML = `
                        <tr>
                            <th width="4%" class="text-center">No</th>
                            <th>Nama Agent (G)</th>
                            <th>TL (H)</th>
                            <th>SPV (I)</th>
                            <th>KIP (K)</th>
                            <th>Kategori (L)</th>
                            <th>Detil Bad Tiket (M)</th>
                            <th>Notes Solver (N)</th>
                            <th>Source (P)</th>
                            <th width="8%" class="text-end">Jumlah</th>
                        </tr>
                    `;
                }

                if (badgeCount) {
                    if (totalPatterns < totalPhysicalTickets) {
                        badgeCount.innerHTML = `<i class="fa-solid fa-layer-group me-1"></i>${totalPatterns} Pola Temuan <span class="badge bg-danger-subtle text-danger ms-1 fw-bold">(${totalPhysicalTickets} Tiket)</span>`;
                    } else {
                        badgeCount.innerHTML = `<i class="fa-solid fa-table me-1"></i>${totalPhysicalTickets} Temuan`;
                    }
                }
                if (summaryTextEl) {
                    summaryTextEl.innerHTML = `Total: <strong>${totalPatterns} pola temuan unik</strong> (${totalPhysicalTickets} lembar tiket fisik)`;
                }
                if (hintTextEl) {
                    hintTextEl.innerHTML = `<i class="fa-solid fa-circle-info me-1 text-primary"></i>Mode: <strong>Ringkas Pola Temuan</strong> (Temuan identik dikelompokkan, jumlah lembar tiket tertera pada kolom Jumlah).`;
                }

                if (aggregatedRows.length === 0) {
                    tbody.innerHTML = '<tr><td colspan="10" class="text-center py-4 text-muted"><i class="fa-solid fa-inbox fa-lg mb-2 d-block" style="color:#CBD5E1;"></i>Tidak ada data temuan</td></tr>';
                    return;
                }

                tbody.innerHTML = aggregatedRows.map((r, idx) => `
                    <tr>
                        <td class="text-center text-muted fw-semibold">${idx + 1}</td>
                        <td><strong class="text-navy">${escapeHtml(r.agent)}</strong></td>
                        <td><span class="unit-name-style">${escapeHtml(r.tl)}</span></td>
                        <td><span class="unit-name-style">${escapeHtml(r.spv)}</span></td>
                        <td><span class="badge bg-light text-navy border" style="font-size:0.72rem;">${escapeHtml(r.kip)}</span></td>
                        <td><span class="badge bg-danger-subtle text-danger" style="font-size:0.72rem;">${escapeHtml(r.kat)}</span></td>
                        <td><span class="text-truncate d-inline-block" style="max-width:200px;" title="${escapeHtml(r.detil)}">${escapeHtml(r.detil)}</span></td>
                        <td><span class="text-truncate d-inline-block text-muted" style="max-width:180px;" title="${escapeHtml(r.notes)}">${escapeHtml(r.notes)}</span></td>
                        <td><span class="badge bg-secondary-subtle text-secondary" style="font-size:0.7rem;">${escapeHtml(r.source)}</span></td>
                        <td class="text-end"><span class="badge bg-danger text-white rounded-pill px-2.5" title="${r.count} lembar tiket">${r.count}</span></td>
                    </tr>
                `).join('');
            }
        }


                
        // ===================== UTILITY FUNCTIONS (INITIALS & SPARKLINE) =====================
        function getInitials(name) {
            if (!name) return 'AG';
            const clean = String(name).trim().replace(/[^a-zA-Z0-9\s]/g, '');
            const parts = clean.split(/\s+/).filter(Boolean);
            if (parts.length === 0) return 'AG';
            if (parts.length === 1) return parts[0].substring(0, 2).toUpperCase();
            return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
        }

        // Membuat sparkline SVG modern dengan gradient fill & highlighted endpoint dot
        function buildSparklineSVG(values) {
            const w = 126, h = 34, pad = 4;
            if (!values || values.length === 0) {
                return `<span class="text-muted small" style="font-size:0.75rem;">-</span>`;
            }
            if (values.length === 1) {
                return `<span class="badge bg-light text-dark border px-2 py-1" style="font-size:0.72rem;">${values[0]} tkt</span>`;
            }

            const max = Math.max(...values, 1);
            const min = Math.min(...values);
            const stepX = (w - pad * 2) / (values.length - 1);

            const coords = values.map((v, i) => {
                const x = pad + i * stepX;
                const y = h - pad - (v / max) * (h - pad * 2);
                return { x: Number(x.toFixed(1)), y: Number(y.toFixed(1)), val: v };
            });

            const polyPoints = coords.map(c => `${c.x},${c.y}`).join(' ');
            const first = values[0], last = values[values.length - 1];

            // Tren: last > first = bad ticket bertambah (buruk/merah); last < first = berkurang (baik/hijau)
            let strokeColor = '#64748B';
            let fillColor = 'rgba(100, 116, 139, 0.12)';
            if (last > first) {
                strokeColor = '#E11D48';
                fillColor = 'rgba(225, 29, 72, 0.14)';
            } else if (last < first) {
                strokeColor = '#059669';
                fillColor = 'rgba(5, 150, 105, 0.14)';
            }

            const lastCoord = coords[coords.length - 1];
            const areaPoints = `${coords[0].x},${h - pad} ${polyPoints} ${lastCoord.x},${h - pad}`;

            return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" style="display:inline-block; vertical-align:middle; overflow:visible;">
        <title>Tren Harian: Awal ${first} -> Akhir ${last} (Min: ${min}, Max: ${max})</title>
        <polygon points="${areaPoints}" fill="${fillColor}" />
        <polyline points="${polyPoints}" fill="none" stroke="${strokeColor}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
        <circle cx="${lastCoord.x}" cy="${lastCoord.y}" r="3" fill="${strokeColor}" stroke="#FFFFFF" stroke-width="1.5" />
      </svg>`;
        }

        // Mengisi dropdown "Bandingkan Bulan" (Bulan A vs Bulan B) pada tabel Breakdown Agent
        

        function populateBreakdownTrendMonths() {
            const selA = document.getElementById('bdTrendBulanA');
            const selB = document.getElementById('bdTrendBulanB');
            if (!selA || !selB) return;
            selA.innerHTML = "";
            selB.innerHTML = "";
            bulanTerurutGlobal.forEach((val) => {
                if (val && val.toString().trim() !== "") {
                    selA.options[selA.options.length] = new Option(val, val);
                    selB.options[selB.options.length] = new Option(val, val);
                }
            });
            if (selA.options.length > 0) selA.selectedIndex = 0;
            if (selB.options.length > 1) selB.selectedIndex = 1;
            else if (selB.options.length > 0) selB.selectedIndex = 0;
        }

