        // Helper mengecek apakah tiket berstatus "SANGGAHAN DITERIMA" pada Kolom O (Final Status / row[14])
        function isSanggahanDiterima(row) {
            if (!row || row.length <= 14 || row[14] === undefined || row[14] === null) return false;
            const st = String(row[14]).trim().toUpperCase();
            return st === 'SANGGAHAN DITERIMA' || st.includes('SANGGAHAN DITERIMA') || st === 'SANGGAHAN DISETUJUI';
        }

