        // Menampilkan loading persentase (sama seperti tombol Cari lainnya) sebelum menghitung perbandingan
        function handleCariCompareRange() {
            const loader = document.getElementById('loader');
            loader.style.display = 'flex';
            runFakeLoader(function () {
                loader.style.display = 'none';
                filterCompareRange();
            });
        }

        function filterCompareRange() {
            const tglAwal = parseInt(document.getElementById('cmpTglAwal').value, 10);
            const tglAkhir = parseInt(document.getElementById('cmpTglAkhir').value, 10);
            const bulanA = document.getElementById('cmpBulanA').value.trim();
            const bulanB = document.getElementById('cmpBulanB').value.trim();
            const fUnit = document.getElementById('cmpUnit').value.trim();
            const fKatL = document.getElementById('cmpKategoriL').value.trim();
            const fSourceBy = document.getElementById('cmpSourceBy').value.trim();
            const selStatusSgh = document.getElementById('cmpStatusSanggahan');
            const fStatusSgh = selStatusSgh ? selStatusSgh.value : 'net';

            // Kalau tanggal awal > akhir, tukar otomatis supaya tetap valid
            const dayStart = Math.min(tglAwal, tglAkhir);
            const dayEnd = Math.max(tglAwal, tglAkhir);

            if (!bulanA || !bulanB) {
                alert('Pilih Bulan A dan Bulan B terlebih dahulu.');
                return;
            }

            // Bangun daftar tanggal dalam rentang yang dipilih (mis. 1..12)
            let dateRange = [];
            for (let d = dayStart; d <= dayEnd; d++) dateRange.push(String(d));

            let countsAAll = {}, countsBAll = {};
            let countsASanggahan = {}, countsBSanggahan = {};
            let countsANet = {}, countsBNet = {};
            dateRange.forEach(d => {
                countsAAll[d] = 0; countsBAll[d] = 0;
                countsASanggahan[d] = 0; countsBSanggahan[d] = 0;
                countsANet[d] = 0; countsBNet[d] = 0;
            });

            allRecords.forEach(row => {
                let rowTgl = String(row[0]).trim();
                let rowBln = String(row[1]).trim();
                let rowUnit = String(row[9]).trim();
                let rowL = String(row[11]).trim();
                let rowSourceBy = String(row[15]).trim();

                if (dateRange.indexOf(rowTgl) === -1) return;
                if (fUnit !== "" && rowUnit !== fUnit) return;
                if (fKatL !== "" && rowL !== fKatL) return;
                if (fSourceBy !== "" && rowSourceBy !== fSourceBy) return;

                const isSgh = isSanggahanDiterima(row);

                if (rowBln === bulanA) {
                    countsAAll[rowTgl]++;
                    if (isSgh) countsASanggahan[rowTgl]++;
                    else countsANet[rowTgl]++;
                }
                if (rowBln === bulanB) {
                    countsBAll[rowTgl]++;
                    if (isSgh) countsBSanggahan[rowTgl]++;
                    else countsBNet[rowTgl]++;
                }
            });

            const totalA_All = dateRange.reduce((sum, d) => sum + countsAAll[d], 0);
            const totalA_Sanggahan = dateRange.reduce((sum, d) => sum + countsASanggahan[d], 0);
            const totalA_Net = dateRange.reduce((sum, d) => sum + countsANet[d], 0);

            const totalB_All = dateRange.reduce((sum, d) => sum + countsBAll[d], 0);
            const totalB_Sanggahan = dateRange.reduce((sum, d) => sum + countsBSanggahan[d], 0);
            const totalB_Net = dateRange.reduce((sum, d) => sum + countsBNet[d], 0);

            // Tentukan angka primer kartu sesuai pilihan dropdown Status Sanggahan
            let totalA = totalA_Net;
            let totalB = totalB_Net;
            let subLabelCard = 'Total bad tiket bersih (setelah sanggahan diterima)';

            if (fStatusSgh === 'all') {
                totalA = totalA_All;
                totalB = totalB_All;
                subLabelCard = 'Total akumulasi awal sebelum sanggahan (All Tiket)';
            } else if (fStatusSgh === 'only_sanggahan') {
                totalA = totalA_Sanggahan;
                totalB = totalB_Sanggahan;
                subLabelCard = 'Total tiket dengan sanggahan diterima (Kolom O)';
            }

            const netTickets = totalB - totalA;

            // Growth: Naik = tiket bertambah = buruk (merah), Turun = berkurang = baik (hijau)
            let growthPct = 0;
            let statusKey = 'stabil';
            if (totalA !== totalB) {
                if (totalB > totalA) {
                    statusKey = 'naik';
                    growthPct = totalA === 0 ? 100 : Math.round(((totalB - totalA) / totalA) * 100);
                } else {
                    statusKey = 'turun';
                    growthPct = totalA === 0 ? -100 : Math.round(((totalB - totalA) / totalA) * 100);
                }
            }

            const rangeLabel = `Tgl ${dayStart} - ${dayEnd}`;
            document.getElementById('cmpLabelA').innerText = `${rangeLabel} ${bulanA}`;
            document.getElementById('cmpLabelB').innerText = `${rangeLabel} ${bulanB}`;
            document.getElementById('cmpTotalA').innerText = totalA;
            document.getElementById('cmpTotalB').innerText = totalB;

            const subTotalAEl = document.getElementById('cmpSubTotalA');
            if (subTotalAEl) subTotalAEl.innerHTML = `<i class="fa-solid fa-circle-info me-1"></i>${subLabelCard}`;
            const subTotalBEl = document.getElementById('cmpSubTotalB');
            if (subTotalBEl) subTotalBEl.innerHTML = `<i class="fa-solid fa-circle-info me-1"></i>${subLabelCard}`;

            // Render sub-pills pada Card A & Card B agar selalu transparan All vs Sanggahan vs Net
            const pillsAEl = document.getElementById('cmpPillsA');
            if (pillsAEl) {
                pillsAEl.innerHTML = `
                    <span class="badge" style="background:#F1F5F9; color:#475569; font-weight:600; padding:4px 8px;" title="Total Tiket Sebelum Sanggahan">
                        All: <strong>${totalA_All}</strong>
                    </span>
                    <span class="badge" style="background:rgba(217,119,6,0.12); color:#B45309; font-weight:600; padding:4px 8px;" title="Sanggahan Diterima (Pengurang)">
                        <i class="fa-solid fa-gavel me-1"></i>Sgh: <strong>-${totalA_Sanggahan}</strong>
                    </span>
                    <span class="badge" style="background:rgba(16,185,129,0.12); color:#047857; font-weight:600; padding:4px 8px;" title="Bad Tiket Bersih Setelah Sanggahan Diterima">
                        <i class="fa-solid fa-check-double me-1"></i>Net: <strong>${totalA_Net}</strong>
                    </span>
                `;
            }

            const pillsBEl = document.getElementById('cmpPillsB');
            if (pillsBEl) {
                pillsBEl.innerHTML = `
                    <span class="badge" style="background:#F1F5F9; color:#475569; font-weight:600; padding:4px 8px;" title="Total Tiket Sebelum Sanggahan">
                        All: <strong>${totalB_All}</strong>
                    </span>
                    <span class="badge" style="background:rgba(217,119,6,0.12); color:#B45309; font-weight:600; padding:4px 8px;" title="Sanggahan Diterima (Pengurang)">
                        <i class="fa-solid fa-gavel me-1"></i>Sgh: <strong>-${totalB_Sanggahan}</strong>
                    </span>
                    <span class="badge" style="background:rgba(16,185,129,0.12); color:#047857; font-weight:600; padding:4px 8px;" title="Bad Tiket Bersih Setelah Sanggahan Diterima">
                        <i class="fa-solid fa-check-double me-1"></i>Net: <strong>${totalB_Net}</strong>
                    </span>
                `;
            }

            // Delta pertumbuhan All vs Net
            const deltaAll = totalB_All - totalA_All;
            const pctAll = totalA_All === 0 ? (deltaAll > 0 ? 100 : 0) : Math.round((deltaAll / totalA_All) * 100);
            const deltaNet = totalB_Net - totalA_Net;
            const pctNet = totalA_Net === 0 ? (deltaNet > 0 ? 100 : 0) : Math.round((deltaNet / totalA_Net) * 100);

            const pillsGrowthEl = document.getElementById('cmpPillsGrowth');
            if (pillsGrowthEl) {
                pillsGrowthEl.innerHTML = `
                    <span class="badge" style="background:#F1F5F9; color:#475569; font-weight:600; padding:4px 8px;" title="Delta Sebelum Sanggahan (All)">
                        All: <strong>${deltaAll >= 0 ? '+' + deltaAll : deltaAll} (${pctAll >= 0 ? '+' : ''}${pctAll}%)</strong>
                    </span>
                    <span class="badge" style="background:rgba(16,185,129,0.12); color:#047857; font-weight:600; padding:4px 8px;" title="Delta Setelah Sanggahan (Net)">
                        Net: <strong>${deltaNet >= 0 ? '+' + deltaNet : deltaNet} (${pctNet >= 0 ? '+' : ''}${pctNet}%)</strong>
                    </span>
                `;
            }

            const growthEl = document.getElementById('cmpGrowthValue');
            const growthSubEl = document.getElementById('cmpGrowthSubText');
            const cardGrowth = document.getElementById('cmpGrowthCardBox');
            const iconGrowth = document.getElementById('cmpGrowthIconBox');

            if (statusKey === 'naik') {
                growthEl.innerHTML = `<span style="color:#A30030;"><i class="fa-solid fa-arrow-trend-up me-1"></i>Naik ${growthPct}%</span>`;
                if (growthSubEl) growthSubEl.innerHTML = `<span class="text-danger fw-semibold"><i class="fa-solid fa-circle-exclamation me-1"></i>+${netTickets} tiket bertambah vs ${escapeHtml(bulanA)}</span>`;
                if (cardGrowth) cardGrowth.style.borderLeft = '4px solid #A30030';
                if (iconGrowth) {
                    iconGrowth.style.background = '#FFF1F2';
                    iconGrowth.style.color = '#A30030';
                    iconGrowth.innerHTML = '<i class="fa-solid fa-arrow-trend-up"></i>';
                }
            } else if (statusKey === 'turun') {
                growthEl.innerHTML = `<span style="color:#10B981;"><i class="fa-solid fa-arrow-trend-down me-1"></i>Turun ${Math.abs(growthPct)}%</span>`;
                if (growthSubEl) growthSubEl.innerHTML = `<span class="text-success fw-semibold"><i class="fa-solid fa-circle-check me-1"></i>${Math.abs(netTickets)} tiket berkurang vs ${escapeHtml(bulanA)}</span>`;
                if (cardGrowth) cardGrowth.style.borderLeft = '4px solid #10B981';
                if (iconGrowth) {
                    iconGrowth.style.background = '#ECFDF5';
                    iconGrowth.style.color = '#10B981';
                    iconGrowth.innerHTML = '<i class="fa-solid fa-arrow-trend-down"></i>';
                }
            } else {
                growthEl.innerHTML = `<span style="color:#6B7280;"><i class="fa-solid fa-minus me-1"></i>Stabil</span>`;
                if (growthSubEl) growthSubEl.innerHTML = `<span class="text-muted"><i class="fa-solid fa-minus me-1"></i>Volume tiket persis sama</span>`;
                if (cardGrowth) cardGrowth.style.borderLeft = '4px solid #64748B';
                if (iconGrowth) {
                    iconGrowth.style.background = '#F1F5F9';
                    iconGrowth.style.color = '#64748B';
                    iconGrowth.innerHTML = '<i class="fa-solid fa-minus"></i>';
                }
            }

            // ===== POPULATE TABEL KOMPARASI SEBELUM VS SETELAH SANGGAHAN DITERIMA =====
            const sghBoxEl = document.getElementById('compareSanggahanBoxRow');
            if (sghBoxEl) sghBoxEl.style.display = 'block';

            const thAEl = document.getElementById('thSanggahanA');
            const thBEl = document.getElementById('thSanggahanB');
            if (thAEl) thAEl.innerText = `${rangeLabel} ${bulanA}`;
            if (thBEl) thBEl.innerText = `${rangeLabel} ${bulanB}`;

            const deltaSgh = totalB_Sanggahan - totalA_Sanggahan;
            const tbodySgh = document.getElementById('compareSanggahanTableBody');
            if (tbodySgh) {
                const badgeAll = deltaAll > 0 
                    ? `<span class="badge rounded-pill fw-bold" style="background:rgba(163,0,48,0.1); color:#A30030; padding:6px 12px;"><i class="fa-solid fa-arrow-trend-up me-1"></i>+${deltaAll} tiket (+${pctAll}%)</span>`
                    : (deltaAll < 0 
                        ? `<span class="badge rounded-pill fw-bold" style="background:rgba(16,185,129,0.12); color:#10B981; padding:6px 12px;"><i class="fa-solid fa-arrow-trend-down me-1"></i>${deltaAll} tiket (${pctAll}%)</span>`
                        : `<span class="badge rounded-pill fw-bold" style="background:rgba(107,114,128,0.1); color:#64748B; padding:6px 12px;"><i class="fa-solid fa-minus me-1"></i>0 (Stabil)</span>`);

                const badgeSgh = deltaSgh > 0
                    ? `<span class="badge rounded-pill fw-bold" style="background:rgba(217,119,6,0.12); color:#B45309; padding:6px 12px;"><i class="fa-solid fa-arrow-trend-up me-1"></i>+${deltaSgh} sanggahan disetujui</span>`
                    : (deltaSgh < 0
                        ? `<span class="badge rounded-pill fw-bold" style="background:rgba(107,114,128,0.1); color:#64748B; padding:6px 12px;"><i class="fa-solid fa-arrow-trend-down me-1"></i>${deltaSgh} tiket</span>`
                        : `<span class="badge rounded-pill fw-bold" style="background:rgba(107,114,128,0.1); color:#64748B; padding:6px 12px;"><i class="fa-solid fa-minus me-1"></i>Sama (${totalA_Sanggahan} tiket)</span>`);

                const badgeNet = deltaNet > 0
                    ? `<span class="badge rounded-pill fw-bold" style="background:rgba(163,0,48,0.1); color:#A30030; padding:6px 12px;"><i class="fa-solid fa-arrow-trend-up me-1"></i>+${deltaNet} tiket (+${pctNet}%)</span>`
                    : (deltaNet < 0
                        ? `<span class="badge rounded-pill fw-bold" style="background:rgba(16,185,129,0.12); color:#10B981; padding:6px 12px;"><i class="fa-solid fa-arrow-trend-down me-1"></i>${deltaNet} tiket (${pctNet}%)</span>`
                        : `<span class="badge rounded-pill fw-bold" style="background:rgba(107,114,128,0.1); color:#64748B; padding:6px 12px;"><i class="fa-solid fa-minus me-1"></i>0 (Stabil)</span>`);

                tbodySgh.innerHTML = `
                    <tr>
                        <td style="padding:12px 16px;">
                            <div class="d-flex align-items-center gap-2">
                                <span style="width:10px; height:10px; border-radius:50%; background:#64748B; display:inline-block;"></span>
                                <div>
                                    <div class="fw-bold text-navy" style="font-size:0.9rem;">1. Sebelum Sanggahan Diterima (All Tiket)</div>
                                    <small class="text-muted">Total akumulasi temuan tiket awal sebelum evaluasi sanggahan</small>
                                </div>
                            </div>
                        </td>
                        <td class="text-center fw-bold text-navy" style="padding:12px 16px; font-size:1rem; font-variant-numeric:tabular-nums;">${totalA_All}</td>
                        <td class="text-center fw-bold text-navy" style="padding:12px 16px; font-size:1rem; font-variant-numeric:tabular-nums;">${totalB_All}</td>
                        <td class="text-center" style="padding:12px 16px;">${badgeAll}</td>
                    </tr>
                    <tr style="background:rgba(217,119,6,0.03);">
                        <td style="padding:12px 16px;">
                            <div class="d-flex align-items-center gap-2">
                                <span style="width:10px; height:10px; border-radius:50%; background:#D97706; display:inline-block;"></span>
                                <div>
                                    <div class="fw-bold text-warning-emphasis" style="font-size:0.9rem; color:#B45309;"><i class="fa-solid fa-gavel me-1"></i>2. Sanggahan Diterima (Kolom O)</div>
                                    <small class="text-muted">Tiket yang disetujui sanggahannya dan menjadi faktor pengurang bad tiket</small>
                                </div>
                            </div>
                        </td>
                        <td class="text-center fw-bold" style="padding:12px 16px; font-size:1rem; color:#B45309; font-variant-numeric:tabular-nums;">-${totalA_Sanggahan}</td>
                        <td class="text-center fw-bold" style="padding:12px 16px; font-size:1rem; color:#B45309; font-variant-numeric:tabular-nums;">-${totalB_Sanggahan}</td>
                        <td class="text-center" style="padding:12px 16px;">${badgeSgh}</td>
                    </tr>
                    <tr style="background:rgba(16,185,129,0.04); border-top:2px solid rgba(16,185,129,0.2);">
                        <td style="padding:12px 16px;">
                            <div class="d-flex align-items-center gap-2">
                                <span style="width:10px; height:10px; border-radius:50%; background:#10B981; display:inline-block;"></span>
                                <div>
                                    <div class="fw-bold text-success" style="font-size:0.95rem;"><i class="fa-solid fa-check-circle me-1"></i>3. Setelah Sanggahan Diterima (Net Bad Tiket)</div>
                                    <small class="text-muted">Total bad tiket final setelah dikurangi sanggahan diterima (All - Sanggahan Diterima)</small>
                                </div>
                            </div>
                        </td>
                        <td class="text-center fw-bold text-success" style="padding:12px 16px; font-size:1.15rem; font-variant-numeric:tabular-nums;">${totalA_Net}</td>
                        <td class="text-center fw-bold text-success" style="padding:12px 16px; font-size:1.15rem; font-variant-numeric:tabular-nums;">${totalB_Net}</td>
                        <td class="text-center" style="padding:12px 16px;">${badgeNet}</td>
                    </tr>
                `;
            }

            const sghInsightEl = document.getElementById('compareSanggahanInsightText');
            if (sghInsightEl) {
                if (totalA_Sanggahan > 0 || totalB_Sanggahan > 0) {
                    sghInsightEl.innerHTML = `
                        <i class="fa-solid fa-circle-info text-primary fs-6"></i>
                        <div>
                            Sanggahan diterima mereduksi <strong>${totalA_Sanggahan} tiket</strong> pada <strong>${escapeHtml(bulanA)}</strong> (dari ${totalA_All} menjadi <strong>${totalA_Net} bad tiket</strong>), dan <strong>${totalB_Sanggahan} tiket</strong> pada <strong>${escapeHtml(bulanB)}</strong> (dari ${totalB_All} menjadi <strong>${totalB_Net} bad tiket</strong>). Delta pertumbuhan setelah sanggahan diterima adalah <strong>${deltaNet >= 0 ? '+' + deltaNet : deltaNet} tiket (${pctNet >= 0 ? '+' : ''}${pctNet}%)</strong>.
                        </div>
                    `;
                } else {
                    sghInsightEl.innerHTML = `
                        <i class="fa-solid fa-circle-info text-muted fs-6"></i>
                        <div>
                            Belum ada tiket berstatus "SANGGAHAN DITERIMA" (Kolom O) pada rentang tanggal dan kriteria filter yang dipilih. Angka Sebelum Sanggahan (All) dan Setelah Sanggahan (Net) bernilai sama.
                        </div>
                    `;
                }
            }

            // Simpan cache data komparasi
            cmpLastFilteredData = {
                dateRange,
                bulanA,
                bulanB,
                countsAAll,
                countsBAll,
                countsASanggahan,
                countsBSanggahan,
                countsANet,
                countsBNet,
                totalA_All,
                totalB_All,
                totalA_Sanggahan,
                totalB_Sanggahan,
                totalA_Net,
                totalB_Net
            };

            // Sinkronisasi status metric chart dengan filter sanggahan
            if (fStatusSgh === 'all') cmpCurrentChartMetric = 'all';
            else if (fStatusSgh === 'only_sanggahan') cmpCurrentChartMetric = 'sanggahan';
            else cmpCurrentChartMetric = 'net';

            ['Net', 'All', 'Sanggahan'].forEach(m => {
                const btn = document.getElementById('btnCmpChart' + m);
                if (btn) {
                    const isActive = m.toLowerCase() === cmpCurrentChartMetric.toLowerCase();
                    btn.classList.toggle('active', isActive);
                    btn.className = isActive ? 'btn btn-primary active' : 'btn btn-outline-primary';
                }
            });

            renderCompareRangeChart();

            // ===== ANALISA PER KATEGORI KETIDAKSESUAIAN (Mandatory Ticket, KIP Tidak Sesuai, dst) =====
            let catDefs = [];
            if (currentDomain === 'fixed') {
                catDefs = [
                    { label: 'Mandatory Ticket', keys: ['MANDATORY TICKET'] },
                    { label: 'KIP Tidak Sesuai', keys: ['KIP TIDAK SESUAI'] },
                    { label: 'Case Tidak Perlu Dieskalasi', keys: ['CASE TIDAK PERLU DIESKALASI'] },
                    { label: 'Penggunaan Nomer Dummy', keys: ['PENGGUNAAN NOMER DUMMY', 'NOMER DUMMY'] },
                    { label: 'Double Ticket', keys: ['DOUBLE TICKET'] },
                    { label: 'Salah Tujuan', keys: ['SALAH TUJUAN'] }
                ];
            } else {
                // Mobile: Ambil seluruh kategori unik dari sheet Data2 (Kolom L)
                const mobCats = [...new Set(allRecords.map(r => r[11]).filter(x => x && String(x).trim() !== ""))].sort();
                catDefs = mobCats.map(c => ({
                    label: c,
                    keys: [c.toUpperCase()]
                }));
            }

            let catResults = catDefs.map(def => {
                let a_all = 0, b_all = 0;
                let a_sgh = 0, b_sgh = 0;
                allRecords.forEach(row => {
                    let rowTgl = String(row[0]).trim();
                    let rowBln = String(row[1]).trim();
                    let rowUnit = String(row[9]).trim();
                    let rowL = String(row[11]).trim().toUpperCase();
                    let rowSourceBy = String(row[15]).trim();

                    if (dateRange.indexOf(rowTgl) === -1) return;
                    if (fUnit !== "" && rowUnit !== fUnit) return;
                    if (fKatL !== "" && String(row[11]).trim() !== fKatL) return;
                    if (fSourceBy !== "" && rowSourceBy !== fSourceBy) return;
                    if (!def.keys.some(k => rowL.includes(k))) return;

                    const isSgh = isSanggahanDiterima(row);
                    if (rowBln === bulanA) {
                        a_all++;
                        if (isSgh) a_sgh++;
                    }
                    if (rowBln === bulanB) {
                        b_all++;
                        if (isSgh) b_sgh++;
                    }
                });

                const a_net = a_all - a_sgh;
                const b_net = b_all - b_sgh;

                let a = a_net, b = b_net;
                if (fStatusSgh === 'all') { a = a_all; b = b_all; }
                else if (fStatusSgh === 'only_sanggahan') { a = a_sgh; b = b_sgh; }

                let pct = 0;
                let catStatus = 'stabil';
                if (a !== b) {
                    if (b > a) { catStatus = 'naik'; pct = a === 0 ? 100 : Math.round(((b - a) / a) * 100); }
                    else { catStatus = 'turun'; pct = a === 0 ? -100 : Math.round(((b - a) / a) * 100); }
                }
                return { label: def.label, a, b, a_all, b_all, a_sgh, b_sgh, a_net, b_net, status: catStatus, pct };
            });

            document.getElementById('cmpCatThA').innerText = `${rangeLabel} ${bulanA}`;
            document.getElementById('cmpCatThB').innerText = `${rangeLabel} ${bulanB}`;

            document.getElementById('compareCategoryTable').innerHTML = catResults.map(c => {
                let badge;
                if (c.status === 'naik') {
                    badge = `<span class="badge px-3 py-2 rounded-pill fw-bold" style="background:rgba(163,0,48,0.1); color:#A30030; border:1px solid rgba(163,0,48,0.2);"><i class="fa-solid fa-arrow-trend-up me-1"></i>Naik ${c.pct}%</span>`;
                } else if (c.status === 'turun') {
                    badge = `<span class="badge px-3 py-2 rounded-pill fw-bold" style="background:rgba(16,185,129,0.12); color:#10B981; border:1px solid rgba(16,185,129,0.25);"><i class="fa-solid fa-arrow-trend-down me-1"></i>Turun ${Math.abs(c.pct)}%</span>`;
                } else {
                    badge = `<span class="badge px-3 py-2 rounded-pill fw-bold" style="background:rgba(107,114,128,0.1); color:#64748B; border:1px solid rgba(107,114,128,0.2);"><i class="fa-solid fa-minus me-1"></i>Stabil</span>`;
                }

                // Subtitle komparasi All vs Sanggahan di bawah angka
                let subA = '', subB = '';
                if (fStatusSgh === 'net') {
                    subA = `<div class="text-muted" style="font-size:0.72rem; font-weight:normal;">All: ${c.a_all}${c.a_sgh > 0 ? ` • <span style="color:#B45309; font-weight:600;">Sgh: -${c.a_sgh}</span>` : ''}</div>`;
                    subB = `<div class="text-muted" style="font-size:0.72rem; font-weight:normal;">All: ${c.b_all}${c.b_sgh > 0 ? ` • <span style="color:#B45309; font-weight:600;">Sgh: -${c.b_sgh}</span>` : ''}</div>`;
                } else if (fStatusSgh === 'all') {
                    subA = `<div class="text-muted" style="font-size:0.72rem; font-weight:normal;">Net: ${c.a_net} • Sgh: -${c.a_sgh}</div>`;
                    subB = `<div class="text-muted" style="font-size:0.72rem; font-weight:normal;">Net: ${c.b_net} • Sgh: -${c.b_sgh}</div>`;
                }

                return `
          <tr>
            <td style="padding:12px 16px;">
              <div class="d-flex align-items-center gap-2">
                <span style="width:8px; height:8px; border-radius:50%; background:${c.status === 'naik' ? '#A30030' : c.status === 'turun' ? '#10B981' : '#94A3B8'}; display:inline-block;"></span>
                <span class="fw-bold text-navy" style="font-size:0.88rem;">${escapeHtml(c.label)}</span>
              </div>
            </td>
            <td class="text-center fw-bold text-navy" style="padding:12px 16px; font-variant-numeric:tabular-nums; font-size:0.95rem;">
              ${c.a}
              ${subA}
            </td>
            <td class="text-center fw-bold text-navy" style="padding:12px 16px; font-variant-numeric:tabular-nums; font-size:0.95rem;">
              ${c.b}
              ${subB}
            </td>
            <td class="text-center" style="padding:12px 16px;">${badge}</td>
          </tr>
        `;
            }).join('');

            // Analisa ringkas otomatis: kategori dengan kenaikan & penurunan volume tertinggi terlebih dahulu, baru persentase
            let naikList = catResults.filter(c => c.status === 'naik').sort((x, y) => {
                let diffY = y.b - y.a;
                let diffX = x.b - x.a;
                if (diffY !== diffX) return diffY - diffX;
                return y.pct - x.pct;
            });

            let turunList = catResults.filter(c => c.status === 'turun').sort((x, y) => {
                let diffY = y.a - y.b;
                let diffX = x.a - x.b;
                if (diffY !== diffX) return diffY - diffX;
                return Math.abs(y.pct) - Math.abs(x.pct);
            });

            // Identifikasi kategori dengan volume tertinggi di Bulan A & Bulan B
            const sortedByVolA = [...catResults].filter(c => c.a > 0).sort((x, y) => y.a - x.a);
            const sortedByVolB = [...catResults].filter(c => c.b > 0).sort((x, y) => y.b - x.b);
            const kipData = catResults.find(c => c.label.toUpperCase().includes('KIP TIDAK SESUAI'));
            const mandatoryData = catResults.find(c => c.label.toUpperCase().includes('MANDATORY TICKET'));

            let insightParts = [];
            if (kipData && (kipData.a > 0 || kipData.b > 0)) {
                const diffKip = kipData.b - kipData.a;
                if (kipData.status === 'naik') {
                    insightParts.push(`<div class="d-flex align-items-start gap-2 mb-2"><i class="fa-solid fa-triangle-exclamation text-danger mt-1"></i><div><strong style="color:#A30030;">Perhatian Kritis (KIP Tidak Sesuai):</strong> Kategori <strong>KIP Tidak Sesuai</strong> yang sudah bervolume tinggi di ${escapeHtml(bulanA)} (${kipData.a} tiket) justru melonjak <strong>+${diffKip} tiket (+${kipData.pct}%)</strong> menjadi <strong>${kipData.b} tiket</strong> di ${escapeHtml(bulanB)} — <em>saat ini menjadi volume temuan bad ticket tertinggi dan memerlukan audit kepatuhan khusus.</em></div></div>`);
                } else if (kipData.status === 'turun') {
                    insightParts.push(`<div class="d-flex align-items-start gap-2 mb-2"><i class="fa-solid fa-circle-check text-success mt-1"></i><div><strong style="color:#10B981;">Perbaikan KIP Tidak Sesuai:</strong> Kategori <strong>KIP Tidak Sesuai</strong> berhasil ditekan berkurang <strong>-${Math.abs(diffKip)} tiket (-${Math.abs(kipData.pct)}%)</strong> (dari ${kipData.a} menjadi ${kipData.b} tiket).</div></div>`);
                }
            }

            if (mandatoryData && (mandatoryData.a > 0 || mandatoryData.b > 0)) {
                const diffMandatory = mandatoryData.b - mandatoryData.a;
                if (mandatoryData.status === 'turun') {
                    insightParts.push(`<div class="d-flex align-items-start gap-2 mb-2"><i class="fa-solid fa-circle-check text-success mt-1"></i><div><strong style="color:#10B981;">Penurunan Terbesar (Mandatory Ticket):</strong> Kategori <strong>Mandatory Ticket</strong> yang merupakan volume terbesar di ${escapeHtml(bulanA)} (${mandatoryData.a} tiket) berhasil dipangkas signifikan <strong>-${Math.abs(diffMandatory)} tiket (-${Math.abs(mandatoryData.pct)}%)</strong> menjadi <strong>${mandatoryData.b} tiket</strong>.</div></div>`);
                } else if (mandatoryData.status === 'naik') {
                    insightParts.push(`<div class="d-flex align-items-start gap-2 mb-2"><i class="fa-solid fa-triangle-exclamation text-danger mt-1"></i><div><strong style="color:#A30030;">Kenaikan Mandatory Ticket:</strong> Kategori <strong>Mandatory Ticket</strong> bertambah <strong>+${diffMandatory} tiket (+${mandatoryData.pct}%)</strong> (dari ${mandatoryData.a} menjadi ${mandatoryData.b} tiket).</div></div>`);
                }
            }

            // Kategori lain yang mengalami kenaikan volume di luar KIP & Mandatory
            const otherNaik = naikList.find(c => !c.label.toUpperCase().includes('KIP TIDAK SESUAI') && !c.label.toUpperCase().includes('MANDATORY TICKET'));
            if (otherNaik) {
                const volOther = otherNaik.b - otherNaik.a;
                insightParts.push(`<div class="d-flex align-items-start gap-2 mb-2"><i class="fa-solid fa-arrow-trend-up text-warning mt-1"></i><div><strong>Kenaikan Kategori Lain:</strong> Kategori <strong>${escapeHtml(otherNaik.label)}</strong> bertambah <strong>+${volOther} tiket (+${otherNaik.pct}%)</strong> (dari ${otherNaik.a} ke ${otherNaik.b} tiket).</div></div>`);
            }

            if (insightParts.length === 0) {
                insightParts.push('<div class="d-flex align-items-center gap-2"><i class="fa-solid fa-info-circle text-muted"></i><div>Tidak ditemukan perubahan volume signifikan pada kategori untuk rentang tanggal yang dibandingkan.</div></div>');
            }
            document.getElementById('compareCategoryInsight').innerHTML = insightParts.join('');

            // ===== POPULATE EXECUTIVE SUMMARY =====
            const numDays = dateRange.length;
            const dailyAvgA = numDays > 0 ? (totalA / numDays).toFixed(1) : '0';
            const dailyAvgB = numDays > 0 ? (totalB / numDays).toFixed(1) : '0';

            // 1. Period Label
            const execPeriodLabel = document.getElementById('execPeriodLabel');
            if (execPeriodLabel) {
                execPeriodLabel.innerText = `Rentang Tanggal ${dayStart} - ${dayEnd} (${bulanA} vs ${bulanB})`;
            }

            // 2. Verdict Badge in Header
            const verdictBadgeEl = document.getElementById('execSummaryVerdictBadge');
            if (verdictBadgeEl) {
                if (statusKey === 'turun') {
                    verdictBadgeEl.innerHTML = `<span class="badge px-3 py-2 fw-bold" style="background:#ECFDF5; color:#065F46; border:1px solid #A7F3D0; font-size:0.82rem; border-radius:20px;"><i class="fa-solid fa-circle-check me-1"></i> PERFORMA MEMBAIK (Turun ${Math.abs(netTickets)} Tiket / -${Math.abs(growthPct)}%)</span>`;
                } else if (statusKey === 'naik') {
                    verdictBadgeEl.innerHTML = `<span class="badge px-3 py-2 fw-bold" style="background:#FFF1F2; color:#9F1239; border:1px solid #FECDD3; font-size:0.82rem; border-radius:20px;"><i class="fa-solid fa-triangle-exclamation me-1"></i> PERHATIAN DIPERLUKAN (Naik +${netTickets} Tiket / +${growthPct}%)</span>`;
                } else {
                    verdictBadgeEl.innerHTML = `<span class="badge px-3 py-2 fw-bold" style="background:#F1F5F9; color:#475569; border:1px solid #CBD5E1; font-size:0.82rem; border-radius:20px;"><i class="fa-solid fa-minus me-1"></i> KONDISI STABIL (0 Tiket / 0%)</span>`;
                }
            }

            // 3. Growth Tiket
            const execNetEl = document.getElementById('execNetTickets');
            const execNetPctEl = document.getElementById('execNetPercent');
            if (execNetEl && execNetPctEl) {
                if (netTickets > 0) {
                    execNetEl.innerHTML = `<span style="color:#A30030;">+${netTickets} Tiket</span>`;
                    execNetPctEl.innerHTML = `<span style="color:#A30030;"><i class="fa-solid fa-arrow-trend-up me-1"></i>Naik +${netTickets} tiket (+${growthPct}%) vs ${escapeHtml(bulanA)}</span>`;
                } else if (netTickets < 0) {
                    execNetEl.innerHTML = `<span style="color:#10B981;">${netTickets} Tiket</span>`;
                    execNetPctEl.innerHTML = `<span style="color:#10B981;"><i class="fa-solid fa-arrow-trend-down me-1"></i>Turun ${Math.abs(netTickets)} tiket (-${Math.abs(growthPct)}%) vs ${escapeHtml(bulanA)}</span>`;
                } else {
                    execNetEl.innerHTML = `<span style="color:#64748B;">0 Tiket</span>`;
                    execNetPctEl.innerHTML = `<span style="color:#64748B;"><i class="fa-solid fa-minus me-1"></i>Sama persis dengan ${escapeHtml(bulanA)}</span>`;
                }
            }

            // 4. Rata-rata Tiket / Hari
            const execDailyAvgEl = document.getElementById('execDailyAvg');
            const execDailyAvgSubEl = document.getElementById('execDailyAvgSub');
            if (execDailyAvgEl && execDailyAvgSubEl) {
                execDailyAvgEl.innerText = `${dailyAvgB} / hari`;
                execDailyAvgSubEl.innerHTML = `Bulan A: <strong>${dailyAvgA}</strong> ➔ Bulan B: <strong>${dailyAvgB}</strong>`;
            }

            // 5. Perlu Perhatian (Kritis)
            const execWorstCatEl = document.getElementById('execWorstCategory');
            const execWorstCatStatEl = document.getElementById('execWorstCategoryStat');
            if (execWorstCatEl && execWorstCatStatEl) {
                if (naikList.length > 0) {
                    const topNaik = naikList[0];
                    const diffNaik = topNaik.b - topNaik.a;
                    execWorstCatEl.innerText = topNaik.label;
                    execWorstCatEl.title = topNaik.label;
                    execWorstCatStatEl.innerHTML = `<i class="fa-solid fa-arrow-trend-up me-1"></i>Naik +${diffNaik} tiket (+${topNaik.pct}%) • Total saat ini: ${topNaik.b} tiket`;
                } else {
                    execWorstCatEl.innerText = "Tidak Ada Lonjakan";
                    execWorstCatEl.title = "Tidak ada lonjakan volume tiket";
                    execWorstCatStatEl.innerHTML = `<span style="color:#10B981;"><i class="fa-solid fa-check me-1"></i>Semua kategori terkendali</span>`;
                }
            }

            // 6. Perbaikan Tertinggi
            const execBestCatEl = document.getElementById('execBestCategory');
            const execBestCatStatEl = document.getElementById('execBestCategoryStat');
            if (execBestCatEl && execBestCatStatEl) {
                if (turunList.length > 0) {
                    const topTurun = turunList[0];
                    const diffTurun = topTurun.a - topTurun.b;
                    execBestCatEl.innerText = topTurun.label;
                    execBestCatEl.title = topTurun.label;
                    execBestCatStatEl.innerHTML = `<i class="fa-solid fa-arrow-trend-down me-1"></i>Turun -${diffTurun} tiket (-${Math.abs(topTurun.pct)}%) • Dari ${topTurun.a} ke ${topTurun.b} tiket`;
                } else {
                    execBestCatEl.innerText = "Tidak Ada Penurunan";
                    execBestCatEl.title = "Tidak ada penurunan volume tiket";
                    execBestCatStatEl.innerHTML = `<span style="color:#64748B;"><i class="fa-solid fa-minus me-1"></i>Belum ada perbaikan volume</span>`;
                }
            }

            // 7. Executive Narrative Paragraph
            const execNarrativeEl = document.getElementById('execNarrativeText');
            if (execNarrativeEl) {
                let narrative = "";

                // Bagian 1: Ringkasan Global
                if (statusKey === 'turun') {
                    narrative += `Pada rentang <strong>Tanggal ${dayStart} s/d ${dayEnd}</strong>, akumulasi ketidaksesuaian tiket pada <strong>${escapeHtml(bulanB)} (${totalB} tiket)</strong> mencatatkan kinerja positif dengan <strong>penurunan volume sebesar ${Math.abs(netTickets)} tiket (-${Math.abs(growthPct)}%)</strong> dibandingkan <strong>${escapeHtml(bulanA)} (${totalA} tiket)</strong>. Rata-rata harian tiket berhasil ditekan dari <strong>${dailyAvgA}</strong> menjadi <strong>${dailyAvgB} tiket/hari</strong>. `;
                } else if (statusKey === 'naik') {
                    narrative += `Pada rentang <strong>Tanggal ${dayStart} s/d ${dayEnd}</strong>, akumulasi ketidaksesuaian tiket pada <strong>${escapeHtml(bulanB)} (${totalB} tiket)</strong> mengalami peningkatan volume sebesar <strong>+${netTickets} tiket (+${growthPct}%)</strong> dibandingkan <strong>${escapeHtml(bulanA)} (${totalA} tiket)</strong>. Rata-rata harian tiket bertambah dari <strong>${dailyAvgA}</strong> menjadi <strong>${dailyAvgB} tiket/hari</strong> sehingga menuntut langkah intervensi segera. `;
                } else {
                    narrative += `Pada rentang <strong>Tanggal ${dayStart} s/d ${dayEnd}</strong>, volume ketidaksesuaian tiket pada <strong>${escapeHtml(bulanB)}</strong> dan <strong>${escapeHtml(bulanA)}</strong> berstatus identik yaitu sebesar <strong>${totalA} tiket</strong> dengan rata-rata <strong>${dailyAvgA} tiket/hari</strong>. `;
                }

                // Bagian 1b: Narasi Dampak Sanggahan Diterima
                if (totalB_Sanggahan > 0 || totalA_Sanggahan > 0) {
                    narrative += `Melalui proses evaluasi sanggahan (Kolom O), sebanyak <strong>${totalB_Sanggahan} tiket berhasil dikabulkan pada ${escapeHtml(bulanB)}</strong> (mereduksi bad tiket awal dari ${totalB_All} menjadi ${totalB_Net}), serta <strong>${totalA_Sanggahan} tiket pada ${escapeHtml(bulanA)}</strong> (dari ${totalA_All} menjadi ${totalA_Net}). `;
                }

                // Bagian 2: Tinjauan Volume Baseline (Bulan A)
                if (sortedByVolA.length > 0) {
                    const topA1 = sortedByVolA[0];
                    const topA2 = sortedByVolA.length > 1 ? sortedByVolA[1] : null;
                    if (topA2) {
                        narrative += `Pada periode acuan (<strong>${escapeHtml(bulanA)}</strong>), volume bad ticket sangat terpusat pada dua kategori terbesar, yaitu <strong>${escapeHtml(topA1.label)} (${topA1.a} tiket)</strong> dan <strong>${escapeHtml(topA2.label)} (${topA2.a} tiket)</strong>. `;
                    } else {
                        narrative += `Pada periode acuan (<strong>${escapeHtml(bulanA)}</strong>), volume tiket didominasi oleh kategori <strong>${escapeHtml(topA1.label)} (${topA1.a} tiket)</strong>. `;
                    }
                }

                // Bagian 3: Pembahasan Mendalam KIP Tidak Sesuai
                if (kipData && (kipData.a > 0 || kipData.b > 0)) {
                    const diffKip = kipData.b - kipData.a;
                    if (kipData.status === 'naik') {
                        narrative += `Perhatian khusus harus diarahkan pada <strong>KIP Tidak Sesuai</strong>: meskipun pada ${escapeHtml(bulanA)} sudah mencatat volume tinggi (${kipData.a} tiket), pada ${escapeHtml(bulanB)} volumenya justru kembali bertambah <strong>+${diffKip} tiket (+${kipData.pct}%)</strong> hingga mencapai <strong>${kipData.b} tiket</strong>, menjadikannya kontributor temuan tertinggi (#1) saat ini. `;
                    } else if (kipData.status === 'turun') {
                        narrative += `Kategori <strong>KIP Tidak Sesuai</strong> yang pada periode sebelumnya bervolume tinggi (${kipData.a} tiket) berhasil diturunkan sebesar <strong>-${Math.abs(diffKip)} tiket (-${Math.abs(kipData.pct)}%)</strong> menjadi <strong>${kipData.b} tiket</strong>. `;
                    } else {
                        narrative += `Kategori <strong>KIP Tidak Sesuai</strong> yang di periode sebelumnya berbobot tinggi (${kipData.a} tiket) relatif konstan di angka <strong>${kipData.b} tiket</strong>. `;
                    }
                }

                // Bagian 4: Pembahasan Mandatory Ticket & Penurunan Terbesar
                if (mandatoryData && mandatoryData.status === 'turun' && (mandatoryData.a > 0 || mandatoryData.b > 0)) {
                    const volMandatory = mandatoryData.a - mandatoryData.b;
                    narrative += `Di sisi lain, pendorong efisiensi volume terbesar diraih oleh <strong>Mandatory Ticket</strong> yang berhasil dipangkas signifikan sebesar <strong>-${volMandatory} tiket (-${Math.abs(mandatoryData.pct)}%)</strong> (dari ${mandatoryData.a} menjadi ${mandatoryData.b} tiket). `;
                } else if (turunList.length > 0) {
                    const topTurun = turunList[0];
                    if (!kipData || topTurun.label !== kipData.label) {
                        const volTurun = topTurun.a - topTurun.b;
                        narrative += `Pendorong efisiensi volume terbesar dicapai oleh kategori <strong>${escapeHtml(topTurun.label)}</strong> yang berhasil berkurang sebanyak <strong>-${volTurun} tiket (-${Math.abs(topTurun.pct)}%)</strong>. `;
                    }
                }

                // Bagian 5: Kategori Kenaikan Lainnya jika ada
                const otherCritical = naikList.find(c => (!kipData || c.label !== kipData.label) && (c.b - c.a >= 3));
                if (otherCritical) {
                    narrative += `Kenaikan volume juga terdeteksi pada kategori <strong>${escapeHtml(otherCritical.label)}</strong> (+${otherCritical.b - otherCritical.a} tiket / +${otherCritical.pct}%).`;
                }

                execNarrativeEl.innerHTML = narrative;
            }

            // 8. Actionable Recommendation Pills
            const execRecEl = document.getElementById('execRecommendations');
            if (execRecEl) {
                let recs = [];
                // Prioritas Utama: KIP Tidak Sesuai jika naik atau bervolume tinggi
                if (kipData && kipData.status === 'naik') {
                    const diffKip = kipData.b - kipData.a;
                    recs.push(`<span class="recommendation-pill recommendation-pill-danger"><i class="fa-solid fa-triangle-exclamation"></i> Prioritas Utama: Evaluasi menyeluruh SOP dan pendampingan khusus kategori "KIP Tidak Sesuai" (+${diffKip} tiket, total ${kipData.b} tiket) yang kini menjadi kontributor bad ticket tertinggi</span>`);
                } else if (naikList.length > 0) {
                    const topNaik = naikList[0];
                    const volNaik = topNaik.b - topNaik.a;
                    recs.push(`<span class="recommendation-pill recommendation-pill-danger"><i class="fa-solid fa-crosshairs"></i> Fokus Audit: Prioritaskan coaching pada kategori "${escapeHtml(topNaik.label)}" (+${volNaik} tiket)</span>`);
                }

                // Best Practice: Mandatory Ticket jika turun signifikan
                if (mandatoryData && mandatoryData.status === 'turun') {
                    const volMandatory = mandatoryData.a - mandatoryData.b;
                    recs.push(`<span class="recommendation-pill recommendation-pill-success"><i class="fa-solid fa-circle-check"></i> Best Practice: Pertahankan mekanisme kontrol "Mandatory Ticket" (-${volMandatory} tiket) dan jadikan standar kerja rutin</span>`);
                } else if (turunList.length > 0) {
                    const topTurun = turunList[0];
                    const volTurun = topTurun.a - topTurun.b;
                    recs.push(`<span class="recommendation-pill recommendation-pill-success"><i class="fa-solid fa-circle-check"></i> Best Practice: Adopsi penanganan kategori "${escapeHtml(topTurun.label)}" (-${volTurun} tiket) ke unit lainnya</span>`);
                }

                // Rekomendasi Sanggahan
                if (totalB_Sanggahan > 0) {
                    recs.push(`<span class="recommendation-pill recommendation-pill-info"><i class="fa-solid fa-gavel"></i> Evaluasi Sanggahan: Sebanyak ${totalB_Sanggahan} tiket berhasil disetujui sanggahannya pada ${escapeHtml(bulanB)} — pastikan validitas klarifikasi dijadikan referensi audit berikutnya</span>`);
                }

                // Monitoring
                if (statusKey === 'turun') {
                    recs.push(`<span class="recommendation-pill recommendation-pill-info"><i class="fa-solid fa-chart-line"></i> Monitoring: Lanjutkan tren positif penurunan total tiket (-${Math.abs(growthPct)}%) hingga akhir siklus bulan</span>`);
                } else {
                    recs.push(`<span class="recommendation-pill recommendation-pill-info"><i class="fa-solid fa-bell"></i> Monitoring: Lakukan audit harian bersama Team Leader & Supervisor</span>`);
                }

                execRecEl.innerHTML = recs.join('');
            }

            // Unhide all result rows & hide empty state
            const execSummaryRow = document.getElementById('compareExecutiveSummaryRow');
            if (execSummaryRow) execSummaryRow.style.display = 'block';
            const sghRow = document.getElementById('compareSanggahanBoxRow');
            if (sghRow) sghRow.style.display = 'block';
            document.getElementById('compareResultRow').style.display = 'flex';
            document.getElementById('compareChartRow').style.display = 'flex';
            document.getElementById('compareCategoryRow').style.display = 'flex';
            document.getElementById('compareEmptyState').style.display = 'none';
        }

        


        // 4. TABEL BREAKDOWN AGENT (TREN HARIAN & KOMPARASI BULAN) - SINKRON DENGAN FILTER DATA BREAKDOWN
        function renderBreakdownTable(data) {
            const bulanA = document.getElementById('bdTrendBulanA') ? document.getElementById('bdTrendBulanA').value.trim() : '';
            const bulanB = document.getElementById('bdTrendBulanB') ? document.getElementById('bdTrendBulanB').value.trim() : '';
            const fTgl = document.getElementById('filBdTanggal') ? document.getElementById('filBdTanggal').value.trim() : '';
            const fThn = document.getElementById('filBdTahun') ? document.getElementById('filBdTahun').value.trim() : '';
            const fUnit = document.getElementById('filBdUnit') ? document.getElementById('filBdUnit').value.trim() : '';
            const fKatL = document.getElementById('filBdKategoriL') ? document.getElementById('filBdKategoriL').value.trim() : '';
            const fSourceBy = document.getElementById('filBdSourceBy') ? document.getElementById('filBdSourceBy').value.trim() : '';
            const fSpv = document.getElementById('filBdSpv') ? document.getElementById('filBdSpv').value.trim() : '';
            const fTl = document.getElementById('filBdTl') ? document.getElementById('filBdTl').value.trim() : '';
            const fKip = document.getElementById('filBdKip') ? document.getElementById('filBdKip').value.trim() : '';
            const sAgentName = document.getElementById('searchBreakdownAgentName') ? document.getElementById('searchBreakdownAgentName').value.toLowerCase().trim() : '';
            const sAgentSearchPanel = document.getElementById('filBdAgentSearch') ? document.getElementById('filBdAgentSearch').value.toLowerCase().trim() : '';

            let maxDay = 31;
            if (fTgl !== "") {
                const parsed = parseInt(fTgl, 10);
                if (!isNaN(parsed) && parsed >= 1 && parsed <= 31) maxDay = parsed;
            }

            // Update label header kolom mengikuti bulan yang dipilih
            const thA = document.getElementById('thBdBulanA');
            const thB = document.getElementById('thBdBulanB');
            if (thA) thA.innerText = bulanA || 'Bulan A';
            if (thB) thB.innerText = bulanB || 'Bulan B';

            // Sumber data untuk komparasi Bulan A vs Bulan B (tersaring SPV, TL, Unit, Kat, KIP, Source, Agent Search)
            let compareSource = allRecords.filter(row => {
                let matchUnit = fUnit === "" || String(row[9]).trim() === fUnit;
                let matchKatL = fKatL === "" || String(row[11]).trim().toUpperCase() === fKatL.trim().toUpperCase();
                let matchSourceBy = fSourceBy === "" || String(row[15]).trim() === fSourceBy;
                let matchSpv = fSpv === "" || String(row[8]).trim() === fSpv;
                let matchTl = fTl === "" || String(row[7]).trim() === fTl;
                let matchKip = fKip === "" || String(row[10]).trim() === fKip;
                let rowAgent = (row[6] != null) ? String(row[6]).toLowerCase() : '';
                let matchAgentName = (sAgentName === "" || rowAgent.includes(sAgentName)) &&
                                     (sAgentSearchPanel === "" || rowAgent.includes(sAgentSearchPanel));
                let matchThn = fThn === "" || String(row[2]).trim() === fThn;
                let rDate = parseInt(row[0], 10);
                let matchTgl = fTgl === "" || (!isNaN(rDate) && rDate >= 1 && rDate <= maxDay);
                return matchUnit && matchKatL && matchSourceBy && matchSpv && matchTl && matchKip && matchAgentName && matchThn && matchTgl;
            });

            let agentMap = {};

            // 1. Masukkan seluruh agent dari komparasi Bulan A vs Bulan B
            compareSource.forEach(row => {
                let agent = row[6];
                let unit = row[9];
                let tl = row[7];
                let spv = row[8];
                let bln = String(row[1]).trim();
                if (!agent) return;
                if (bln !== bulanA && bln !== bulanB) return;
                if (!agentMap[agent]) agentMap[agent] = { unit: unit, tl: tl, spv: spv, countA: 0, countB: 0 };
                if (bln === bulanA) agentMap[agent].countA++;
                if (bln === bulanB) agentMap[agent].countB++;
            });

            // 2. PASTI masukkan setiap agent yang memiliki record pada filter aktif (data)
            data.forEach(row => {
                let agent = row[6];
                let unit = row[9];
                let tl = row[7];
                let spv = row[8];
                if (!agent) return;
                if (!agentMap[agent]) {
                    agentMap[agent] = { unit: unit, tl: tl, spv: spv, countA: 0, countB: 0 };
                }
            });

            // 3. Sparkline Tren Harian dihitung dari filtered dataset (data)
            let dailyMap = {};
            data.forEach(row => {
                let agent = row[6];
                if (!agent) return;
                let tgl = String(row[0]).trim();
                if (!dailyMap[agent]) dailyMap[agent] = {};
                dailyMap[agent][tgl] = (dailyMap[agent][tgl] || 0) + 1;
            });

            // Hitung growth% & status untuk setiap agent
            let agentList = Object.entries(agentMap).map(([agentName, info]) => {
                const { countA, countB } = info;
                let statusKey = 'stabil';
                let pct = 0;
                if (countA !== countB) {
                    if (countB > countA) {
                        statusKey = 'naik';
                        pct = countA === 0 ? 100 : Math.round(((countB - countA) / countA) * 100);
                    } else {
                        statusKey = 'turun';
                        pct = countA === 0 ? -100 : Math.round(((countB - countA) / countA) * 100);
                    }
                }

                let dailyForAgent = dailyMap[agentName] || {};
                let dateKeys = Object.keys(dailyForAgent).sort((a, b) => Number(a) - Number(b));
                let values = dateKeys.map(d => dailyForAgent[d]);

                return { agentName, info, values, statusKey, pct };
            });

            // Terapkan mode sorting
            const sortMode = document.getElementById('bdSortMode') ? document.getElementById('bdSortMode').value : 'total_desc';
            if (sortMode === 'total_asc') {
                agentList.sort((a, b) => (a.info.countA + a.info.countB) - (b.info.countA + b.info.countB));
            } else if (sortMode === 'naik' || sortMode === 'turun' || sortMode === 'stabil') {
                agentList.sort((a, b) => {
                    const aMatch = a.statusKey === sortMode ? 0 : 1;
                    const bMatch = b.statusKey === sortMode ? 0 : 1;
                    if (aMatch !== bMatch) return aMatch - bMatch;
                    return (b.info.countA + b.info.countB) - (a.info.countA + a.info.countB);
                });
            } else {
                agentList.sort((a, b) => (b.info.countA + b.info.countB) - (a.info.countA + a.info.countB));
            }

            let tbody = document.getElementById('breakdownAgentTable');
            if (!tbody) return;
            tbody.innerHTML = "";

            if (agentList.length === 0) {
                tbody.innerHTML = '<tr><td colspan="10" class="text-center py-4 text-muted"><i class="fa-solid fa-filter fa-lg mb-2 d-block" style="color:#CBD5E1;"></i>Tidak ada data untuk filter yang dipilih.</td></tr>';
                return;
            }

            let rowsHtml = agentList.map((item, index) => {
                const { agentName, info, values, statusKey, pct } = item;

                let statusBadge;
                if (statusKey === 'naik') {
                    statusBadge = `<span class="badge-growth-chip growth-up"><i class="fa-solid fa-arrow-trend-up me-1"></i>+${Math.abs(pct)}%</span>`;
                } else if (statusKey === 'turun') {
                    statusBadge = `<span class="badge-growth-chip growth-down"><i class="fa-solid fa-arrow-trend-down me-1"></i>${pct}%</span>`;
                } else {
                    statusBadge = `<span class="badge-growth-chip growth-stable"><i class="fa-solid fa-minus me-1"></i>0%</span>`;
                }

                return `
                    <tr>
                        <td class="text-center"><span class="badge-rank rank-normal">${index + 1}</span></td>
                        <td>
                            <div class="d-flex align-items-center gap-2">
                                <span class="avatar-initials">${getInitials(agentName)}</span>
                                <span class="agent-name-style text-truncate" style="max-width:210px;" title="${escapeHtml(agentName)}">${escapeHtml(agentName)}</span>
                            </div>
                        </td>
                        <td><span class="unit-name-style">${escapeHtml(info.unit || '-')}</span></td>
                        <td><span class="unit-name-style">${escapeHtml(info.tl || '-')}</span></td>
                        <td><span class="unit-name-style">${escapeHtml(info.spv || '-')}</span></td>
                        <td class="text-center fw-bold" style="color:#0F172A; font-variant-numeric:tabular-nums;">${info.countA}</td>
                        <td class="text-center fw-bold" style="color:#0F172A; font-variant-numeric:tabular-nums;">${info.countB}</td>
                        <td class="text-center">${statusBadge}</td>
                        <td class="text-center">${buildSparklineSVG(values)}</td>
                        <td class="text-center">
                            <button class="btn-detail-pill" onclick="showBreakdownDetail('${escapeJsAttr(agentName)}')" title="Lihat detail bad tiket agent ini">
                                <i class="fa-solid fa-arrow-up-right-from-square"></i>Detail
                            </button>
                        </td>
                    </tr>
                `;
            }).join('');
            tbody.innerHTML = rowsHtml;
        }

        function downloadBreakdownTemuanExcel() {
            const list = currentBdRawTemuanList && currentBdRawTemuanList.length > 0
                ? currentBdRawTemuanList
