                alert('Tidak ada data temuan untuk diunduh. Silakan pilih parameter dan klik Cari Data terlebih dahulu.');
                return;
            }

            ensureXLSXLibrary(function () {
                const headers = [
                    'No', 'Tanggal Input Solver (D)', 'SIAD Agent (F)', 'Nama Agent (G)',
                    'Nama TL (H)', 'Nama SPV (I)', 'Unit Name (J)', 'No Tiket (E)',
                    'KIP (K)', 'Kategori Bad Ticket (L)', 'Detil Bad Ticket (M)',
                    'Notes by Solver (N)', 'Final Status (O)', 'Source by (P)'
                ];

                const rows = list.map((row, idx) => [
