                    { wch: 18 }, { wch: 18 }, { wch: 16 }, { wch: 14 },
                    { wch: 28 }, { wch: 26 }, { wch: 34 }, { wch: 34 },
                    { wch: 16 }, { wch: 14 }
                ];

                const workbook = XLSX.utils.book_new();
                XLSX.utils.book_append_sheet(workbook, worksheet, 'Temuan Team Insights');

                const tz = new Date();
                const stamp = `${tz.getFullYear()}${String(tz.getMonth() + 1).padStart(2, '0')}${String(tz.getDate()).padStart(2, '0')}_${String(tz.getHours()).padStart(2, '0')}${String(tz.getMinutes()).padStart(2, '0')}`;
