        function fillBreakdownVsMonthSelectors() {
            const selBefore = document.getElementById('bdVsBulanBefore');
            const selAfter = document.getElementById('bdVsBulanAfter');
            if (!selBefore || !selAfter) return;
            selBefore.innerHTML = "";
            selAfter.innerHTML = "";
            bulanTerurutGlobal.forEach((val) => {
                if (val && val.toString().trim() !== "") {
                    selBefore.options[selBefore.options.length] = new Option(val, val);
                    selAfter.options[selAfter.options.length] = new Option(val, val);
                }
            });

            // Default pilih bulan yang sedang dibandingkan di toolbar tabel utama breakdown (jika ada)
            const mainBlnA = document.getElementById('bdTrendBulanA') ? document.getElementById('bdTrendBulanA').value.trim() : '';
            const mainBlnB = document.getElementById('bdTrendBulanB') ? document.getElementById('bdTrendBulanB').value.trim() : '';

            if (mainBlnA && [...selBefore.options].some(o => o.value === mainBlnA)) {
                selBefore.value = mainBlnA;
            } else if (selBefore.options.length > 0) {
                selBefore.selectedIndex = 0;
            }

            if (mainBlnB && [...selAfter.options].some(o => o.value === mainBlnB)) {
                selAfter.value = mainBlnB;
            } else if (selAfter.options.length > 1) {
                selAfter.selectedIndex = 1;
            } else if (selAfter.options.length > 0) {
                selAfter.selectedIndex = 0;
            }
        }

        // Grafik perbandingan (VS) jumlah tiket seorang agent antara dua bulan, sesuai filter tanggal yang dipilih
        function renderBreakdownVsChart(agentName) {
            if (!agentName) return;
            destroyChart('breakdownVs');

            const vsBefore = document.getElementById('bdVsBulanBefore') ? document.getElementById('bdVsBulanBefore').value.trim() : '';
            const vsAfter = document.getElementById('bdVsBulanAfter') ? document.getElementById('bdVsBulanAfter').value.trim() : '';
            const fTgl = document.getElementById('filBdTanggal') ? document.getElementById('filBdTanggal').value.trim() : '';
            const fThn = document.getElementById('filBdTahun') ? document.getElementById('filBdTahun').value.trim() : '';
            const fUnit = document.getElementById('filBdUnit') ? document.getElementById('filBdUnit').value.trim().toUpperCase() : '';
            const fKatL = document.getElementById('filBdKategoriL') ? document.getElementById('filBdKategoriL').value.trim().toUpperCase() : '';
            const fSourceBy = document.getElementById('filBdSourceBy') ? document.getElementById('filBdSourceBy').value.trim().toUpperCase() : '';

            let maxDay = 31;
            if (fTgl !== "") {
                const parsed = parseInt(fTgl, 10);
                if (!isNaN(parsed) && parsed >= 1 && parsed <= 31) {
                    maxDay = parsed;
                }
            }

            // Rentang tanggal yang ditampilkan pada grafik:
            // Ketika tanggal yang dipilih tgl 6, grafik memunculkan tgl 1-6 (tgl 1-6 dst).
            // Jika "Semua Tanggal", tampilkan tgl 1 s/d 31.
            let targetDates = Array.from({ length: maxDay }, (_, i) => String(i + 1));

            // Tampilkan badge info tanggal yang sedang dibandingkan
            const infoEl = document.getElementById('modalBreakdownFilterInfo');
            if (infoEl) {
                if (fTgl !== "") {
                    infoEl.innerHTML = `<span class="badge bg-danger-subtle text-danger border px-2 py-1"><i class="fa-solid fa-calendar-days me-1"></i>Periode Tanggal: 1 s/d ${maxDay} (MTD)</span>` +
                        (fThn ? ` <span class="badge bg-light text-muted border px-2 py-1 ms-1">Tahun ${fThn}</span>` : '');
                } else {
                    infoEl.innerHTML = `<span class="badge bg-light text-muted border px-2 py-1"><i class="fa-solid fa-calendar-days me-1"></i>Semua Tanggal (1 s/d 31)</span>` +
                        (fThn ? ` <span class="badge bg-light text-muted border px-2 py-1 ms-1">Tahun ${fThn}</span>` : '');
                }
            }

            let countsBefore = {}, countsAfter = {};
            targetDates.forEach(d => { countsBefore[d] = 0; countsAfter[d] = 0; });
            let sumBefore = 0, sumAfter = 0;

            allRecords.forEach(row => {
                let rowAgent = String(row[6]).trim();
                if (rowAgent !== agentName) return;

                let rowTgl = String(row[0]).trim();
                let rowBln = String(row[1]).trim();
                let rowThn = String(row[2]).trim();
                let rowUnit = String(row[9]).trim().toUpperCase();
                let rowL = String(row[11]).trim().toUpperCase();
                let rowSourceBy = String(row[15]).trim().toUpperCase();

                let rDate = parseInt(rowTgl, 10);
                let matchTgl = (fTgl === "" || (!isNaN(rDate) && rDate >= 1 && rDate <= maxDay));
                let matchThn = (fThn === "" || rowThn === fThn);
                let matchUnit = (fUnit === "" || rowUnit === fUnit);
                let matchL = (fKatL === "" || rowL === fKatL);
                let matchSourceBy = (fSourceBy === "" || rowSourceBy === fSourceBy);

                if (matchTgl && matchThn && matchUnit && matchL && matchSourceBy) {
                    if (rowBln === vsBefore && countsBefore[rowTgl] !== undefined) {
                        countsBefore[rowTgl]++;
                        sumBefore++;
                    }
                    if (rowBln === vsAfter && countsAfter[rowTgl] !== undefined) {
                        countsAfter[rowTgl]++;
                        sumAfter++;
                    }
                }
            });

            // Update total tiket di footer modal
            const totalCountEl = document.getElementById('modalBreakdownTotalCount');
            if (totalCountEl) {
                totalCountEl.innerHTML = `Total Tiket (Tgl 1 s/d ${maxDay}): <strong class="text-navy">${sumBefore + sumAfter}</strong> tiket &nbsp;•&nbsp; ` +
                    `<span class="badge bg-danger-subtle text-danger fw-bold px-2 py-1 me-1">${vsBefore || 'Bulan A'}: ${sumBefore}</span>` +
                    `<span class="badge bg-primary-subtle text-primary fw-bold px-2 py-1">${vsAfter || 'Bulan B'}: ${sumAfter}</span>`;
            }

            const chartCanvas = document.getElementById('chartBreakdownVs');
            if (!chartCanvas) return;

            const labels = targetDates;

            activeCharts['breakdownVs'] = new Chart(chartCanvas, {
                type: 'bar',
                data: {
                    labels: labels,
                    datasets: [
                        {
                            label: vsBefore ? `Bulan: ${vsBefore}` : 'Bulan Sebelum',
                            data: targetDates.map(d => countsBefore[d]),
                            backgroundColor: '#A30030',
                            borderRadius: { topLeft: 5, topRight: 5 },
                            borderSkipped: false,
                            maxBarThickness: maxDay <= 7 ? 32 : (maxDay <= 15 ? 22 : 18),
                            barPercentage: 0.85,
                            categoryPercentage: 0.85
                        },
                        {
                            label: vsAfter ? `Bulan: ${vsAfter}` : 'Bulan Sesudah',
                            data: targetDates.map(d => countsAfter[d]),
                            backgroundColor: '#2563EB',
                            borderRadius: { topLeft: 5, topRight: 5 },
                            borderSkipped: false,
                            maxBarThickness: maxDay <= 7 ? 32 : (maxDay <= 15 ? 22 : 18),
                            barPercentage: 0.85,
                            categoryPercentage: 0.85
                        }
                    ]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            display: true,
                            labels: {
                                color: '#475569',
                                font: { family: 'Poppins', size: 11, weight: '600' },
                                usePointStyle: true,
                                pointStyle: 'circle',
                                boxWidth: 8,
                                boxHeight: 8,
                                padding: 16
                            }
                        },
                        datalabels: barDataLabelOptions
                    },
                    scales: {
                        y: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 }, stepSize: 1 },
                            grid: { color: 'rgba(226, 232, 240, 0.7)', drawBorder: false },
                            border: { display: false },
                            beginAtZero: true,
                            title: { display: true, text: 'Jumlah Tiket', color: '#64748B', font: { family: 'Poppins', size: 11, weight: '600' } }
                        },
                        x: {
                            ticks: { color: '#64748B', font: { family: 'Poppins', size: 10 } },
                            grid: { display: false },
                            border: { display: false }
                        }
                    }
                }
            });
        }

