        // Helper untuk meringkas daftar teks panjang (Detail kolom M atau Notes kolom N)
        // Mengagregasi frekuensi kalimat/frasa dengan case-insensitive deduplication
        function summarizeKipTexts(textArray, maxItems) {
            if (!textArray || textArray.length === 0) return ['<span class="text-muted">-</span>'];
            const freq = {};
            const labelVariants = {};

            textArray.forEach(txt => {
                if (!txt) return;
                let clean = String(txt).trim();
                if (!clean || clean === '-' || clean.toLowerCase() === 'null') return;
                // Rapikan spasi ganda dan hilangkan tanda baca akhir seperti titik/koma/titik dua
                clean = clean.replace(/\s+/g, ' ').replace(/[.,;:!?]+$/, '').trim();
                if (!clean) return;

                // Normalisasi huruf kecil untuk grouping case-insensitive
                const normKey = clean.toLowerCase();
                freq[normKey] = (freq[normKey] || 0) + 1;

                if (!labelVariants[normKey]) labelVariants[normKey] = {};
                labelVariants[normKey][clean] = (labelVariants[normKey][clean] || 0) + 1;
            });

            const sorted = Object.entries(freq).sort((a, b) => b[1] - a[1]);
            if (sorted.length === 0) return ['<span class="text-muted">-</span>'];

            const limit = maxItems || 2;
            const top = sorted.slice(0, limit);
            const items = top.map(([normKey, totalCount]) => {
                // Pilih varian teks yang paling sering digunakan (frekuensi kemunculan terbanyak)
                const variants = labelVariants[normKey] || {};
                const bestPhrase = Object.entries(variants).sort((a, b) => b[1] - a[1])[0][0];

                const countBadge = totalCount > 1 ? ` <span class="badge bg-secondary-subtle text-secondary" style="font-size:0.7rem; font-weight:700;">${totalCount}x</span>` : '';
                return `${bestPhrase}${countBadge}`;
            });

            if (sorted.length > limit) {
                const remaining = sorted.length - limit;
                items.push(`<span class="text-muted small" style="font-size:0.72rem;">+${remaining} catatan lainnya</span>`);
            }
            return items;
        }

        function filterAndRenderBreakdownKip() {
            if (!allRecords || allRecords.length === 0) return;

            const fTgl = (document.getElementById('filKipTanggal')?.value || '').trim();
            const fBln = (document.getElementById('filKipBulan')?.value || '').trim().toUpperCase();
            const fThn = (document.getElementById('filKipTahun')?.value || '').trim();
            const fUnit = (document.getElementById('filKipUnit')?.value || '').trim();
            const fSrc = (document.getElementById('filKipSourceBy')?.value || '').trim();
            const fKatL = (document.getElementById('filKipKategoriL')?.value || '').trim();
            const fKip = (document.getElementById('filKipNama')?.value || '').trim();
            const fStatusSgh = (document.getElementById('filKipStatusSanggahan')?.value || 'net').trim();
            const fSearch = (document.getElementById('searchKipInput')?.value || '').trim().toLowerCase();

            let maxDay = 31;
            if (fTgl !== "") {
                const parsed = parseInt(fTgl, 10);
                if (!isNaN(parsed) && parsed >= 1 && parsed <= 31) maxDay = parsed;
            }

            // Saring rawRecords (Tanggal dihitung kumulatif 1 s/d maxDay jika tanggal dipilih)
            kipCurrentFilteredRecords = allRecords.filter(row => {
                let rDate = parseInt(row[0], 10);
                let matchTgl = fTgl === "" || (!isNaN(rDate) && rDate >= 1 && rDate <= maxDay);
                if (!matchTgl) return false;
                if (fBln && String(row[1]).trim().toUpperCase() !== fBln) return false;
                if (fThn && String(row[2]).trim() !== fThn) return false;
                if (fUnit && String(row[9]).trim() !== fUnit) return false;
                if (fSrc && String(row[15]).trim() !== fSrc) return false;
                if (fKatL && String(row[11]).trim() !== fKatL) return false;
                if (fKip && String(row[10]).trim() !== fKip) return false;
                if (fStatusSgh === 'net' && isSanggahanDiterima(row)) return false;
                if (fStatusSgh === 'only_sanggahan' && !isSanggahanDiterima(row)) return false;

                if (fSearch) {
                    const kipText = String(row[10] || '').toLowerCase();
                    const katText = String(row[11] || '').toLowerCase();
                    const detilText = String(row[12] || '').toLowerCase();
                    const notesText = String(row[13] || '').toLowerCase();
                    if (!kipText.includes(fSearch) && !katText.includes(fSearch) && !detilText.includes(fSearch) && !notesText.includes(fSearch)) {
                        return false;
                    }
                }
                return true;
            });

            // Agregasi per pasangan (KIP, Kategori L)
            const mapGroup = {};
            const kipTotalMap = {};
            const categoryTotalMap = {};

            kipCurrentFilteredRecords.forEach(row => {
                const kip = (row[10] && String(row[10]).trim() !== '') ? String(row[10]).trim() : '(Tanpa KIP)';
                const katL = (row[11] && String(row[11]).trim() !== '') ? String(row[11]).trim() : '(Tanpa Kategori)';
                const detilM = row[12] ? String(row[12]).trim() : '';
                const notesN = row[13] ? maskNotesKolomN(String(row[13]).trim()) : '';

                const key = kip + '____' + katL;
                if (!mapGroup[key]) {
                    mapGroup[key] = {
                        key: key,
                        kip: kip,
                        kategoriL: katL,
                        count: 0,
                        details: [],
                        notes: [],
                        matchedRows: []
                    };
                }
                mapGroup[key].count++;
                if (detilM && detilM !== '-') mapGroup[key].details.push(detilM);
                if (notesN && notesN !== '-') mapGroup[key].notes.push(notesN);
                mapGroup[key].matchedRows.push(row);

                kipTotalMap[kip] = (kipTotalMap[kip] || 0) + 1;
                categoryTotalMap[katL] = (categoryTotalMap[katL] || 0) + 1;
            });

            // Urutkan grup berdasarkan jumlah tiket terbanyak
            kipAggregatedData = Object.values(mapGroup).sort((a, b) => b.count - a.count);

            // Update Label Filter Aktif
            const filterParts = [];
            if (fBln) filterParts.push(fBln);
            if (fTgl) filterParts.push('Tgl 1-' + fTgl);
            if (fThn) filterParts.push(fThn);
            if (fUnit) filterParts.push(fUnit);
            if (fKatL) filterParts.push(fKatL);
            if (fKip) filterParts.push(fKip);
            if (fSrc) filterParts.push(fSrc);
            const filterLabelText = filterParts.length > 0 ? ('Filter: ' + filterParts.join(' | ')) : 'Filter Aktif: Semua Data';
            const execFilterLabelEl = document.getElementById('kipExecFilterLabel');
            if (execFilterLabelEl) execFilterLabelEl.innerText = filterLabelText;

            // Render KPI & Executive Summary
            renderKipExecutiveSummary(kipAggregatedData, kipTotalMap, categoryTotalMap, kipCurrentFilteredRecords.length);

            // Render Charts
            renderKipCharts(kipTotalMap, categoryTotalMap);

            // Render Table
            kipCurrentPage = 1;
            handleKipTableSearch();
        }

        function renderKipExecutiveSummary(aggregatedList, kipTotalMap, categoryTotalMap, totalTickets) {
            const elTotalTiket = document.getElementById('kipKpiTotalTiket');
            const elTotalTiketSub = document.getElementById('kipKpiTotalTiketSub');
            const elTotalKip = document.getElementById('kipKpiTotalKip');
            const elTopKipName = document.getElementById('kipKpiTopKipName');
            const elTopKipStat = document.getElementById('kipKpiTopKipStat');
            const elTopKatName = document.getElementById('kipKpiTopKategoriName');
            const elTopKatStat = document.getElementById('kipKpiTopKategoriStat');
            const narrativeBox = document.getElementById('kipNarrativeText');
            const actionGrid = document.getElementById('kipActionGrid');

            if (totalTickets === 0) {
                if (elTotalTiket) elTotalTiket.innerText = '0';
                if (elTotalTiketSub) elTotalTiketSub.innerText = '0% dari database';
                if (elTotalKip) elTotalKip.innerText = '0';
                if (elTopKipName) elTopKipName.innerText = '-';
                if (elTopKipStat) elTopKipStat.innerText = '0 tiket';
                if (elTopKatName) elTopKatName.innerText = '-';
                if (elTopKatStat) elTopKatStat.innerText = '0 tiket';
                if (narrativeBox) narrativeBox.innerHTML = '<span class="text-muted">Tidak ada data tiket yang cocok dengan parameter filter yang dipilih.</span>';
                if (actionGrid) actionGrid.innerHTML = '';
                return;
            }

            const totalAllDb = allRecords.length || 1;
            const pctOfDb = ((totalTickets / totalAllDb) * 100).toFixed(1);

            // Urutkan KIP unik terbanyak
            const sortedKips = Object.entries(kipTotalMap).sort((a, b) => b[1] - a[1]);
            const totalUniqueKips = sortedKips.length;
            const topKipEntry = sortedKips[0] || ['-', 0];
            const topKipPct = totalTickets > 0 ? ((topKipEntry[1] / totalTickets) * 100).toFixed(1) : 0;

            // Urutkan Kategori unik terbanyak
            const sortedCategories = Object.entries(categoryTotalMap).sort((a, b) => b[1] - a[1]);
            const topKatEntry = sortedCategories[0] || ['-', 0];
            const topKatPct = totalTickets > 0 ? ((topKatEntry[1] / totalTickets) * 100).toFixed(1) : 0;

            // Update 4 KPI Cards
            if (elTotalTiket) elTotalTiket.innerText = totalTickets.toLocaleString('id-ID');
            if (elTotalTiketSub) elTotalTiketSub.innerText = `${pctOfDb}% dari seluruh database (${totalAllDb.toLocaleString('id-ID')} tiket)`;

            // Hitung status sanggahan pada KIP aktif
            const fTglK = (document.getElementById('filKipTanggal')?.value || '').trim();
            const fBlnK = (document.getElementById('filKipBulan')?.value || '').trim().toUpperCase();
            const fThnK = (document.getElementById('filKipTahun')?.value || '').trim();
            const fUnitK = (document.getElementById('filKipUnit')?.value || '').trim();
            const fSrcK = (document.getElementById('filKipSourceBy')?.value || '').trim();
            const fKatLK = (document.getElementById('filKipKategoriL')?.value || '').trim();
            const fKipK = (document.getElementById('filKipNama')?.value || '').trim();
            const fSearchK = (document.getElementById('searchKipInput')?.value || '').trim().toLowerCase();

            let maxDayKip = 31;
            if (fTglK !== "") {
                const parsed = parseInt(fTglK, 10);
                if (!isNaN(parsed) && parsed >= 1 && parsed <= 31) maxDayKip = parsed;
            }

            let kipScopeAll = 0, kipScopeSgh = 0, kipScopeNet = 0;
            allRecords.forEach(row => {
                let rDate = parseInt(row[0], 10);
                let matchTgl = fTglK === "" || (!isNaN(rDate) && rDate >= 1 && rDate <= maxDayKip);
                if (!matchTgl) return;
                if (fBlnK && String(row[1]).trim().toUpperCase() !== fBlnK) return;
                if (fThnK && String(row[2]).trim() !== fThnK) return;
                if (fUnitK && String(row[9]).trim() !== fUnitK) return;
                if (fSrcK && String(row[15]).trim() !== fSrcK) return;
                if (fKatLK && String(row[11]).trim() !== fKatLK) return;
                if (fKipK && String(row[10]).trim() !== fKipK) return;
                if (fSearchK) {
                    const kipText = String(row[10] || '').toLowerCase();
                    const katText = String(row[11] || '').toLowerCase();
                    const detilText = String(row[12] || '').toLowerCase();
                    const notesText = String(row[13] || '').toLowerCase();
                    if (!kipText.includes(fSearchK) && !katText.includes(fSearchK) && !detilText.includes(fSearchK) && !notesText.includes(fSearchK)) return;
                }
                kipScopeAll++;
                if (isSanggahanDiterima(row)) kipScopeSgh++;
                else kipScopeNet++;
            });

            const pillsKip = document.getElementById('kipKpiSanggahanPills');
            if (pillsKip) {
                pillsKip.innerHTML = `
                    <span class="badge" style="background:#F1F5F9; color:#475569; font-weight:600; padding:3px 6px; font-size:0.65rem;" title="Total Tiket Sebelum Sanggahan">
                        All: <strong>${kipScopeAll}</strong>
                    </span>
                    <span class="badge" style="background:rgba(217,119,6,0.12); color:#B45309; font-weight:600; padding:3px 6px; font-size:0.65rem;" title="Sanggahan Diterima (Pengurang Kolom O)">
                        <i class="fa-solid fa-gavel me-1"></i>Sgh: <strong>-${kipScopeSgh}</strong>
                    </span>
                    <span class="badge" style="background:rgba(16,185,129,0.12); color:#047857; font-weight:600; padding:3px 6px; font-size:0.65rem;" title="Bad Tiket Bersih Setelah Sanggahan Diterima">
                        <i class="fa-solid fa-check-double me-1"></i>Net: <strong>${kipScopeNet}</strong>
                    </span>
                `;
            }
            if (elTotalKip) elTotalKip.innerText = totalUniqueKips.toLocaleString('id-ID');
            if (elTopKipName) { elTopKipName.innerText = topKipEntry[0]; elTopKipName.title = topKipEntry[0]; }
            if (elTopKipStat) elTopKipStat.innerText = `${topKipEntry[1].toLocaleString('id-ID')} tiket (${topKipPct}% kontribusi)`;
            if (elTopKatName) { elTopKatName.innerText = topKatEntry[0]; elTopKatName.title = topKatEntry[0]; }
            if (elTopKatStat) elTopKatStat.innerText = `${topKatEntry[1].toLocaleString('id-ID')} tiket (${topKatPct}% kontribusi)`;

            // Ekstraksi sintesis Detail Bad Ticket (Kolom M) dan Notes by Solver (Kolom N)
            const allDetails = [];
            const allNotes = [];
            kipCurrentFilteredRecords.forEach(r => {
                if (r[12] && r[12] !== '-') allDetails.push(r[12]);
                if (r[13] && r[13] !== '-') allNotes.push(maskNotesKolomN(r[13]));
            });

            const topDetailsSummary = summarizeKipTexts(allDetails, 3);
            const topNotesSummary = summarizeKipTexts(allNotes, 3);

            // Buat narasi eksekutif multi-pilar
            const top3KipNames = sortedKips.slice(0, 3).map(([k, cnt]) => `<strong>${k}</strong> (${cnt} tiket, ${((cnt / totalTickets) * 100).toFixed(0)}%)`).join(', ');

            let narrativeHtml = `
                <div class="mb-2">
                    <span class="fw-bold text-navy" style="font-size:0.95rem;">1. Konsentrasi Ketidaksesuaian KIP:</span><br>
                    Terdapat total <strong>${totalTickets.toLocaleString('id-ID')} temuan bad ticket</strong> yang tersebar pada <strong>${totalUniqueKips} KIP berbeda</strong>. Konsentrasi tertinggi terpusat pada: ${top3KipNames}.
                    Kategori ketidaksesuaian paling dominan adalah <strong>${topKatEntry[0]}</strong> sebesar ${topKatEntry[1].toLocaleString('id-ID')} tiket (${topKatPct}%).
                </div>
                <div class="mb-2">
                    <span class="fw-bold text-danger" style="font-size:0.95rem;">2. Rangkuman Detail Kesalahan (Kolom M):</span><br>
                    Pola kesalahan yang paling berulang diidentifikasi pada temuan solver meliputi:<br>
                    <ul class="mb-1 mt-1 ps-3" style="font-size:0.85rem;">
                        ${topDetailsSummary.map(item => `<li>${item}</li>`).join('')}
                    </ul>
                </div>
                <div>
                    <span class="fw-bold text-primary" style="font-size:0.95rem;">3. Rangkuman Arahan Solver (Kolom N):</span><br>
                    Catatan korektif dan instruksi tindak lanjut solver secara konsisten menekankan:<br>
                    <ul class="mb-0 mt-1 ps-3" style="font-size:0.85rem;">
                        ${topNotesSummary.map(item => `<li>${item}</li>`).join('')}
                    </ul>
                </div>
            `;

            if (narrativeBox) narrativeBox.innerHTML = narrativeHtml;

            // Simpan teks mentah untuk fitur salin ke clipboard
            lastKipExecutiveSummaryText = `INSIGHTS - BREAKDOWN KIP
Periode / Parameter: ${document.getElementById('kipExecFilterLabel')?.innerText || 'Aktif'}
- Total Tiket Temuan: ${totalTickets.toLocaleString('id-ID')} tiket
- Jumlah KIP Terdampak: ${totalUniqueKips} KIP
- KIP Terkritis (#1): ${topKipEntry[0]} (${topKipEntry[1]} tiket - ${topKipPct}%)
- Kategori Kesalahan Dominan: ${topKatEntry[0]} (${topKatEntry[1]} tiket - ${topKatPct}%)

AKAR MASALAH (KOLOM M - DETAIL BAD TIKET):
${topDetailsSummary.map(d => '- ' + d.replace(/<[^>]*>/g, '')).join('\n')}

ARAHAN SOLVER (KOLOM N - NOTES BY SOLVER):
${topNotesSummary.map(n => '- ' + n.replace(/<[^>]*>/g, '')).join('\n')}

REKOMENDASI ACTION:
1. Coaching & Briefing Prioritas untuk KIP: ${topKipEntry[0]}
2. Sosialisasi Standar Validasi untuk Kategori: ${topKatEntry[0]}
3. Pengetatan Verifikasi Tiket sebelum Eskalasi oleh Team Leader (TL)`;

            // Buat Rekomendasi Manajerial & Quick Action Items
            if (actionGrid) {
                actionGrid.innerHTML = `
                    <div class="col-md-4 col-12">
                        <div class="kip-action-card" style="border-left:4px solid #A30030;">
                            <div class="d-flex align-items-center gap-2 mb-2">
                                <span class="badge bg-danger-subtle text-danger fw-bold" style="font-size:0.75rem;">ACTION 1</span>
                                <span class="fw-bold text-navy small">Refreshment KIP Terkritis</span>
                            </div>
                            <p class="small text-muted mb-0" style="line-height:1.45;">
                                Lakukan sesi coaching kilat kepada agen untuk materi <strong>${topKipEntry[0]}</strong>. Fokuskan pada pemahaman naskah solusi dan parameter validasi.
                            </p>
                        </div>
                    </div>
                    <div class="col-md-4 col-12">
                        <div class="kip-action-card" style="border-left:4px solid #2563EB;">
                            <div class="d-flex align-items-center gap-2 mb-2">
                                <span class="badge bg-primary-subtle text-primary fw-bold" style="font-size:0.75rem;">ACTION 2</span>
                                <span class="fw-bold text-navy small">Standardisasi Validasi Input</span>
                            </div>
                            <p class="small text-muted mb-0" style="line-height:1.45;">
                                Wajibkan verifikasi checklist kelengkapan bukti (hasil ukur / kontak alternatif) untuk kategori <strong>${topKatEntry[0]}</strong> sebelum tiket dieskalasi ke solver.
                            </p>
                        </div>
                    </div>
                    <div class="col-md-4 col-12">
                        <div class="kip-action-card" style="border-left:4px solid #10B981;">
                            <div class="d-flex align-items-center gap-2 mb-2">
                                <span class="badge bg-success-subtle text-success fw-bold" style="font-size:0.75rem;">ACTION 3</span>
                                <span class="fw-bold text-navy small">Audit Berkala oleh Team Leader</span>
                            </div>
                            <p class="small text-muted mb-0" style="line-height:1.45;">
                                TL melakukan sampling berkala pada tiket-tiket yang mengacu pada 3 KIP teratas guna memastikan instruksi solver pada kolom notes telah diterapkan secara konsisten.
                            </p>
                        </div>
                    </div>
                `;
            }
        }

        function copyKipExecutiveSummary() {
            if (!lastKipExecutiveSummaryText) {
                alert('Tidak ada rangkuman yang tersedia untuk disalin.');
                return;
            }
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(lastKipExecutiveSummaryText).then(() => {
                    alert('Rangkuman Insights berhasil disalin ke clipboard!');
                }).catch(() => {
                    fallbackCopyText(lastKipExecutiveSummaryText);
                });
            } else {
                fallbackCopyText(lastKipExecutiveSummaryText);
            }
        }

        function fallbackCopyText(text) {
            const tempTextArea = document.createElement('textarea');
            tempTextArea.value = text;
            document.body.appendChild(tempTextArea);
            tempTextArea.select();
            document.execCommand('copy');
            document.body.removeChild(tempTextArea);
            alert('Rangkuman Insights berhasil disalin ke clipboard!');
        }

        function renderKipCharts(kipTotalMap, categoryTotalMap) {
            // Chart 1: Top 10 KIP Bar Chart Horizontal
            const sortedKips = Object.entries(kipTotalMap).sort((a, b) => b[1] - a[1]).slice(0, 10);
            const kipLabels = sortedKips.map(x => x[0].length > 28 ? x[0].substring(0, 26) + '...' : x[0]);
            const kipFullLabels = sortedKips.map(x => x[0]);
            const kipCounts = sortedKips.map(x => x[1]);

            if (activeCharts['topKip']) {
                activeCharts['topKip'].destroy();
            }

            const canvasTopKip = document.getElementById('chartTopKip');
            if (canvasTopKip) {
                const ctx = canvasTopKip.getContext('2d');
                activeCharts['topKip'] = new Chart(ctx, {
                    type: 'bar',
                    data: {
                        labels: kipLabels,
                        datasets: [{
                            label: 'Jumlah Tiket',
                            data: kipCounts,
                            backgroundColor: 'rgba(163, 0, 48, 0.82)',
                            hoverBackgroundColor: '#A30030',
                            borderRadius: 6,
                            borderSkipped: false
                        }]
                    },
                    options: {
                        indexAxis: 'y',
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { display: false },
                            tooltip: {
                                callbacks: {
                                    title: (ctx) => kipFullLabels[ctx[0].dataIndex] || '',
                                    label: (ctx) => `Jumlah Tiket: ${ctx.parsed.x} tiket`
                                }
                            },
                            datalabels: {
                                anchor: 'end',
                                align: 'end',
                                color: '#1E293B',
                                font: { weight: 'bold', size: 11 },
                                formatter: (val) => val > 0 ? val : ''
                            }
                        },
                        scales: {
                            x: {
                                beginAtZero: true,
                                grid: { color: 'rgba(226, 232, 240, 0.6)' },
                                ticks: { font: { size: 10 } }
                            },
                            y: {
                                grid: { display: false },
                                ticks: { font: { size: 11, weight: '500' } }
                            }
                        }
                    }
                });
            }

            // Chart 2: Category Breakdown Doughnut Chart
            const sortedCategories = Object.entries(categoryTotalMap).sort((a, b) => b[1] - a[1]);
            const catLabels = sortedCategories.map(x => x[0]);
            const catCounts = sortedCategories.map(x => x[1]);

            const palette = [
                '#A30030', '#2563EB', '#D97706', '#10B981', '#7C3AED',
                '#EC4899', '#0891B2', '#F59E0B', '#64748B', '#059669'
            ];

            if (activeCharts['kipCategories']) {
                activeCharts['kipCategories'].destroy();
            }

            const canvasCat = document.getElementById('chartKipCategories');
            if (canvasCat) {
                const ctxCat = canvasCat.getContext('2d');
                activeCharts['kipCategories'] = new Chart(ctxCat, {
                    type: 'doughnut',
                    data: {
                        labels: catLabels,
                        datasets: [{
                            data: catCounts,
                            backgroundColor: palette.slice(0, catLabels.length),
                            borderWidth: 2,
                            borderColor: '#FFFFFF'
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        cutout: '62%',
                        plugins: {
                            legend: {
                                position: 'right',
                                labels: {
                                    boxWidth: 12,
                                    font: { size: 11, weight: '500' }
                                }
                            },
                            tooltip: {
                                callbacks: {
                                    label: function(ctx) {
                                        const val = ctx.parsed || 0;
                                        const sum = ctx.dataset.data.reduce((a, b) => a + b, 0);
                                        const pct = sum > 0 ? ((val / sum) * 100).toFixed(1) : 0;
                                        return ` ${ctx.label}: ${val} tiket (${pct}%)`;
                                    }
                                }
                            },
                            datalabels: {
                                display: false
                            }
                        }
                    }
                });
            }
        }

        function handleKipTableSearch() {
            const searchVal = (document.getElementById('searchKipTable')?.value || '').trim().toLowerCase();
            if (!searchVal) {
                kipDisplayedData = [...kipAggregatedData];
            } else {
                kipDisplayedData = kipAggregatedData.filter(item => {
                    const kipMatch = item.kip.toLowerCase().includes(searchVal);
                    const katMatch = item.kategoriL.toLowerCase().includes(searchVal);
                    const detilMatch = item.details.some(d => d.toLowerCase().includes(searchVal));
                    const notesMatch = item.notes.some(n => n.toLowerCase().includes(searchVal));
                    return kipMatch || katMatch || detilMatch || notesMatch;
                });
            }
            kipCurrentPage = 1;
            renderKipTable();
        }

        function handleKipPageSizeChange() {
            const el = document.getElementById('kipTablePageSize');
            if (el) {
                kipPageSize = parseInt(el.value, 10) || 25;
            }
            kipCurrentPage = 1;
            renderKipTable();
        }

        function renderKipTable() {
            const tbody = document.getElementById('bodyKipBreakdown');
            const infoText = document.getElementById('kipTableCountInfo');
            const pagText = document.getElementById('kipPaginationText');
            const pagUl = document.getElementById('kipPaginationUl');
            if (!tbody) return;

            const totalRows = kipDisplayedData.length;
            if (infoText) {
                infoText.innerText = `Menampilkan ${totalRows.toLocaleString('id-ID')} kombinasi KIP & Kategori`;
            }

            if (totalRows === 0) {
                tbody.innerHTML = `<tr><td colspan="7" class="text-center py-4 text-muted"><i class="fa-regular fa-folder-open me-2"></i>Tidak ada data yang cocok dengan pencarian / filter.</td></tr>`;
                if (pagText) pagText.innerText = 'Menampilkan 0 dari 0 data';
                if (pagUl) pagUl.innerHTML = '';
                return;
            }

            const totalPages = Math.ceil(totalRows / kipPageSize) || 1;
            if (kipCurrentPage > totalPages) kipCurrentPage = totalPages;

            const startIdx = (kipCurrentPage - 1) * kipPageSize;
            const endIdx = Math.min(startIdx + kipPageSize, totalRows);
            const pageData = kipDisplayedData.slice(startIdx, endIdx);

            const totalTicketsInFiltered = kipCurrentFilteredRecords.length || 1;

            let htmlRows = '';
            pageData.forEach((row, idx) => {
                const globalIdx = startIdx + idx + 1;
                const pct = ((row.count / totalTicketsInFiltered) * 100).toFixed(1);

                let rankClass = 'kip-badge-rank-default';
                if (globalIdx === 1) rankClass = 'kip-badge-rank-1';
                else if (globalIdx === 2) rankClass = 'kip-badge-rank-2';
                else if (globalIdx === 3) rankClass = 'kip-badge-rank-3';

                const detailsSummarized = summarizeKipTexts(row.details, 2);
                const notesSummarized = summarizeKipTexts(row.notes, 2);

                const detailsHtml = detailsSummarized.map(d => `<div class="kip-tag-detail"><i class="fa-solid fa-circle-exclamation me-1" style="font-size:0.7rem;"></i>${d}</div>`).join('');
                const notesHtml = notesSummarized.map(n => `<div class="kip-tag-notes"><i class="fa-solid fa-comment-dots me-1" style="font-size:0.7rem;"></i>${n}</div>`).join('');

                const escapedKip = row.kip.replace(/'/g, "\\'");
                const escapedKat = row.kategoriL.replace(/'/g, "\\'");

                htmlRows += `
                    <tr>
                        <td class="text-center">
                            <span class="kip-badge-rank ${rankClass}">${globalIdx}</span>
                        </td>
                        <td>
                            <strong class="text-navy">${row.kip}</strong>
                        </td>
                        <td>
                            <span class="badge" style="background:rgba(163,0,48,0.08); color:#A30030; border:1px solid rgba(163,0,48,0.2); font-weight:600; font-size:0.76rem; border-radius:6px; padding:5px 8px;">
                                ${row.kategoriL}
                            </span>
                        </td>
                        <td class="text-center" style="min-width:130px;">
                            <div class="fw-bold text-navy" style="font-size:0.95rem;">${row.count.toLocaleString('id-ID')} <span class="text-muted small" style="font-size:0.74rem;">tiket</span></div>
                            <div class="progress mt-1" style="height:5px; background-color:#E2E8F0; border-radius:3px;">
                                <div class="progress-bar" style="width:${Math.min(pct * 2, 100)}%; background-color:#A30030;"></div>
                            </div>
                            <span class="text-muted" style="font-size:0.72rem;">${pct}% dari filter</span>
                        </td>
                        <td>
                            <div class="d-flex flex-column">${detailsHtml}</div>
                        </td>
                        <td>
                            <div class="d-flex flex-column">${notesHtml}</div>
                        </td>
                        <td class="text-center">
                            <button class="btn btn-sm btn-outline-danger fw-bold rounded-pill px-3 py-1 shadow-sm"
                                style="font-size:0.75rem;"
                                onclick="showKipPopupDetail('${escapedKip}', '${escapedKat}')">
                                <i class="fa-solid fa-list-ul me-1"></i> Lihat Tiket
                            </button>
                        </td>
                    </tr>
                `;
            });

            tbody.innerHTML = htmlRows;

            // Update Pagination UI
            if (pagText) {
                pagText.innerText = `Menampilkan ${startIdx + 1} - ${endIdx} dari ${totalRows.toLocaleString('id-ID')} data`;
            }

            if (pagUl) {
                let pagHtml = '';
                pagHtml += `<li class="page-item ${kipCurrentPage === 1 ? 'disabled' : ''}">
                    <a class="page-link" href="#" onclick="goToKipPage(${kipCurrentPage - 1}); return false;">&laquo;</a>
                </li>`;

                const startPage = Math.max(1, kipCurrentPage - 2);
                const endPage = Math.min(totalPages, startPage + 4);

                for (let p = startPage; p <= endPage; p++) {
                    pagHtml += `<li class="page-item ${p === kipCurrentPage ? 'active' : ''}">
                        <a class="page-link" href="#" onclick="goToKipPage(${p}); return false;">${p}</a>
                    </li>`;
                }

                pagHtml += `<li class="page-item ${kipCurrentPage === totalPages ? 'disabled' : ''}">
                    <a class="page-link" href="#" onclick="goToKipPage(${kipCurrentPage + 1}); return false;">&raquo;</a>
                </li>`;

                pagUl.innerHTML = pagHtml;
            }
        }

        function goToKipPage(pageNumber) {
            const totalPages = Math.ceil(kipDisplayedData.length / kipPageSize) || 1;
            if (pageNumber < 1 || pageNumber > totalPages) return;
            kipCurrentPage = pageNumber;
            renderKipTable();
        }

        function showKipPopupDetail(kipName, kategoriName) {
            const titleEl = document.getElementById('modalAgentTitle');
            if (titleEl) {
                titleEl.innerText = `Detail Bad Ticket - KIP: ${kipName} (${kategoriName})`;
            }

            const matchedTickets = kipCurrentFilteredRecords.filter(r => {
                const rKip = (r[10] && String(r[10]).trim() !== '') ? String(r[10]).trim() : '(Tanpa KIP)';
                const rKat = (r[11] && String(r[11]).trim() !== '') ? String(r[11]).trim() : '(Tanpa Kategori)';
                return rKip === kipName && rKat === kategoriName;
            });

            const countEl = document.getElementById('modalTotalCount');
            if (countEl) countEl.innerText = `Total: ${matchedTickets.length} tiket`;

            const tbody = document.getElementById('modalTableBody');
            if (tbody) {
                tbody.innerHTML = '';
                matchedTickets.forEach(row => {
                    const tr = document.createElement('tr');
                    tr.innerHTML = `
                        <td>${row[3] || '-'}</td>
                        <td>${row[5] || '-'}</td>
                        <td><strong>${row[6] || '-'}</strong></td>
                        <td>${row[7] || '-'}</td>
                        <td>${row[8] || '-'}</td>
                        <td>${row[9] || '-'}</td>
                        <td>${row[4] || '-'}</td>
                        <td><span class="badge bg-dark">${row[10] || '-'}</span></td>
                        <td><span class="text-danger fw-bold">${row[11] || '-'}</span></td>
                        <td class="col-detil-m"><small>${row[12] || '-'}</small></td>
                        <td class="col-notes-n"><small>${maskNotesKolomN(row[13]) || '-'}</small></td>
                        <td>${isSanggahanDiterima(row) ? '<span class="badge bg-success" style="font-size:0.7rem;"><i class="fa-solid fa-circle-check me-1"></i>SANGGAHAN DITERIMA</span>' : (row[14] || '-')}</td>
                        <td>${row[15] || '-'}</td>
                    `;
                    tbody.appendChild(tr);
                });
            }

            applyAgentDetailColumnVisibility();
            agentModalBootstrap.show();
        }

        function downloadKipBreakdownExcel() {
            if (!kipDisplayedData || kipDisplayedData.length === 0) {
                alert('Tidak ada data KIP yang tersedia untuk diunduh.');
                return;
            }

            ensureXLSXLibrary(function () {
                const headers = [
                    'No',
                    'KIP (Kolom K)',
                    'Kategori Bad Ticket (Kolom L)',
                    'Jumlah Tiket',
                    'Persentase Kontribusi (%)',
                    'Ringkasan Detail Bad Ticket (Kolom M)',
                    'Ringkasan Notes by Solver (Kolom N)'
                ];

                const totalFiltered = kipCurrentFilteredRecords.length || 1;
                const rows = kipDisplayedData.map((row, idx) => {
                    const pct = ((row.count / totalFiltered) * 100).toFixed(1) + '%';
                    const detilPlain = summarizeKipTexts(row.details, 3).map(s => s.replace(/<[^>]*>/g, '')).join('; ');
                    const notesPlain = summarizeKipTexts(row.notes, 3).map(s => s.replace(/<[^>]*>/g, '')).join('; ');

                    return [
                        idx + 1,
                        row.kip,
                        row.kategoriL,
                        row.count,
                        pct,
                        detilPlain,
                        notesPlain
                    ];
                });

                const worksheet = XLSX.utils.aoa_to_sheet([headers, ...rows]);
                worksheet['!cols'] = [
                    { wch: 6 },
                    { wch: 32 },
                    { wch: 28 },
                    { wch: 14 },
                    { wch: 24 },
                    { wch: 45 },
                    { wch: 45 }
                ];

                const workbook = XLSX.utils.book_new();
                XLSX.utils.book_append_sheet(workbook, worksheet, 'Breakdown KIP');

                const tz = new Date();
                const stamp = `${tz.getFullYear()}${String(tz.getMonth() + 1).padStart(2, '0')}${String(tz.getDate()).padStart(2, '0')}_${String(tz.getHours()).padStart(2, '0')}${String(tz.getMinutes()).padStart(2, '0')}`;
                XLSX.writeFile(workbook, `Breakdown_KIP_${stamp}.xlsx`);
            });
        }

    </script>
</body>

</html>